}

"use client";

// ORCALY_OWNER_SUPPORT_CONTROL_V1

import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import { supabase } from "@/lib/supabase";

type Json = Record<string, any>;
type Tab =
  | "overview"
  | "partners"
  | "referrals"
  | "commissions"
  | "payouts"
  | "ranking";

async function currentToken() {
  const { data } = await supabase.auth.getSession();
  return data.session?.access_token || "";
}

function money(value: unknown) {
  if (value === null || value === undefined) {
    return "Protegido";
  }

  return Number(value || 0).toLocaleString(
    "pt-BR",
    {
      style: "currency",
      currency: "BRL",
    },
  );
}

function dateTime(value: unknown) {
  if (!value) return "—";
  const parsed = new Date(String(value));
  if (Number.isNaN(parsed.getTime())) return "—";

  return new Intl.DateTimeFormat("pt-BR", {
    dateStyle: "short",
    timeStyle: "short",
  }).format(parsed);
}

function referralStatus(value: unknown) {
  const status = String(value || "");
  const labels: Record<string, string> = {
    registered: "Cadastrada",
    trial: "Em teste grátis",
    payment_pending: "Aguardando pagamento",
    qualified: "Pagamento confirmado",
    customer_active: "Cliente ativo",
    customer_cancelled: "Cliente cancelado",
    rejected: "Recusada",
    reversed: "Estornada",
  };

  return labels[status] || status || "Sem status";
}

function reviewStatus(value: unknown) {
  const status = String(value || "pending");
  const labels: Record<string, string> = {
    pending: "Aguardando análise",
    approved: "Aprovada",
    rejected: "Recusada",
    flagged: "Sinalizada",
  };

  return labels[status] || status;
}

function commissionStatus(value: unknown) {
  const status = String(value || "");
  const labels: Record<string, string> = {
    future: "Futura",
    hold: "Em retenção",
    available: "Disponível",
    processing: "Em pagamento",
    paid: "Paga",
    reversed: "Estornada",
    rejected: "Rejeitada",
  };

  return labels[status] || status || "Sem status";
}

function payoutStatus(value: unknown) {
  const status = String(value || "");
  const labels: Record<string, string> = {
    requested: "Solicitado",
    approved: "Aprovado",
    processing: "Processando",
    paid: "Pago",
    failed: "Falhou",
    cancelled: "Cancelado",
  };

  return labels[status] || status || "Sem status";
}

function phoneLink(value: unknown) {
  const digits = String(value || "").replace(/\D/g, "");
  if (!digits) return "";
  return `https://wa.me/${
    digits.startsWith("55") ? digits : `55${digits}`
  }`;
}

function Badge({
  value,
  tone = "blue",
}: {
  value: string;
  tone?: "blue" | "green" | "amber" | "red" | "violet";
}) {
  const tones = {
    blue: "bg-blue-50 text-[#05245c]",
    green: "bg-emerald-50 text-emerald-700",
    amber: "bg-amber-50 text-amber-700",
    red: "bg-red-50 text-red-700",
    violet: "bg-violet-50 text-violet-700",
  };

  return (
    <span
      className={`inline-flex rounded-full px-3 py-1.5 text-[10px] font-black uppercase tracking-[0.08em] ${tones[tone]}`}
    >
      {value}
    </span>
  );
}

export default function AdminIndicacoesPage() {
  const router = useRouter();
  const [data, setData] =
    useState<Json | null>(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [tab, setTab] =
    useState<Tab>("overview");
  const [search, setSearch] = useState("");
  const [reviewTarget, setReviewTarget] =
    useState<Json | null>(null);
  const [reviewDecision, setReviewDecision] =
    useState<"approved" | "rejected" | "flagged">(
      "approved",
    );
  const [reviewNote, setReviewNote] =
    useState("");
  const [revealedPix, setRevealedPix] =
    useState<Json | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError("");

    const token = await currentToken();

    if (!token) {
      router.replace("/admin/login");
      return;
    }

    const response = await fetch(
      "/api/admin/affiliates",
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        cache: "no-store",
      },
    );

    const payload = await response
      .json()
      .catch(() => ({}));

    if (!response.ok) {
      if ([401, 403].includes(response.status)) {
        router.replace("/admin");
        return;
      }

      setError(
        payload.error ||
          "Não foi possível carregar o programa de parceiros.",
      );
    } else {
      setData(payload);
    }

    setLoading(false);
  }, [router]);

  useEffect(() => {
    void load();
  }, [load]);

  async function action(
    actionName: string,
    body: Record<string, unknown>,
    options: {
      reload?: boolean;
      success?: string;
    } = {},
  ) {
    const key = `${actionName}:${
      body.referralId ||
      body.affiliateId ||
      body.payoutId ||
      body.commissionId ||
      ""
    }`;

    setBusy(key);
    setError("");
    setMessage("");

    const token = await currentToken();
    const response = await fetch(
      "/api/admin/affiliates",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          action: actionName,
          ...body,
        }),
      },
    );

    const payload = await response
      .json()
      .catch(() => ({}));

    if (!response.ok) {
      setError(
        payload.error ||
          "Não foi possível concluir a operação.",
      );
      setBusy("");
      return null;
    }

    setMessage(
      options.success ||
        "Operação concluída com segurança.",
    );
    setBusy("");

    if (options.reload !== false) {
      await load();
    }

    return payload;
  }

  async function submitReview() {
    if (!reviewTarget?.id) return;

    const result = await action(
      "review_referral",
      {
        referralId: reviewTarget.id,
        decision: reviewDecision,
        note: reviewNote,
      },
      {
        success:
          reviewDecision === "approved"
            ? "Indicação aprovada."
            : reviewDecision === "rejected"
              ? "Indicação recusada e valores elegíveis revertidos."
              : "Indicação marcada para análise.",
      },
    );

    if (result) {
      setReviewTarget(null);
      setReviewNote("");
      setReviewDecision("approved");
    }
  }

  async function revealPix(profile: Json) {
    const result = await action(
      "reveal_pix",
      {
        affiliateId: profile.id,
      },
      {
        reload: false,
        success:
          "Chave Pix revelada e ação registrada na auditoria.",
      },
    );

    if (result) {
      setRevealedPix({
        ...result,
        affiliateName: profile.name,
      });
    }
  }

  const capabilities =
    data?.capabilities || {};
  const isOwner =
    data?.admin?.role === "owner";

  const profiles = useMemo(
    () => data?.profiles || [],
    [data],
  );
  const referrals = useMemo(
    () => data?.referrals || [],
    [data],
  );
  const commissions = useMemo(
    () => data?.commissions || [],
    [data],
  );
  const payouts = useMemo(
    () => data?.payouts || [],
    [data],
  );

  const partnerMap = useMemo<Map<string, Json>>(
    () =>
      new Map<string, Json>(
        profiles.map(
          (profile: Json): [string, Json] => [
            String(profile.id),
            profile,
          ],
        ),
      ),
    [profiles],
  );

  const filteredProfiles = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return profiles;

    return profiles.filter((profile: Json) =>
      [
        profile.name,
        profile.email,
        profile.whatsapp,
        profile.code,
      ].some((value) =>
        String(value || "")
          .toLowerCase()
          .includes(query),
      ),
    );
  }, [profiles, search]);

  const filteredReferrals = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return referrals;

    return referrals.filter((row: Json) =>
      [
        row.referral_code,
        row.customer_name_masked,
        row.customer_email_masked,
        row.lead?.nome_responsavel,
        row.lead?.empresa_nome,
        row.lead?.email,
        row.company?.nome,
        row.company?.email,
      ].some((value) =>
        String(value || "")
          .toLowerCase()
          .includes(query),
      ),
    );
  }, [referrals, search]);

  const pendingReviews = useMemo(
    () =>
      referrals.filter(
        (row: Json) =>
          ["pending", "flagged"].includes(
            String(row.review_status || "pending"),
          ),
      ),
    [referrals],
  );

  const pendingPix = useMemo(
    () =>
      profiles.filter(
        (profile: Json) =>
          profile.payoutAccount &&
          !profile.payoutAccount.is_verified,
      ),
    [profiles],
  );

  const pendingPayouts = useMemo(
    () =>
      payouts.filter((row: Json) =>
        ["requested", "approved", "processing"].includes(
          String(row.status),
        ),
      ),
    [payouts],
  );

  if (loading) {
    return (
      <main className="grid min-h-screen place-items-center bg-[#eef3f9] text-[#071b3a]">
        <div className="text-center">
          <div className="mx-auto h-10 w-10 animate-spin rounded-full border-4 border-blue-100 border-t-[#05245c]" />
          <p className="mt-4 font-black">
            Carregando controle de parceiros...
          </p>
        </div>
      </main>
    );
  }

  if (!data) {
    return (
      <main className="grid min-h-screen place-items-center bg-[#eef3f9] p-4">
        <section className="max-w-md rounded-[1.8rem] bg-white p-7 text-center shadow-xl">
          <p className="font-black text-red-700">
            {error || "Área indisponível."}
          </p>
          <Link
            href="/admin"
            className="mt-5 inline-flex rounded-2xl bg-[#05245c] px-5 py-3 font-black text-white"
          >
            Voltar ao controle
          </Link>
        </section>
      </main>
    );
  }

  const summary = data.summary || {};
  const ranking = data.ranking || {
    top: [],
  };

  const navigation: Array<{
    id: Tab;
    label: string;
    count?: number;
    visible: boolean;
  }> = [
    {
      id: "overview",
      label: "Visão geral",
      visible: true,
    },
    {
      id: "partners",
      label: "Parceiros",
      count: profiles.length,
      visible: true,
    },
    {
      id: "referrals",
      label: "Indicações",
      count: referrals.length,
      visible: Boolean(capabilities["referrals.view"]),
    },
    {
      id: "commissions",
      label: "Comissões",
      count: commissions.length,
      visible: Boolean(
        capabilities["commissions.view"],
      ),
    },
    {
      id: "payouts",
      label: "Pagamentos",
      count: payouts.length,
      visible: Boolean(capabilities["payouts.view"]),
    },
    {
      id: "ranking",
      label: "Destaques",
      visible: true,
    },
  ];

