export async function POST(request: NextRequest) {
  const admin = await requireAdmin(request)

  if (!admin.ok) {
    return NextResponse.json({ error: admin.error }, { status: admin.status })
  }

  const body = await request.json()
  const leadId = String(body.lead_id || '')
  const action = String(body.action || 'mark_sent')
  const message = String(body.message || '')

  if (!leadId) {
    return NextResponse.json({ error: 'lead_id ausente' }, { status: 400 })
  }

  if (action === 'opt_out') {
    const { error } = await admin.supabaseAdmin
      .from('signup_leads')
      .update({
        status: 'opt_out',
        next_followup_at: null,
      })
      .eq('id', leadId)

    if (error) return NextResponse.json({ error: error.message }, { status: 500 })

    return NextResponse.json({ ok: true })
  }

  if (action === 'lost') {
    const { error } = await admin.supabaseAdmin
      .from('signup_leads')
      .update({
        status: 'perdido',
        next_followup_at: null,
      })
      .eq('id', leadId)

    if (error) return NextResponse.json({ error: error.message }, { status: 500 })

    return NextResponse.json({ ok: true })
  }

  const { data: lead, error: leadError } = await admin.supabaseAdmin
    .from('signup_leads')
    .select('*')
    .eq('id', leadId)
    .single()

  if (leadError) {
    return NextResponse.json({ error: leadError.message }, { status: 500 })
  }

  const nextCount = Number(lead.followup_count || 0) + 1

  await admin.supabaseAdmin.from('signup_lead_followups').insert({
    lead_id: leadId,
    channel: 'whatsapp',
    status: 'enviado_manual',
    message,
    sent_at: new Date().toISOString(),
    admin_email: admin.email,
  })

  const { error } = await admin.supabaseAdmin
    .from('signup_leads')
    .update({
      followup_count: nextCount,
      last_followup_at: new Date().toISOString(),
      next_followup_at: nextCount >= 3 ? null : new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
      status: lead.status === 'lead' ? 'checkout_criado' : lead.status,
    })
    .eq('id', leadId)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  return NextResponse.json({ ok: true })
}

import { timingSafeEqual } from 'node:crypto'
import { NextRequest, NextResponse } from 'next/server'
import { auditLog, can, fail, getCurrentAdmin, supabaseAdmin } from '@/lib/admin-auth'

type Severity = 'baixa' | 'media' | 'alta' | 'critica'

function isBlank(value: any) {
  return value === null || value === undefined || String(value).trim() === ''
}

function daysAgo(value: any) {
  if (!value) return 9999
  return Math.floor((Date.now() - new Date(value).getTime()) / (1000 * 60 * 60 * 24))
}

function daysUntil(value: any) {
  if (!value) return null
  return Math.ceil((new Date(value).getTime() - Date.now()) / (1000 * 60 * 60 * 24))
}

function safe(value: string) {
  return String(value || '').replace(/'/g, "''")
}

function issue(args: {
  code: string
  title: string
  description: string
  severity: Severity
  area: string
  entityType?: string
  entityId?: string
  entityLabel?: string
  affectedTable?: string
  affectedField?: string
  suggestedAction?: string
  fixSteps?: string[]
  fixSql?: string
  fixRoute?: string
  autoFixable?: boolean
  metadata?: any
}) {
  return {
    code: args.code,
    title: args.title,
    description: args.description,
    severity: args.severity,
    area: args.area,
    entity_type: args.entityType || null,
    entity_id: args.entityId || null,
    entity_label: args.entityLabel || null,
    affected_table: args.affectedTable || null,
    affected_field: args.affectedField || null,
    suggested_action: args.suggestedAction || null,
    fix_steps: args.fixSteps || [],
    fix_sql: args.fixSql || null,
    fix_route: args.fixRoute || null,
    auto_fixable: Boolean(args.autoFixable),
    metadata: args.metadata || {},
  }
}

async function dataOrEmpty(query: any) {
  const { data, error } = await query
  if (error) return []
  return data || []
}

async function saveIssues(issues: any[]) {
  for (const item of issues) {
    const { data: existing } = await supabaseAdmin
      .from('admin_bug_reports')
      .select('id,occurrences,status')
      .eq('code', item.code)
      .maybeSingle()

    if (existing?.id) {
      await supabaseAdmin
        .from('admin_bug_reports')
        .update({
          title: item.title,
          description: item.description,
          severity: item.severity,
          area: item.area,
          entity_type: item.entity_type,
          entity_id: item.entity_id,
          entity_label: item.entity_label,
          affected_table: item.affected_table,
          affected_field: item.affected_field,
          suggested_action: item.suggested_action,
          fix_steps: item.fix_steps,
          fix_sql: item.fix_sql,
          fix_route: item.fix_route,
          auto_fixable: item.auto_fixable,
          metadata: item.metadata,
          last_seen_at: new Date().toISOString(),
          occurrences: Number(existing.occurrences || 0) + 1,
          status: existing.status === 'resolvido' || existing.status === 'ignorado' ? 'aberto' : existing.status,
        })
        .eq('id', existing.id)
    } else {
      await supabaseAdmin.from('admin_bug_reports').insert(item)
    }
  }
}

function isCronRequest(request: NextRequest) {
  const secret = String(process.env.CRON_SECRET || '')
  const header = String(request.headers.get('authorization') || '')
  const expected = `Bearer ${secret}`

  if (!secret || header.length !== expected.length) return false

  return timingSafeEqual(
    Buffer.from(header),
    Buffer.from(expected),
  )
}

export async function GET(request: NextRequest) {
  try {
    if (isCronRequest(request)) return POST(request)
    const admin = await getCurrentAdmin(request)
    if (!admin) return fail('Acesso negado.', 403)
    if (!can(admin, 'audit.view')) return fail('Sem permissão para visualizar o scanner.', 403)

    const [bugs, runs] = await Promise.all([
      dataOrEmpty(supabaseAdmin.from('admin_bug_reports').select('*').order('last_seen_at', { ascending: false }).limit(300)),
      dataOrEmpty(supabaseAdmin.from('admin_scan_runs').select('*').order('started_at', { ascending: false }).limit(50)),
    ])

    return NextResponse.json({ bugs, runs })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro ao carregar scanner.' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const startedAt = new Date().toISOString()
  let runId: string | null = null

  try {
    const cronRequest = isCronRequest(request)
    const admin = cronRequest ? null : await getCurrentAdmin(request)

    if (!cronRequest && !admin) return fail('Acesso negado.', 403)
    if (!cronRequest && admin && !can(admin, 'system.scan')) {
      return fail('Sem permissão para rodar scanner.', 403)
    }

    const actorEmail = cronRequest
      ? 'cron@orcaly.system'
      : admin?.email || 'system@orcaly.local'

    const { data: run } = await supabaseAdmin
      .from('admin_scan_runs')
      .insert({
        status: 'rodando',
        started_at: startedAt,
        created_by: actorEmail,
      })
      .select('id')
      .single()

    runId = run?.id || null

    const [
      companies,
      orders,
      products,
      proposals,
      leads,
      finance,
      members,
      bugsOpen,
      usersResult,
    ] = await Promise.all([
      dataOrEmpty(supabaseAdmin.from('companies').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('orders').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('products').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('proposals').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('signup_leads').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('financial_transactions').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('company_members').select('*').limit(1000)),
      dataOrEmpty(supabaseAdmin.from('admin_bug_reports').select('*').in('status', ['aberto', 'em_analise']).limit(1000)),
      supabaseAdmin.auth.admin.listUsers({ page: 1, perPage: 1000 }),
    ])

    const users = usersResult?.data?.users || []
    const issues: any[] = []
    const companyIds = new Set(companies.map((c: any) => c.id))
    const ownerIds = new Set(companies.map((c: any) => c.owner_id).filter(Boolean))
    const memberUserIds = new Set(members.map((m: any) => m.user_id).filter(Boolean))

    const slugMap = new Map<string, any[]>()
    companies.forEach((company: any) => {
      const slug = String(company.slug || '').trim().toLowerCase()
      if (!slug) return
      slugMap.set(slug, [...(slugMap.get(slug) || []), company])
    })

    const subMap = new Map<string, any[]>()
    companies.forEach((company: any) => {
      const sub = String(company.subdomain_slug || '').trim().toLowerCase()
      if (!sub) return
      subMap.set(sub, [...(subMap.get(sub) || []), company])
    })

    companies.forEach((company: any) => {
      const label = company.nome || company.slug || company.id
      const exp = daysUntil(company.assinatura_expira_em)

      if (isBlank(company.owner_id) && isBlank(company.tester_id)) {
        issues.push(issue({
          code: `company:${company.id}:no-owner`,
          title: 'Empresa sem dono vinculado',
          description: `A empresa "${label}" não possui owner_id nem tester_id. Isso pode impedir o login de acessar o painel.`,
          severity: 'critica',
          area: 'empresas',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'owner_id',
          suggestedAction: 'Vincular a empresa ao usuário correto pelo campo owner_id.',
          fixRoute: '/admin?tab=empresas',
          fixSteps: [
            'Abra a aba Empresas no Admin.',
            'Identifique quem deve ser o dono da empresa.',
            'Copie o ID do usuário correto na aba Usuários.',
            'Atualize owner_id da empresa no Supabase ou crie uma ação admin para vincular dono.',
          ],
          fixSql: `update public.companies set owner_id = 'COLE_O_USER_ID_AQUI' where id = '${company.id}';`,
        }))
      }

      if (isBlank(company.slug)) {
        issues.push(issue({
          code: `company:${company.id}:no-slug`,
          title: 'Empresa sem slug',
          description: `A empresa "${label}" não possui slug. Links públicos e rotas por empresa podem falhar.`,
          severity: 'alta',
          area: 'site',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'slug',
          suggestedAction: 'Criar um slug único para a empresa.',
          fixSteps: [
            'Defina um slug curto, sem espaços e sem acentos.',
            'Confira se não existe outra empresa usando o mesmo slug.',
            'Atualize o campo slug da empresa.',
          ],
          fixSql: `update public.companies set slug = 'novo-slug' where id = '${company.id}';`,
        }))
      }

      if (isBlank(company.whatsapp)) {
        issues.push(issue({
          code: `company:${company.id}:no-whatsapp`,
          title: 'Empresa sem WhatsApp',
          description: `A empresa "${label}" está sem WhatsApp. Botões de contato, propostas e pedidos podem ficar incompletos.`,
          severity: 'media',
          area: 'empresas',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'whatsapp',
          suggestedAction: 'Cadastrar o WhatsApp nas configurações da empresa.',
          fixRoute: '/painel/configuracoes',
          fixSteps: [
            'Entrar no painel da empresa.',
            'Abrir Configurações.',
            'Preencher o WhatsApp no bloco Dados da empresa.',
            'Salvar alterações.',
          ],
          fixSql: `update public.companies set whatsapp = '5582999999999' where id = '${company.id}';`,
        }))
      }

      if (isBlank(company.pix_key)) {
        issues.push(issue({
          code: `company:${company.id}:no-pix`,
          title: 'Empresa sem PIX configurado',
          description: `A empresa "${label}" está sem chave PIX. Propostas podem sair sem instrução de pagamento.`,
          severity: 'media',
          area: 'financeiro',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'pix_key',
          suggestedAction: 'Cadastrar chave PIX em Configurações > Recebimento.',
          fixRoute: '/painel/configuracoes',
          fixSteps: [
            'Abrir Configurações da empresa.',
            'Entrar na aba Recebimento.',
            'Preencher tipo da chave, chave PIX, nome e cidade do recebedor.',
            'Salvar alterações.',
          ],
          fixSql: `update public.companies set pix_key = 'COLE_A_CHAVE_PIX_AQUI' where id = '${company.id}';`,
        }))
      }

      if (company.assinatura_status === 'ativa' && exp !== null && exp < 0) {
        issues.push(issue({
          code: `company:${company.id}:subscription-expired`,
          title: 'Assinatura ativa vencida',
          description: `A empresa "${label}" está como ativa, mas a assinatura venceu há ${Math.abs(exp)} dia(s).`,
          severity: 'alta',
          area: 'assinatura',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'assinatura_expira_em',
          suggestedAction: 'Renovar por +30 dias ou bloquear a empresa.',
          fixSteps: [
            'Se o cliente pagou, clique em Adicionar +30 dias na aba Empresas.',
            'Se não pagou, bloqueie a empresa.',
            'Confira se o webhook do Mercado Pago está atualizando renovações.',
          ],
          fixSql: `update public.companies set assinatura_expira_em = now() + interval '30 days', ativo = true, assinatura_status = 'ativa' where id = '${company.id}';`,
          autoFixable: true,
        }))
      }

      if (company.ativo === false && company.assinatura_status === 'ativa') {
        issues.push(issue({
          code: `company:${company.id}:active-plan-blocked`,
          title: 'Empresa bloqueada com assinatura ativa',
          description: `A empresa "${label}" está bloqueada, mas a assinatura aparece como ativa.`,
          severity: 'media',
          area: 'assinatura',
          entityType: 'company',
          entityId: company.id,
          entityLabel: label,
          affectedTable: 'companies',
          affectedField: 'ativo',
          suggestedAction: 'Desbloquear empresa ou alterar status da assinatura.',
          fixSteps: [
            'Verifique se o bloqueio foi manual.',
            'Se a assinatura estiver paga, desbloqueie a empresa.',
            'Se não estiver paga, mude assinatura_status para bloqueada/pendente.',
          ],
          fixSql: `update public.companies set ativo = true where id = '${company.id}';`,
          autoFixable: true,
        }))
      }
    })

    slugMap.forEach((list, slug) => {
      if (list.length > 1) {
        issues.push(issue({
          code: `slug:duplicate:${slug}`,
          title: 'Slug duplicado',
          description: `O slug "${slug}" está sendo usado por ${list.length} empresas. Isso pode quebrar links públicos e consultas por empresa.`,
          severity: 'critica',
          area: 'site',
          entityType: 'slug',
          entityId: slug,
          entityLabel: slug,
          affectedTable: 'companies',
          affectedField: 'slug',
          suggestedAction: 'Alterar o slug das empresas duplicadas, mantendo apenas uma com esse valor.',
          fixSteps: [
            'Abra a aba Empresas.',
            'Pesquise pelo slug duplicado.',
            'Escolha qual empresa deve manter o slug atual.',
            'Altere o slug das demais empresas para valores únicos.',
          ],
          metadata: { companies: list.map((c: any) => ({ id: c.id, nome: c.nome })) },
        }))
      }
    })

    subMap.forEach((list, sub) => {
      if (list.length > 1) {
        issues.push(issue({
          code: `subdomain:duplicate:${sub}`,
          title: 'Subdomínio duplicado',
          description: `O subdomínio "${sub}" está sendo usado por ${list.length} empresas.`,
          severity: 'critica',
          area: 'site',
          entityType: 'subdomain',
          entityId: sub,
          entityLabel: sub,
          affectedTable: 'companies',
          affectedField: 'subdomain_slug',
          suggestedAction: 'Alterar o subdomínio das empresas duplicadas.',
          fixSteps: [
            'Abra a aba Empresas.',
            'Identifique as empresas com o mesmo subdomínio.',
            'Mantenha o subdomínio em uma empresa.',
            'Altere subdomain_slug das demais.',
          ],
          metadata: { companies: list.map((c: any) => ({ id: c.id, nome: c.nome })) },
        }))
      }
    })

    users.forEach((user: any) => {
      if (!ownerIds.has(user.id) && !memberUserIds.has(user.id)) {
        issues.push(issue({
          code: `user:${user.id}:orphan`,
          title: 'Usuário sem empresa',
          description: `O usuário "${user.email}" existe no Auth, mas não é dono nem funcionário de nenhuma empresa.`,
          severity: 'media',
          area: 'usuários',
          entityType: 'user',
          entityId: user.id,
          entityLabel: user.email,
          affectedTable: 'auth.users',
          affectedField: 'id',
          suggestedAction: 'Vincular o usuário a uma empresa ou remover se for cadastro abandonado.',
          fixSteps: [
            'Verifique se o usuário deveria ser dono de alguma empresa.',
            'Se sim, copie o ID dele e salve em companies.owner_id.',
            'Se era teste/cadastro abandonado, considere remover no Supabase Auth.',
          ],
          fixSql: `update public.companies set owner_id = '${user.id}' where id = 'COLE_O_ID_DA_EMPRESA_AQUI';`,
        }))
      }

      if (!user.confirmed_at) {
        issues.push(issue({
          code: `user:${user.id}:not-confirmed`,
          title: 'Usuário não confirmado',
          description: `O usuário "${user.email}" ainda não confirmou o e-mail.`,
          severity: 'baixa',
          area: 'usuários',
          entityType: 'user',
          entityId: user.id,
          entityLabel: user.email,
          affectedTable: 'auth.users',
          affectedField: 'confirmed_at',
          suggestedAction: 'Confirmar e-mail manualmente ou pedir para o usuário acessar o link de confirmação.',
          fixSteps: [
            'Abra Supabase Auth > Users.',
            'Pesquise pelo e-mail.',
            'Confirme manualmente se for usuário válido.',
          ],
        }))
      }
    })

    orders.forEach((order: any) => {
      const label = order.nome || order.produto || order.id

      if (!companyIds.has(order.company_id)) {
        issues.push(issue({
          code: `order:${order.id}:invalid-company`,
          title: 'Pedido sem empresa válida',
          description: `O pedido "${label}" aponta para uma empresa inexistente.`,
          severity: 'critica',
          area: 'pedidos',
          entityType: 'order',
          entityId: order.id,
          entityLabel: label,
          affectedTable: 'orders',
          affectedField: 'company_id',
          suggestedAction: 'Corrigir company_id ou remover o pedido órfão.',
          fixSteps: [
            'Verifique de qual empresa esse pedido deveria ser.',
            'Atualize company_id para o ID correto.',
            'Se for lixo/teste, remova o pedido.',
          ],
          fixSql: `update public.orders set company_id = 'COLE_O_ID_DA_EMPRESA_AQUI' where id = '${order.id}';`,
        }))
      }

      if (isBlank(order.telefone)) {
        issues.push(issue({
          code: `order:${order.id}:no-phone`,
          title: 'Pedido sem telefone',
          description: `O pedido "${label}" está sem telefone. O WhatsApp e o acompanhamento do cliente ficam prejudicados.`,
          severity: 'media',
          area: 'pedidos',
          entityType: 'order',
          entityId: order.id,
          entityLabel: label,
          affectedTable: 'orders',
          affectedField: 'telefone',
          suggestedAction: 'Adicionar telefone ao pedido ou ajustar o formulário para exigir telefone.',
          fixSteps: [
            'Abra o pedido no painel.',
            'Peça o telefone ao cliente, se necessário.',
            'Atualize o campo telefone.',
            'Revise se o formulário público está exigindo telefone.',
          ],
          fixSql: `update public.orders set telefone = '5582999999999' where id = '${order.id}';`,
        }))
      }

      if (isBlank(order.produto)) {
        issues.push(issue({
          code: `order:${order.id}:no-product`,
          title: 'Pedido sem produto',
          description: `O pedido "${label}" não tem produto ou serviço informado.`,
          severity: 'media',
          area: 'pedidos',
          entityType: 'order',
          entityId: order.id,
          entityLabel: label,
          affectedTable: 'orders',
          affectedField: 'produto',
          suggestedAction: 'Corrigir produto do pedido e revisar o formulário público.',
          fixSteps: [
            'Abra o pedido no painel.',
            'Identifique o produto/serviço solicitado.',
            'Atualize o campo produto.',
            'Revise a página pública de orçamento.',
          ],
          fixSql: `update public.orders set produto = 'Produto informado manualmente' where id = '${order.id}';`,
        }))
      }

      if (!['Entregue', 'Pronto'].includes(order.status) && daysAgo(order.created_at) > 15) {
        issues.push(issue({
          code: `order:${order.id}:stale`,
          title: 'Pedido parado há muitos dias',
          description: `O pedido "${label}" está há mais de 15 dias sem ser marcado como Pronto ou Entregue.`,
          severity: 'media',
          area: 'pedidos',
          entityType: 'order',
          entityId: order.id,
          entityLabel: label,
          affectedTable: 'orders',
          affectedField: 'status',
          suggestedAction: 'Verificar produção e atualizar status.',
          fixSteps: [
            'Abra o painel de pedidos.',
            'Confira se o pedido foi entregue ou finalizado.',
            'Atualize o status correto.',
            'Se o cliente sumiu, crie follow-up no Mini-CRM.',
          ],
          fixSql: `update public.orders set status = 'Entregue' where id = '${order.id}';`,
        }))
      }
    })

    products.forEach((product: any) => {
      const label = product.nome || product.id

      if (!companyIds.has(product.company_id)) {
        issues.push(issue({
          code: `product:${product.id}:invalid-company`,
          title: 'Produto sem empresa válida',
          description: `O produto "${label}" aponta para empresa inexistente.`,
          severity: 'alta',
          area: 'catálogo',
          entityType: 'product',
          entityId: product.id,
          entityLabel: label,
          affectedTable: 'products',
          affectedField: 'company_id',
          suggestedAction: 'Corrigir company_id ou remover o produto órfão.',
          fixSteps: [
            'Identifique a empresa correta.',
            'Atualize company_id do produto.',
            'Se for produto antigo/teste, remova.',
          ],
          fixSql: `update public.products set company_id = 'COLE_O_ID_DA_EMPRESA_AQUI' where id = '${product.id}';`,
        }))
      }

      if (Number(product.preco || 0) <= 0) {
        issues.push(issue({
          code: `product:${product.id}:zero-price`,
          title: 'Produto sem preço',
          description: `O produto "${label}" está com preço zero ou vazio. Isso pode gerar orçamento errado.`,
          severity: 'media',
          area: 'catálogo',
          entityType: 'product',
          entityId: product.id,
          entityLabel: label,
          affectedTable: 'products',
          affectedField: 'preco',
          suggestedAction: 'Definir preço ou regra de precificação.',
          fixRoute: '/painel/catalogo',
          fixSteps: [
            'Abra o Catálogo da empresa.',
            'Edite o produto.',
            'Preencha preço ou regra de precificação.',
            'Salve e teste um orçamento.',
          ],
          fixSql: `update public.products set preco = 1 where id = '${product.id}';`,
        }))
      }
    })

    proposals.forEach((proposal: any) => {
      const label = proposal.cliente_nome || proposal.id

      if (!['aprovada', 'aprovado', 'approved'].includes(String(proposal.status || '').toLowerCase()) && daysAgo(proposal.created_at) > 10) {
        issues.push(issue({
          code: `proposal:${proposal.id}:stale`,
          title: 'Proposta sem retorno',
          description: `A proposta de "${label}" está há mais de 10 dias sem aprovação.`,
          severity: 'baixa',
          area: 'propostas',
          entityType: 'proposal',
          entityId: proposal.id,
          entityLabel: label,
          affectedTable: 'proposals',
          affectedField: 'status',
          suggestedAction: 'Criar follow-up e chamar o cliente.',
          fixSteps: [
            'Abra Mini-CRM.',
            'Localize o cliente.',
            'Crie follow-up de retorno.',
            'Envie mensagem pelo WhatsApp.',
          ],
        }))
      }
    })

    leads.forEach((lead: any) => {
      const label = lead.empresa_nome || lead.email || lead.id

      if (lead.status === 'pago' && isBlank(lead.converted_user_id)) {
        issues.push(issue({
          code: `lead:${lead.id}:paid-not-converted`,
          title: 'Lead pago sem conta criada',
          description: `O lead "${label}" pagou, mas ainda não foi convertido em usuário/empresa.`,
          severity: 'critica',
          area: 'leads',
          entityType: 'lead',
          entityId: lead.id,
          entityLabel: label,
          affectedTable: 'signup_leads',
          affectedField: 'converted_user_id',
          suggestedAction: 'Verificar checkout de sucesso e criar conta do cliente.',
          fixSteps: [
            'Abra a aba Leads.',
            'Confirme se o pagamento foi aprovado.',
            'Abra checkout/sucesso e complete a criação da conta.',
            'Se necessário, crie usuário manualmente e vincule company_id.',
          ],
        }))
      }

      if (['lead', 'checkout_criado'].includes(lead.status) && daysAgo(lead.created_at) > 3) {
        issues.push(issue({
          code: `lead:${lead.id}:stale`,
          title: 'Lead parado',
          description: `O lead "${label}" iniciou cadastro há mais de 3 dias e não concluiu assinatura.`,
          severity: 'media',
          area: 'leads',
          entityType: 'lead',
          entityId: lead.id,
          entityLabel: label,
          affectedTable: 'signup_leads',
          affectedField: 'status',
          suggestedAction: 'Entrar em contato pelo WhatsApp.',
          fixSteps: [
            'Abra Leads no Admin.',
            'Clique no WhatsApp do lead.',
            'Pergunte se teve dificuldade no cadastro.',
            'Marque contato no Admin após falar com ele.',
          ],
        }))
      }
    })

    finance.forEach((tx: any) => {
      const label = tx.descricao || tx.id
      const due = daysUntil(tx.vencimento)

      if (tx.status === 'pendente' && due !== null && due < 0) {
        issues.push(issue({
          code: `finance:${tx.id}:overdue`,
          title: 'Conta pendente vencida',
          description: `O lançamento "${label}" está pendente e vencido há ${Math.abs(due)} dia(s).`,
          severity: 'media',
          area: 'financeiro',
          entityType: 'financial_transaction',
          entityId: tx.id,
          entityLabel: label,
          affectedTable: 'financial_transactions',
          affectedField: 'status',
          suggestedAction: 'Marcar como pago, renegociar ou ajustar vencimento.',
          fixRoute: '/painel/financeiro',
          fixSteps: [
            'Abra o Financeiro da empresa.',
            'Localize o lançamento pendente.',
            'Se foi pago, marque como pago.',
            'Se não foi pago, renegocie ou atualize vencimento.',
          ],
          fixSql: `update public.financial_transactions set status = 'pago' where id = '${tx.id}';`,
        }))
      }

      if (tx.origem === 'nota_fiscal' && isBlank(tx.nota_chave)) {
        issues.push(issue({
          code: `finance:${tx.id}:nf-no-key`,
          title: 'Nota fiscal sem chave',
          description: `O lançamento "${label}" veio de nota fiscal, mas está sem chave NF-e.`,
          severity: 'baixa',
          area: 'financeiro',
          entityType: 'financial_transaction',
          entityId: tx.id,
          entityLabel: label,
          affectedTable: 'financial_transactions',
          affectedField: 'nota_chave',
          suggestedAction: 'Anexar XML da NF-e ou preencher a chave manualmente.',
          fixRoute: '/painel/financeiro',
          fixSteps: [
            'Abra o Financeiro.',
            'Localize o lançamento.',
            'Anexe o XML da NF-e ou preencha a chave.',
            'Salve a alteração.',
          ],
          fixSql: `update public.financial_transactions set nota_chave = 'COLE_A_CHAVE_NFE_AQUI' where id = '${tx.id}';`,
        }))
      }
    })

    if (bugsOpen.length > 100) {
      issues.push(issue({
        code: 'system:too-many-open-bugs',
        title: 'Muitos bugs abertos',
        description: `Há ${bugsOpen.length} bugs abertos ou em análise. Isso atrapalha priorização.`,
        severity: 'alta',
        area: 'sistema',
        entityType: 'system',
        entityId: 'bugs',
        entityLabel: 'Scanner',
        suggestedAction: 'Resolver, ignorar ou colocar bugs em análise.',
        fixSteps: [
          'Abra a aba Scanner 24h.',
          'Filtre por abertos.',
          'Resolva os críticos e altos primeiro.',
          'Ignore os falsos positivos.',
        ],
      }))
    }

    await saveIssues(issues)

    const counts = issues.reduce((acc: any, item: any) => {
      if (item.severity === 'critica') acc.critical += 1
      if (item.severity === 'alta') acc.high += 1
      if (item.severity === 'media') acc.medium += 1
      if (item.severity === 'baixa') acc.low += 1
      return acc
    }, { critical: 0, high: 0, medium: 0, low: 0 })

    if (runId) {
      await supabaseAdmin
        .from('admin_scan_runs')
        .update({
          status: 'concluido',
          finished_at: new Date().toISOString(),
          total_issues: issues.length,
          critical_count: counts.critical,
          high_count: counts.high,
          medium_count: counts.medium,
          low_count: counts.low,
          summary: {
            companies: companies.length,
            users: users.length,
            orders: orders.length,
            products: products.length,
            proposals: proposals.length,
            leads: leads.length,
            finance: finance.length,
            generated_issue_codes: issues.map((item: any) => item.code),
          },
        })
        .eq('id', runId)
    }

    await auditLog(actorEmail, 'scanner.run_detailed', 'scan', runId || '', 'Scanner detalhado', { issues: issues.length, counts })

    const [bugs, runs] = await Promise.all([
      dataOrEmpty(supabaseAdmin.from('admin_bug_reports').select('*').order('last_seen_at', { ascending: false }).limit(300)),
      dataOrEmpty(supabaseAdmin.from('admin_scan_runs').select('*').order('started_at', { ascending: false }).limit(50)),
    ])

    return NextResponse.json({ ok: true, issues, counts, bugs, runs })
  } catch (error) {
    if (runId) {
      await supabaseAdmin
        .from('admin_scan_runs')
        .update({
          status: 'falhou',
          finished_at: new Date().toISOString(),
          summary: { error: error instanceof Error ? error.message : 'Erro desconhecido' },
        })
        .eq('id', runId)
    }

    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro ao rodar scanner.' }, { status: 500 })
  }
}

// ORCALY_OWNER_SUPPORT_CONTROL_V1
import { NextRequest, NextResponse } from 'next/server'
import { enforceRateLimit } from '@/lib/security/rate-limit'
import { readJsonBody, requestBodyErrorResponse } from '@/lib/security/request'
import {
  PLATFORM_PERMISSION_CATALOG,
  auditPlatformAction,
  requirePlatformAdmin,
  sanitizeSupportPermissions,
} from '@/lib/platform-admin'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function text(value: unknown) {
  return String(value || '').trim()
}

function email(value: unknown) {
  return text(value).toLowerCase()
}

function validPassword(value: unknown) {
  const password = text(value)

  return (
    password.length >= 10 &&
    /[A-Za-z]/.test(password) &&
    /\d/.test(password)
  )
}

async function findAuthUserByEmail(
  supabaseAdmin: any,
  targetEmail: string,
) {
  for (let page = 1; page <= 20; page += 1) {
    const { data, error } =
      await supabaseAdmin.auth.admin.listUsers({
        page,
        perPage: 100,
      })

    if (error) throw error

    const users = data?.users || []
    const found = users.find(
      (user: any) =>
        String(user.email || '').toLowerCase() ===
        targetEmail,
    )

    if (found) return found
    if (users.length < 100) break
  }

  return null
}

export async function GET(request: NextRequest) {
  const session = await requirePlatformAdmin(
    request,
    'team.manage',
  )

  if (!session.ok) {
    return NextResponse.json(
      { error: session.error },
      { status: session.status },
    )
  }

  const { data, error } = await session.supabaseAdmin
    .from('platform_admins')
    .select(
      'id,user_id,email,nome,role,is_active,permissions,area,observacoes,created_by,last_login_at,must_change_password,created_at,updated_at',
    )
    .order('created_at', {
      ascending: true,
    })

  if (error) {
    return NextResponse.json(
      { error: error.message },
      { status: 500 },
    )
  }

  return NextResponse.json({
    team: data || [],
    permissionCatalog:
      PLATFORM_PERMISSION_CATALOG.filter(
        (item) => item.supportAssignable,
      ),
  })
}

export async function POST(request: NextRequest) {
  const session = await requirePlatformAdmin(
    request,
    'team.manage',
  )

  if (!session.ok) {
    return NextResponse.json(
      { error: session.error },
      { status: session.status },
    )
  }

  try {
    const blocked = await enforceRateLimit(request, {
      scope: 'admin-team-write',
      identity: session.admin.id,
      limit: 30,
      windowSeconds: 60,
    })
    if (blocked) return blocked

    const body = await readJsonBody<Record<string, unknown>>(
      request,
      32 * 1024,
    )
    const action = text(body.action)
    const targetId = text(body.id)

    if (action === 'create_support') {
      const targetEmail = email(body.email)
      const nome = text(body.nome)
      const password = text(body.password)
      const observacoes =
        text(body.observacoes).slice(0, 500) ||
        null

      if (
        !targetEmail ||
        !targetEmail.includes('@')
      ) {
        return NextResponse.json(
          { error: 'Informe um e-mail válido.' },
          { status: 400 },
        )
      }

      if (nome.length < 2) {
        return NextResponse.json(
          { error: 'Informe o nome do suporte.' },
          { status: 400 },
        )
      }

      if (!validPassword(password)) {
        return NextResponse.json(
          {
            error:
              'A senha temporária precisa ter pelo menos 10 caracteres, com letra e número.',
          },
          { status: 400 },
        )
      }

      const { data: existingAdmin } =
        await session.supabaseAdmin
          .from('platform_admins')
          .select('id,role')
          .ilike('email', targetEmail)
          .maybeSingle()

      const authUser = await findAuthUserByEmail(
        session.supabaseAdmin,
        targetEmail,
      )

      if (authUser && !existingAdmin?.id) {
        return NextResponse.json(
          {
            error:
              'Esse e-mail já pertence a outra conta do Orçaly. Use um e-mail exclusivo para o suporte.',
          },
          { status: 409 },
        )
      }

      let user = authUser

      if (!user) {
        const { data, error } =
          await session.supabaseAdmin.auth.admin.createUser(
            {
              email: targetEmail,
              password,
              email_confirm: true,
              app_metadata: {
                orcaly_role: 'support',
              },
              user_metadata: {
                nome,
                portal: 'admin',
                must_change_password: true,
              },
            },
          )

        if (error || !data.user?.id) {
          throw (
            error ||
            new Error(
              'Não foi possível criar a conta.',
            )
          )
        }

        user = data.user
      } else {
        if (
          existingAdmin?.role &&
          existingAdmin.role !== 'support'
        ) {
          return NextResponse.json(
            {
              error:
                'Esse usuário interno possui outro nível de acesso.',
            },
            { status: 409 },
          )
        }

        const { data, error } =
          await session.supabaseAdmin.auth.admin.updateUserById(
            user.id,
            {
              password,
              email_confirm: true,
              app_metadata: {
                ...(user.app_metadata || {}),
                orcaly_role: 'support',
              },
              user_metadata: {
                ...(user.user_metadata || {}),
                nome,
                portal: 'admin',
                must_change_password: true,
              },
            },
          )

        if (error || !data.user?.id) {
          throw (
            error ||
            new Error(
              'Não foi possível atualizar a conta.',
            )
          )
        }

        user = data.user
      }

      const permissions =
        sanitizeSupportPermissions(
          body.permissions,
        )

      const { data: row, error } =
        await session.supabaseAdmin
          .from('platform_admins')
          .upsert(
            {
              user_id: user.id,
              email: targetEmail,
              nome,
              role: 'support',
              is_active: true,
              permissions,
              area: 'Suporte',
              observacoes,
              created_by: session.admin.email,
              must_change_password: true,
              updated_at:
                new Date().toISOString(),
            },
            {
              onConflict: 'email',
            },
          )
          .select(
            'id,email,nome,role,is_active,permissions,area,must_change_password,created_at,updated_at',
          )
          .single()

      if (error) throw error

      await auditPlatformAction(
        session.admin.email,
        'support_created',
        {
          targetType: 'platform_admin',
          targetId: row.id,
          targetLabel: targetEmail,
          payload: {
            permissions,
          },
        },
      )

      return NextResponse.json({
        ok: true,
        member: row,
        message:
          'Acesso de suporte criado. A senha não foi armazenada.',
      })
    }

    const { data: target, error: targetError } =
      await session.supabaseAdmin
        .from('platform_admins')
        .select(
          'id,user_id,email,nome,role,is_active,permissions',
        )
        .eq('id', targetId)
        .maybeSingle()

    if (targetError) throw targetError

    if (!target?.id) {
      return NextResponse.json(
        { error: 'Usuário interno não encontrado.' },
        { status: 404 },
      )
    }

    if (target.role === 'owner') {
      return NextResponse.json(
        {
          error:
            'Contas de dono não podem ser alteradas por esta tela.',
        },
        { status: 403 },
      )
    }

    if (action === 'update_support') {
      const nome = text(body.nome)
      const permissions =
        sanitizeSupportPermissions(
          body.permissions,
        )
      const observacoes =
        text(body.observacoes).slice(0, 500) ||
        null

      const { data, error } =
        await session.supabaseAdmin
          .from('platform_admins')
          .update({
            nome:
              nome.length >= 2
                ? nome
                : target.nome,
            permissions,
            observacoes,
            updated_at:
              new Date().toISOString(),
          })
          .eq('id', target.id)
          .select(
            'id,email,nome,role,is_active,permissions,area,observacoes,must_change_password,created_at,updated_at',
          )
          .single()

      if (error) throw error

      await auditPlatformAction(
        session.admin.email,
        'support_permissions_updated',
        {
          targetType: 'platform_admin',
          targetId: target.id,
          targetLabel: target.email,
          payload: {
            permissions,
          },
        },
      )

      return NextResponse.json({
        ok: true,
        member: data,
      })
    }

    if (action === 'set_active') {
      const active = Boolean(body.active)

      const { error } =
        await session.supabaseAdmin
          .from('platform_admins')
          .update({
            is_active: active,
            updated_at:
              new Date().toISOString(),
          })
          .eq('id', target.id)

      if (error) throw error

      if (target.user_id) {
        const authUser =
          await session.supabaseAdmin.auth.admin.getUserById(
            target.user_id,
          )

        if (authUser.data.user?.id) {
          await session.supabaseAdmin.auth.admin.updateUserById(
            target.user_id,
            {
              app_metadata: {
                ...(authUser.data.user
                  .app_metadata || {}),
                orcaly_role: active
                  ? 'support'
                  : 'disabled_support',
              },
            },
          )
        }
      }

      await auditPlatformAction(
        session.admin.email,
        active
          ? 'support_activated'
          : 'support_deactivated',
        {
          targetType: 'platform_admin',
          targetId: target.id,
          targetLabel: target.email,
        },
      )

      return NextResponse.json({
        ok: true,
      })
    }

    if (action === 'reset_password') {
      const password = text(body.password)

      if (!validPassword(password)) {
        return NextResponse.json(
          {
            error:
              'A nova senha temporária precisa ter pelo menos 10 caracteres, com letra e número.',
          },
          { status: 400 },
        )
      }

      if (!target.user_id) {
        return NextResponse.json(
          {
            error:
              'A conta ainda não está vinculada ao Supabase Auth.',
          },
          { status: 409 },
        )
      }

      const { data: authData, error } =
        await session.supabaseAdmin.auth.admin.getUserById(
          target.user_id,
        )

      if (error || !authData.user?.id) {
        throw (
          error ||
          new Error('Conta de autenticação ausente.')
        )
      }

      const update =
        await session.supabaseAdmin.auth.admin.updateUserById(
          target.user_id,
          {
            password,
            app_metadata: {
              ...(authData.user.app_metadata || {}),
              orcaly_role: 'support',
            },
            user_metadata: {
              ...(authData.user.user_metadata || {}),
              must_change_password: true,
            },
          },
        )

      if (update.error) throw update.error

      await session.supabaseAdmin
        .from('platform_admins')
        .update({
          must_change_password: true,
          updated_at:
            new Date().toISOString(),
        })
        .eq('id', target.id)

      await auditPlatformAction(
        session.admin.email,
        'support_password_reset',
        {
          targetType: 'platform_admin',
          targetId: target.id,
          targetLabel: target.email,
        },
      )

      return NextResponse.json({
        ok: true,
        message:
          'Senha temporária redefinida. Ela não foi armazenada.',
      })
    }

    return NextResponse.json(
      { error: 'Ação inválida.' },
      { status: 400 },
    )
  } catch (error) {
    const bodyError = requestBodyErrorResponse(error)
    if (bodyError) return bodyError

    return NextResponse.json(
      {
        error:
          error instanceof Error
            ? error.message
            : 'Não foi possível concluir a operação.',
      },
      { status: 500 },
    )
  }
}

import { enforceRateLimit } from '@/lib/security/rate-limit'
import { readJsonBody, requestBodyErrorResponse } from '@/lib/security/request'
// ORCALY_AI_LIMITS_V1
import { NextRequest, NextResponse } from 'next/server'
import { assinaturaEstaAtiva, getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { normalizePlanKey } from '@/lib/plans/plan-config'

export async function POST(request: NextRequest) {
  try {
    const apiKey = process.env.OPENAI_API_KEY
    const model = process.env.ORCALY_AI_MODEL || 'gpt-4o-mini'

    if (!apiKey) {
      return NextResponse.json(
        { error: 'OPENAI_API_KEY não configurada.' },
        { status: 500 }
      )
    }

    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

    if (!access.company?.id) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (!assinaturaEstaAtiva(access.company)) {
      return NextResponse.json(
        { error: 'Assinatura sem acesso ativo.' },
        { status: 403 },
      )
    }

    const plan = normalizePlanKey(
      access.company.assinatura_plano ||
        access.company.plano ||
        'essencial',
    )
    const dailyLimit =
      plan === 'premium'
        ? 600
        : plan === 'profissional'
          ? 120
          : 25

    const burstBlocked = await enforceRateLimit(request, {
      scope: 'ai-user-minute',
      identity: requester.id,
      limit: 10,
      windowSeconds: 60,
    })
    if (burstBlocked) return burstBlocked

    const dailyBlocked = await enforceRateLimit(request, {
      scope: 'ai-company-daily',
      identity: access.company.id,
      limit: dailyLimit,
      windowSeconds: 86400,
    })
    if (dailyBlocked) return dailyBlocked

    const body = await readJsonBody<any>(request, 16 * 1024)
    const prompt = String(body.prompt || '').trim().slice(0, 8000)

    if (!prompt) {
      return NextResponse.json({ error: 'Digite uma solicitação.' }, { status: 400 })
    }

    const system = [
      'Você é o assistente interno do Orçaly.',
      'Ajude empresas brasileiras a configurar site, catálogo, produtos, cupons, atendimento, propostas e operação.',
      'Responda em português do Brasil.',
      'Seja prático, organizado e pronto para copiar.',
      'Não invente dados sensíveis.',
      'Quando criar produtos, traga nomes, descrições, preços sugeridos e campos úteis.',
    ].join('\n')

    const context = {
      empresa: {
        nome: access.company.nome,
        segmento: access.company.segmento || access.company.modelo_negocio || access.company.site_template,
        cidade: access.company.cidade,
        estado: access.company.estado,
        plano: access.company.assinatura_plano || access.company.plano,
      },
    }

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model,
        temperature: 0.6,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: `Contexto da empresa:\n${JSON.stringify(context, null, 2)}\n\nPedido do usuário:\n${prompt}` },
        ],
      }),
    })

    const payload = await response.json().catch(() => ({}))

    if (!response.ok) {
      return NextResponse.json(
        { error: payload.error?.message || 'Erro na OpenAI.' },
        { status: 500 }
      )
    }

    const answer = payload.choices?.[0]?.message?.content || ''

    return NextResponse.json({ ok: true, answer })
  } catch (error) {
    const bodyError = requestBodyErrorResponse(error)
    if (bodyError) return bodyError

    const message = error instanceof Error ? error.message : 'Erro ao consultar assistente.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { enforceRateLimit } from '@/lib/security/rate-limit'
import { readJsonBody, requestBodyErrorResponse } from '@/lib/security/request'
// ORCALY_AI_LIMITS_V1
import { NextRequest, NextResponse } from 'next/server'
import { assinaturaEstaAtiva, getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { normalizePlanKey } from '@/lib/plans/plan-config'

function heuristic(text: string) {
  const lower = text.toLowerCase()
  const quantityMatch = lower.match(/(\d+)\s*(camisas|camisetas|cartões|cartoes|adesivos|canecas|unidades|peças|pecas)?/)
  const quantity = quantityMatch ? Number(quantityMatch[1]) : null

  const product =
    lower.includes('camisa') || lower.includes('camiseta') ? 'camisa personalizada'
    : lower.includes('cart') ? 'cartão de visita'
    : lower.includes('adesivo') ? 'adesivo'
    : lower.includes('caneca') ? 'caneca personalizada'
    : 'produto/serviço a definir'

  const missing = []
  if (!lower.includes('arte') && !lower.includes('logo')) missing.push('Você já tem a arte ou logo?')
  if (product.includes('camisa') && !lower.includes('tamanho')) missing.push('Quais tamanhos das camisas?')
  if (!lower.includes('retirar') && !lower.includes('entrega') && !lower.includes('entregar')) missing.push('Vai retirar ou precisa de entrega?')

  return {
    produto: product,
    quantidade: quantity,
    cor: lower.includes('preta') || lower.includes('preto') ? 'preta' : null,
    personalizacao: lower.includes('frente') || lower.includes('costas') ? 'frente/costas' : null,
    prazo: lower.includes('sábado') || lower.includes('sabado') ? 'sábado' : null,
    status: 'aguardando preço',
    perguntas_faltantes: missing,
    resumo: text,
  }
}

export async function POST(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)
    if (!access.company?.id) return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    if (!assinaturaEstaAtiva(access.company)) {
      return NextResponse.json(
        { error: 'Assinatura sem acesso ativo.' },
        { status: 403 },
      )
    }

    const plan = normalizePlanKey(
      access.company.assinatura_plano ||
        access.company.plano ||
        'essencial',
    )
    const dailyLimit =
      plan === 'premium'
        ? 600
        : plan === 'profissional'
          ? 120
          : 25

    const burstBlocked = await enforceRateLimit(request, {
      scope: 'ai-user-minute',
      identity: requester.id,
      limit: 10,
      windowSeconds: 60,
    })
    if (burstBlocked) return burstBlocked

    const dailyBlocked = await enforceRateLimit(request, {
      scope: 'ai-company-daily',
      identity: access.company.id,
      limit: dailyLimit,
      windowSeconds: 86400,
    })
    if (dailyBlocked) return dailyBlocked

    const body = await readJsonBody<Record<string, unknown>>(request, 16 * 1024)
    const text = String(body.text || '').trim().slice(0, 8000)

    if (!text) return NextResponse.json({ error: 'Texto do pedido é obrigatório.' }, { status: 400 })

    const apiKey = process.env.OPENAI_API_KEY

    if (!apiKey) {
      return NextResponse.json({
        ok: true,
        source: 'heuristic',
        parsed: heuristic(text),
      })
    }

    const prompt = `
Transforme o pedido bagunçado abaixo em JSON estruturado para orçamento.
Responda apenas JSON válido, sem markdown.

Campos:
produto, quantidade, cor, personalizacao, prazo, status, perguntas_faltantes, resumo.

Empresa: ${access.company.nome}
Segmento: ${access.company.segmento || access.company.modelo_nome || 'geral'}
Pedido: ${text}
`.trim()

    const response = await fetch('https://api.openai.com/v1/responses', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: process.env.ORCALY_AI_MODEL || 'gpt-4.1-mini',
        input: prompt,
        max_output_tokens: 500,
      }),
    })

    const data = await response.json().catch(() => ({}))

    if (!response.ok) {
      return NextResponse.json({
        ok: true,
        source: 'heuristic',
        warning: data?.error?.message || 'IA indisponível, usando extração simples.',
        parsed: heuristic(text),
      })
    }

    let parsed: any = null
    const output = String(data.output_text || '{}').trim()

    try {
      parsed = JSON.parse(output)
    } catch {
      parsed = heuristic(text)
    }

    return NextResponse.json({
      ok: true,
      source: 'openai',
      parsed,
    })
  } catch (error) {
    const bodyError = requestBodyErrorResponse(error)
    if (bodyError) return bodyError

    const message = error instanceof Error ? error.message : 'Erro ao interpretar pedido.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { assinaturaEstaAtiva, getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { getBusinessTypeConfig, getDefaultSetupForBusiness, normalizeBusinessType } from '@/lib/business-types'

export async function POST(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

    if (!access.company?.id) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (!assinaturaEstaAtiva(access.company)) {
      return NextResponse.json({
        error: 'Assinatura inativa. Renove para alterar módulos e configurações avançadas.',
      }, { status: 402 })
    }

    if (!access.canManage) {
      return NextResponse.json({ error: 'Seu perfil não pode alterar o tipo de negócio.' }, { status: 403 })
    }

    const body = await request.json()
    const businessType = normalizeBusinessType(body.business_type)
    const applyTemplate = body.apply_template === true
    const config = getBusinessTypeConfig(businessType)

    const update: Record<string, any> = {
      business_type: businessType,
      site_updated_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }

    if (applyTemplate) {
      Object.assign(update, getDefaultSetupForBusiness(businessType))
    }

    const { data, error } = await supabaseAdmin
      .from('companies')
      .update(update)
      .eq('id', access.company.id)
      .select('*')
      .single()

    if (error) throw error

    return NextResponse.json({
      ok: true,
      company: data,
      businessType: config,
      appliedTemplate: applyTemplate,
      message: applyTemplate
        ? `Modelo ${config.publicName} aplicado. Produtos e pedidos existentes foram preservados.`
        : `Tipo de negócio alterado para ${config.label}. Produtos e pedidos existentes foram preservados.`,
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao aplicar tipo de negócio.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

// ORCALY_AFFILIATE_INTEGRATION_V1
import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { requireSameOrigin } from "@/lib/orcaly-security";
import { enforceRateLimit } from "@/lib/security/rate-limit";
import { readJsonBody, requestBodyErrorResponse } from "@/lib/security/request";
import { documentDigits, isValidCpfCnpj } from "@/lib/br-document";
import { normalizePlanKey } from "@/lib/plans/plan-config";
import {
  getBusinessTypeConfig,
  getDefaultSetupForBusiness,
  normalizeBusinessType,
} from "@/lib/business-types";
import {
  getSubdomainSuggestions,
  validateSubdomainSlug,
} from "@/lib/slug";
import {
  createSignupCheckoutToken,
} from "@/lib/signup-checkout";
import {
  recordAffiliateReferral,
  requestIp,
} from "@/lib/affiliates/server";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY!;
const siteUrl = (
  process.env.ORCALY_APP_URL ||
  process.env.NEXT_PUBLIC_APP_URL ||
  process.env.NEXT_PUBLIC_SITE_URL ||
  "https://orcaly.com.br"
).replace(/\/$/, "");

const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
  auth: {
    persistSession: false,
  },
});

function telefoneLimpo(valor: string) {
  return valor.replace(/\D/g, "");
}

function erro(message: string, status = 400) {
  return NextResponse.json({ error: message }, { status });
}

async function linkDisponivel(slug: string) {
  const { data, error } = await supabaseAdmin
    .from("companies")
    .select("id")
    .or(`subdomain_slug.eq.${slug},slug.eq.${slug}`)
    .limit(1);

  if (error) throw error;

  return !data || data.length === 0;
}

function safeRaw(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return value as Record<string, unknown>;
}

export async function POST(request: NextRequest) {
  try {
    const originError = requireSameOrigin(request);
    if (originError) return originError;

    const blocked = await enforceRateLimit(request, {
      scope: "signup-lead",
      limit: 8,
      windowSeconds: 3600,
    });
    if (blocked) return blocked;

    if (!supabaseUrl || !serviceRoleKey) {
      return erro("Supabase service role não configurada.", 500);
    }

    const body = await readJsonBody<Record<string, unknown>>(
      request,
      32 * 1024,
    );

    const nome_responsavel = String(body.nome_responsavel || "").trim();
    const email = String(body.email || "").trim().toLowerCase();
    const cpf_cnpj = documentDigits(
      body.cpf_cnpj || body.documento || body.document,
    );
    const whatsapp = telefoneLimpo(String(body.whatsapp || ""));
    const empresa_nome = String(body.empresa_nome || "").trim();
    const business_type = normalizeBusinessType(
      body.business_type || body.modelo_negocio || body.segmento,
    );
    const businessConfig = getBusinessTypeConfig(business_type);
    const defaultSetup = getDefaultSetupForBusiness(business_type);
    const segmento = String(body.segmento || businessConfig.label).trim();
    const modelo_negocio = String(body.modelo_negocio || business_type).trim();
    const onboarding_goal = String(body.onboarding_goal || "").trim();
    const cidade = String(body.cidade || "").trim();
    const estado = String(body.estado || "").trim().toUpperCase();
    const plano = normalizePlanKey(body.plano || "profissional");
    const marketing_opt_in = Boolean(body.marketing_opt_in);
    const referral_code = String(
      body.referral_code || body.ref || "",
    )
      .trim()
      .toUpperCase()
      .replace(/[^A-Z0-9_-]/g, "")
      .slice(0, 32);

    const requestedSubdomain = String(
      body.subdomain_slug || empresa_nome,
    ).trim();
    const validation = validateSubdomainSlug(requestedSubdomain);

    if (!nome_responsavel) return erro("Informe seu nome.");
    if (!email || !email.includes("@")) {
      return erro("Informe um e-mail válido.");
    }
    if (!isValidCpfCnpj(cpf_cnpj)) {
      return erro("Informe um CPF ou CNPJ válido.");
    }
    if (!whatsapp || whatsapp.length < 10) {
      return erro("Informe um WhatsApp válido.");
    }
    if (!empresa_nome || empresa_nome.length < 2) {
      return erro("Informe o nome da empresa.");
    }
    if (!cidade) return erro("Escolha a cidade da empresa.");
    if (!business_type) return erro("Escolha o tipo de negócio.");
    if (!onboarding_goal) {
      return erro("Escolha o principal objetivo da empresa.");
    }
    if (!validation.ok) {
      return erro(validation.reason || "Escolha um link público válido.");
    }
    if (!marketing_opt_in) {
      return erro(
        "Para receber informações sobre o cadastro, confirme a autorização.",
      );
    }

    const available = await linkDisponivel(validation.slug);

    if (!available) {
      return NextResponse.json(
        {
          error: "Esse link já está em uso. Tente outro nome.",
          suggestions: getSubdomainSuggestions(empresa_nome, cidade),
        },
        { status: 409 },
      );
    }

    const rawData = {
      nome_responsavel,
      email,
      whatsapp,
      empresa_nome,
      cidade,
      estado,
      plano,
      cpf_cnpj,
      signup_document: cpf_cnpj,
      signup_document_type:
        cpf_cnpj.length === 14 ? "CNPJ" : "CPF",
      business_type,
      onboarding_goal,
      subdomain_slug: validation.slug,
      slug_sugerido: validation.slug,
      segmento,
      modelo_negocio,
      default_setup: defaultSetup,
      signup_offer: {
        card_trial_days: 7,
        pix_bonus_days: 7,
      },
      signup_checkout_version: 2,
      referral_code: referral_code || null,
    };

    const { data: leadExistente } = await supabaseAdmin
      .from("signup_leads")
      .select("*")
      .eq("email", email)
      .in("status", [
        "lead",
        "checkout_criado",
        "trial_ready",
        "pago",
      ])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    let leadId = leadExistente?.id as string | undefined;

    if (leadId) {
      const { error: updateError } = await supabaseAdmin
        .from("signup_leads")
        .update({
          nome_responsavel,
          whatsapp,
          empresa_nome,
          slug_sugerido: validation.slug,
          segmento,
          modelo_negocio,
          cidade,
          estado,
          plano,
          status: ["pago", "trial_ready"].includes(leadExistente.status)
            ? leadExistente.status
            : "checkout_criado",
          marketing_opt_in,
          marketing_opt_in_text:
            "Autorizo o Orçaly a entrar em contato pelo WhatsApp sobre minha assinatura e meu cadastro.",
          next_followup_at: new Date(
            Date.now() + 2 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          raw_data: {
            ...safeRaw(leadExistente.raw_data),
            ...rawData,
          },
        })
        .eq("id", leadId);

      if (updateError) throw updateError;
    } else {
      const { data: lead, error: insertError } = await supabaseAdmin
        .from("signup_leads")
        .insert({
          nome_responsavel,
          email,
          whatsapp,
          empresa_nome,
          slug_sugerido: validation.slug,
          segmento,
          modelo_negocio,
          cidade,
          estado,
          plano,
          status: "checkout_criado",
          marketing_opt_in,
          marketing_opt_in_text:
            "Autorizo o Orçaly a entrar em contato pelo WhatsApp sobre minha assinatura e meu cadastro.",
          next_followup_at: new Date(
            Date.now() + 2 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          raw_data: rawData,
        })
        .select("id")
        .single();

      if (insertError) throw insertError;
      leadId = lead.id;
    }

    if (!leadId) {
      return erro("Não foi possível preparar o checkout.", 500);
    }

    if (referral_code) {
      try {
        await recordAffiliateReferral({
          code: referral_code,
          leadId,
          customerName: empresa_nome || nome_responsavel,
          customerEmail: email,
          customerDocument: cpf_cnpj,
          customerWhatsapp: whatsapp,
          plan: plano,
          ip: requestIp(request),
          userAgent: request.headers.get("user-agent"),
        });
      } catch (affiliateError) {
        console.error(
          "orcaly_affiliate_referral_error",
          affiliateError instanceof Error
            ? affiliateError.message
            : affiliateError,
        );
      }
    }

    const checkout = createSignupCheckoutToken(leadId);

    const checkoutUrl =
      `${siteUrl}/checkout/cadastro` +
      `?lead_id=${encodeURIComponent(leadId)}` +
      `&expires=${encodeURIComponent(String(checkout.expires))}` +
      `&token=${encodeURIComponent(checkout.token)}`;

    await supabaseAdmin
      .from("signup_leads")
      .update({ checkout_url: checkoutUrl })
      .eq("id", leadId);

    return NextResponse.json({
      ok: true,
      lead_id: leadId,
      checkout_url: checkoutUrl,
      subdomain_slug: validation.slug,
    });
  } catch (error) {
    return NextResponse.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Erro ao iniciar o cadastro.",
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL || '',
  process.env.SUPABASE_SERVICE_ROLE_KEY || '',
  { auth: { persistSession: false } }
)

const cargoPermissions: Record<string, Record<string, boolean>> = {
  gerente: {
    orders: true,
    products: true,
    proposals: true,
    customers: true,
    opportunities: true,
    finance: true,
    production: true,
    settings: false,
    team: false,
    admin: false,
  },
  atendente: {
    orders: true,
    products: false,
    proposals: true,
    customers: true,
    opportunities: true,
    finance: false,
    production: false,
    settings: false,
    team: false,
    admin: false,
  },
  producao: {
    orders: true,
    products: true,
    proposals: false,
    customers: false,
    opportunities: false,
    finance: false,
    production: true,
    settings: false,
    team: false,
    admin: false,
  },
}

function isUuid(value: unknown) {
  return typeof value === 'string'
    && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
}

function cleanEmail(value: string) {
  return String(value || '').trim().toLowerCase()
}

function cleanCargo(value: string) {
  return ['gerente', 'atendente', 'producao'].includes(value) ? value : 'atendente'
}

async function getRequester(request: NextRequest) {
  const token = (request.headers.get('authorization') || '').replace('Bearer ', '').trim()
  if (!token) return null

  const { data, error } = await supabaseAdmin.auth.getUser(token)
  if (error || !data.user) return null

  return data.user
}

async function getCompanyForUser(userId: string, email?: string) {
  if (!isUuid(userId)) return { company: null, requesterRole: null }

  const { data: ownCompany } = await supabaseAdmin
    .from('companies')
    .select('*')
    .or(`owner_id.eq.${userId},tester_id.eq.${userId}`)
    .maybeSingle()

  if (ownCompany?.id) {
    return { company: ownCompany, requesterRole: 'dono' }
  }

  const { data: member } = await supabaseAdmin
    .from('company_members')
    .select('company_id,cargo,status')
    .eq('user_id', userId)
    .eq('status', 'ativo')
    .maybeSingle()

  if (member?.company_id && isUuid(member.company_id)) {
    const { data: company } = await supabaseAdmin
      .from('companies')
      .select('*')
      .eq('id', member.company_id)
      .maybeSingle()

    return { company, requesterRole: member.cargo || 'funcionario' }
  }

  if (email?.toLowerCase() === 'araujovinicius249@gmail.com') {
    const { data: firstCompany } = await supabaseAdmin
      .from('companies')
      .select('*')
      .eq('slug', 'grafica-flash')
      .maybeSingle()

    if (firstCompany?.id) {
      return { company: firstCompany, requesterRole: 'dono' }
    }
  }

  return { company: null, requesterRole: null }
}

async function findUserByEmail(email: string) {
  const perPage = 1000
  const { data, error } = await supabaseAdmin.auth.admin.listUsers({ page: 1, perPage })

  if (error) throw error

  return (data.users || []).find((user) => user.email?.toLowerCase() === email.toLowerCase()) || null
}

async function ensureAuthUser(email: string, nome: string, senha?: string) {
  const existing = await findUserByEmail(email)

  if (existing) return existing

  const password = senha && senha.length >= 6 ? senha : Math.random().toString(36).slice(2, 10) + 'Aa1!'

  const { data, error } = await supabaseAdmin.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
    user_metadata: {
      nome,
      criado_pelo_orcaly: true,
      tipo: 'funcionario',
    },
  })

  if (error) throw error
  if (!data.user) throw new Error('Não foi possível criar o usuário.')

  return data.user
}

function publicCompany(company: any) {
  return {
    id: company.id,
    nome: company.nome,
    slug: company.slug,
    subdomain_slug: company.subdomain_slug,
    logo_url: company.logo_url,
    whatsapp: company.whatsapp,
    cidade: company.cidade,
    estado: company.estado,
    instagram: company.instagram,
    atendimento_horario: company.atendimento_horario,
    atendimento_observacao: company.atendimento_observacao,
    site_status: company.site_status,
    pix_key: company.pix_key,
    pix_tipo: company.pix_tipo,
    pix_nome: company.pix_nome,
    pix_cidade: company.pix_cidade,
    aceita_pix: company.aceita_pix,
    aceita_cartao: company.aceita_cartao,
    cobrar_sinal: company.cobrar_sinal,
    percentual_sinal: company.percentual_sinal,
  }
}

export async function GET(request: NextRequest) {
  try {
    const requester = await getRequester(request)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const { company } = await getCompanyForUser(requester.id, requester.email || '')

    if (!company?.id || !isUuid(company.id)) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    const { data: members, error } = await supabaseAdmin
      .from('company_members')
      .select('id,company_id,user_id,nome,email,cargo,status,permissions,created_at,updated_at')
      .eq('company_id', company.id)
      .order('created_at', { ascending: false })

    if (error) throw error

    return NextResponse.json({
      company: publicCompany(company),
      company_id: company.id,
      members: members || [],
      limit: 2,
      active_count: (members || []).filter((member) => member.status === 'ativo').length,
    })
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Erro ao carregar equipe.' },
      { status: 500 }
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const requester = await getRequester(request)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const body = await request.json()
    const nome = String(body.nome || '').trim()
    const email = cleanEmail(body.email || '')
    const cargo = cleanCargo(body.cargo || 'atendente')
    const senha = String(body.senha || body.password || '').trim()

    if (!nome) return NextResponse.json({ error: 'Informe o nome do funcionário.' }, { status: 400 })
    if (!email || !email.includes('@')) return NextResponse.json({ error: 'Informe um e-mail válido.' }, { status: 400 })
    if (email === 'araujovinicius249@gmail.com') return NextResponse.json({ error: 'Este e-mail é do Admin Master e não pode ser cadastrado como funcionário.' }, { status: 400 })
    if (senha && senha.length < 6) return NextResponse.json({ error: 'A senha inicial precisa ter pelo menos 6 caracteres.' }, { status: 400 })

    const { company, requesterRole } = await getCompanyForUser(requester.id, requester.email || '')

    if (!company?.id || !isUuid(company.id)) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (requesterRole !== 'dono' && requester.email?.toLowerCase() !== 'araujovinicius249@gmail.com') {
      return NextResponse.json({ error: 'Somente o dono da empresa pode cadastrar funcionários.' }, { status: 403 })
    }

    const { data: activeMembers, error: countError } = await supabaseAdmin
      .from('company_members')
      .select('id,email,status')
      .eq('company_id', company.id)
      .eq('status', 'ativo')

    if (countError) throw countError

    const alreadyActiveByEmail = (activeMembers || []).find((member) => member.email?.toLowerCase() === email)

    if (!alreadyActiveByEmail && (activeMembers || []).length >= 2) {
      return NextResponse.json({ error: 'Limite de 2 funcionários ativos atingido.' }, { status: 400 })
    }

    const user = await ensureAuthUser(email, nome, senha)

    if (!user?.id || !isUuid(user.id)) {
      return NextResponse.json({ error: 'Usuário inválido.' }, { status: 400 })
    }

    const payload = {
      company_id: company.id,
      user_id: user.id,
      nome,
      email,
      cargo,
      status: 'ativo',
      permissions: cargoPermissions[cargo] || cargoPermissions.atendente,
      created_by: requester.id,
      updated_at: new Date().toISOString(),
    }

    const { data: existingMember, error: existingError } = await supabaseAdmin
      .from('company_members')
      .select('id')
      .eq('company_id', company.id)
      .or(`user_id.eq.${user.id},email.eq.${email}`)
      .maybeSingle()

    if (existingError) throw existingError

    let savedMember: any = null

    if (existingMember?.id && isUuid(existingMember.id)) {
      const { data, error } = await supabaseAdmin
        .from('company_members')
        .update(payload)
        .eq('id', existingMember.id)
        .select('id,company_id,user_id,nome,email,cargo,status,permissions,created_at,updated_at')
        .single()

      if (error) throw error
      savedMember = data
    } else {
      const { data, error } = await supabaseAdmin
        .from('company_members')
        .insert(payload)
        .select('id,company_id,user_id,nome,email,cargo,status,permissions,created_at,updated_at')
        .single()

      if (error) throw error
      savedMember = data
    }

    return NextResponse.json({
      ok: true,
      member: savedMember,
      temporary_password: senha || null,
      message: existingMember?.id ? 'Funcionário atualizado.' : 'Funcionário criado.',
    })
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Erro ao salvar funcionário.' },
      { status: 500 }
    )
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const requester = await getRequester(request)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const body = await request.json()
    const id = String(body.id || '').trim()

    if (!isUuid(id)) {
      return NextResponse.json({ error: 'Funcionário inválido. Recarregue a página e tente novamente.' }, { status: 400 })
    }

    const cargo = body.cargo ? cleanCargo(body.cargo) : null
    const status = ['ativo', 'bloqueado', 'removido'].includes(body.status) ? body.status : null
    const nome = body.nome ? String(body.nome).trim() : null

    const { company, requesterRole } = await getCompanyForUser(requester.id, requester.email || '')

    if (!company?.id || !isUuid(company.id)) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (requesterRole !== 'dono' && requester.email?.toLowerCase() !== 'araujovinicius249@gmail.com') {
      return NextResponse.json({ error: 'Somente o dono da empresa pode alterar funcionários.' }, { status: 403 })
    }

    const update: Record<string, any> = {
      updated_at: new Date().toISOString(),
    }

    if (cargo) {
      update.cargo = cargo
      update.permissions = cargoPermissions[cargo] || cargoPermissions.atendente
    }

    if (status) update.status = status
    if (nome) update.nome = nome

    const { data, error } = await supabaseAdmin
      .from('company_members')
      .update(update)
      .eq('id', id)
      .eq('company_id', company.id)
      .select('id,company_id,user_id,nome,email,cargo,status,permissions,created_at,updated_at')
      .maybeSingle()

    if (error) throw error
    if (!data) return NextResponse.json({ error: 'Funcionário não encontrado.' }, { status: 404 })

    return NextResponse.json({ ok: true, member: data })
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Erro ao alterar funcionário.' },
      { status: 500 }
    )
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const requester = await getRequester(request)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const { searchParams } = new URL(request.url)
    const id = String(searchParams.get('id') || '').trim()

    if (!isUuid(id)) {
      return NextResponse.json({ error: 'Funcionário inválido. Recarregue a página e tente novamente.' }, { status: 400 })
    }

    const { company, requesterRole } = await getCompanyForUser(requester.id, requester.email || '')

    if (!company?.id || !isUuid(company.id)) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (requesterRole !== 'dono' && requester.email?.toLowerCase() !== 'araujovinicius249@gmail.com') {
      return NextResponse.json({ error: 'Somente o dono da empresa pode remover funcionários.' }, { status: 403 })
    }

    const { error } = await supabaseAdmin
      .from('company_members')
      .update({
        status: 'removido',
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .eq('company_id', company.id)

    if (error) throw error

    return NextResponse.json({ ok: true })
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Erro ao remover funcionário.' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { assinaturaEstaAtiva, companyPlanAllows, getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { createAuditLog } from '@/lib/orcaly-audit'
