      .from('orders')
      .update(update)
      .eq('id', id)
      .eq('company_id', result.access!.company.id)
      .select('*')
      .single()

    if (error) throw error

    let whatsappResult: any = null

    if (update.status && update.status !== previous?.status) {
      await result.supabaseAdmin
        .from('order_status_history')
        .insert({
          company_id: result.access!.company.id,
          order_id: id,
          old_status: previous?.status || null,
          new_status: update.status,
          changed_by: result.requester!.id,
          changed_by_email: result.requester!.email || null,
          note: body.note || null,
        })

      await createNotification(result.supabaseAdmin, {
        company_id: result.access!.company.id,
        user_id: result.requester!.id,
        tipo: 'order',
        titulo: 'Status do pedido atualizado',
        mensagem: `${previous?.nome || 'Pedido'} agora está em ${update.status}.`,
        link_url: `/painel/pedidos/${id}`,
        payload: { order_id: id, status: update.status },
      })

      whatsappResult = await notifyOrderStatus(result.supabaseAdmin, {
        company: result.access!.company,
        order,
        status: update.status,
        source: 'status_update',
      })
    }

    await createAuditLog(result.supabaseAdmin, {
      company_id: result.access!.company.id,
      user_id: result.requester!.id,
      action: 'order.updated',
      entity: 'orders',
      entity_id: id,
      details: {
        ...update,
        whatsapp: whatsappResult || undefined,
      },
      request,
    })

    return NextResponse.json({ ok: true, order, whatsapp: whatsappResult })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao atualizar pedido.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin, isUuid } from '@/lib/company-access'
import { notifyNewOrder } from '@/lib/whatsapp-notifications'

export async function POST(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)
    if (!access.company?.id) return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })

    const body = await request.json()
    const orderId = String(body.order_id || '')

    if (!isUuid(orderId)) {
      return NextResponse.json({ error: 'Pedido inválido.' }, { status: 400 })
    }

    const { data: original, error: orderError } = await supabaseAdmin
      .from('orders')
      .select('*')
      .eq('id', orderId)
      .eq('company_id', access.company.id)
      .maybeSingle()

    if (orderError) throw orderError
    if (!original) return NextResponse.json({ error: 'Pedido original não encontrado.' }, { status: 404 })

    const { data: newOrder, error: insertError } = await supabaseAdmin
      .from('orders')
      .insert({
        company_id: access.company.id,
        nome: original.nome,
        telefone: original.telefone,
        produto: original.produto,
        largura: original.largura,
        altura: original.altura,
        quantidade: original.quantidade,
        observacoes: body.observacao || `Pedido repetido a partir de ${original.id}`,
        status: 'Recebido',
        preco_estimado: original.preco_estimado,
        valor_total: original.valor_total,
        arquivo_url: original.arquivo_url,
        itens_resumo: original.itens_resumo,
        dados_inteligentes: original.dados_inteligentes,
        source: 'recorrente',
        original_order_id: original.id,
      })
      .select('*')
      .single()

    if (insertError) throw insertError

    try {
      await notifyNewOrder(supabaseAdmin, {
        company: access.company,
        order: newOrder,
        cliente: { nome: newOrder.nome, telefone: newOrder.telefone },
        total: Number(newOrder.valor_total || newOrder.preco_estimado || 0),
        resumo: newOrder.itens_resumo || newOrder.produto || 'Pedido repetido',
      })
    } catch (notifyError) {
      console.error('[Orçaly WhatsApp] Falha ao notificar pedido repetido:', notifyError)
    }

    const { data: originalItems } = await supabaseAdmin
      .from('order_items')
      .select('*')
      .eq('order_id', original.id)

    if (Array.isArray(originalItems) && originalItems.length > 0) {
      const clonedItems = originalItems.map((item: any) => ({
        company_id: access.company.id,
        order_id: newOrder.id,
        product_id: item.product_id || null,
        nome: item.nome,
        tipo: item.tipo,
        unidade: item.unidade,
        quantidade: item.quantidade,
        preco_unitario: item.preco_unitario,
        subtotal: item.subtotal,
        largura: item.largura,
        altura: item.altura,
        comprimento: item.comprimento,
        area_m2: item.area_m2,
        precificacao: item.precificacao,
        detalhes_calculo: item.detalhes_calculo,
        respostas: item.respostas || {},
      }))

      await supabaseAdmin.from('order_items').insert(clonedItems)
    }

    await supabaseAdmin
      .from('recurring_orders')
      .insert({
        company_id: access.company.id,
        original_order_id: original.id,
        customer_name: original.nome,
        customer_phone: original.telefone,
        title: original.produto || 'Pedido recorrente',
        frequency: body.frequency || 'manual',
        last_repeated_at: new Date().toISOString(),
        notes: body.observacao || null,
        created_by: requester.id,
      })

    return NextResponse.json({ ok: true, order: newOrder })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao repetir pedido.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin, isUuid } from '@/lib/company-access'

export async function PATCH(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)
    if (!access.company?.id) return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    if (!access.canProduction) return NextResponse.json({ error: 'Seu perfil não pode alterar produção.' }, { status: 403 })

    const body = await request.json()
    const id = String(body.id || '')

    if (!isUuid(id)) return NextResponse.json({ error: 'Ordem inválida.' }, { status: 400 })

    const update: Record<string, any> = {
      updated_at: new Date().toISOString(),
    }

    for (const key of ['status', 'priority', 'responsible_name', 'internal_notes']) {
      if (body[key] !== undefined) update[key] = body[key]
    }

    if (body.due_date !== undefined) update.due_date = body.due_date || null
    if (body.files !== undefined) update.files = Array.isArray(body.files) ? body.files : []

    const { data, error } = await supabaseAdmin
      .from('production_orders')
      .update(update)
      .eq('id', id)
      .eq('company_id', access.company.id)
      .select('*')
      .single()

    if (error) throw error

    return NextResponse.json({ ok: true, order: data })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao atualizar produção.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { createAuditLog } from '@/lib/orcaly-audit'
import { normalizeBusinessType } from '@/lib/business-types'

type Context = {
  params: Promise<{ id: string }>
}

const allowedFields = [
  'nome',
  'descricao',
  'descricao_curta',
  'descricao_detalhada',
  'preco',
  'ativo',
  'available',
  'tipo',
  'business_type',
  'categoria',
  'subcategoria',
  'preco_sob_consulta',
  'unidade_preco',
  'estoque',
  'sku',
  'promocao_ativa',
  'preco_promocional',
  'destaque',
  'oculto',
  'arquivado',
  'video_url',
  'image_urls',
  'extras',
  'variations',
  'addons',
  'adicionais',
  'variacoes',
  'campos_orcamento',
  'configuracoes',
]

async function getAccess(request: NextRequest) {
  const supabaseAdmin = getSupabaseAdmin()
  const requester = await getRequester(request, supabaseAdmin)

  if (!requester) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Não autorizado.' }, { status: 401 }) }
  }

  const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

  if (!access.company?.id) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 }) }
  }

  return { supabaseAdmin, requester, access }
}

function ensureArray(value: any) {
  return Array.isArray(value) ? value : []
}

function cleanUpdate(body: any, fallbackBusinessType: string) {
  const update: Record<string, any> = {}

  for (const field of allowedFields) {
    if (body[field] !== undefined) update[field] = body[field]
  }

  if (update.preco !== undefined) update.preco = Number(update.preco || 0)
  if (update.preco_promocional !== undefined) update.preco_promocional = Number(update.preco_promocional || 0)
  if (update.estoque !== undefined && update.estoque !== null && update.estoque !== '') update.estoque = Number(update.estoque || 0)
  if (update.estoque === '') update.estoque = null

  if (update.business_type !== undefined) update.business_type = normalizeBusinessType(update.business_type || fallbackBusinessType)
  if (update.available !== undefined) update.available = Boolean(update.available)

  if (update.image_urls !== undefined) update.image_urls = ensureArray(update.image_urls).slice(0, 4)
  if (update.addons !== undefined) update.addons = ensureArray(update.addons)
  if (update.variations !== undefined) update.variations = ensureArray(update.variations)
  if (update.adicionais !== undefined) update.adicionais = ensureArray(update.adicionais)
  if (update.variacoes !== undefined) update.variacoes = ensureArray(update.variacoes)
  if (update.campos_orcamento !== undefined) update.campos_orcamento = ensureArray(update.campos_orcamento)
  if (update.extras !== undefined && (typeof update.extras !== 'object' || Array.isArray(update.extras))) update.extras = {}
  if (update.configuracoes !== undefined && (typeof update.configuracoes !== 'object' || Array.isArray(update.configuracoes))) update.configuracoes = {}

  update.updated_at = new Date().toISOString()

  return update
}

export async function GET(request: NextRequest, context: Context) {
  try {
    const { id } = await context.params
    const result = await getAccess(request)
    if ('error' in result && result.error) return result.error

    const { data, error } = await result.supabaseAdmin
      .from('products')
      .select('*')
      .eq('id', id)
      .eq('company_id', result.access!.company.id)
      .single()

    if (error) throw error

    return NextResponse.json({ product: data })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao carregar produto.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest, context: Context) {
  try {
    const { id } = await context.params
    const result = await getAccess(request)
    if ('error' in result && result.error) return result.error

    if (!result.access!.canProducts) {
      return NextResponse.json({ error: 'Seu perfil não pode editar produtos.' }, { status: 403 })
    }

    const body = await request.json()
    const update = cleanUpdate(body, result.access!.company.business_type || 'services')

    const { data, error } = await result.supabaseAdmin
      .from('products')
      .update(update)
      .eq('id', id)
      .eq('company_id', result.access!.company.id)
      .select('*')
      .single()

    if (error) throw error

    await createAuditLog(result.supabaseAdmin, {
      company_id: result.access!.company.id,
      user_id: result.requester!.id,
      action: 'product.updated',
      entity: 'products',
      entity_id: id,
      details: update,
      request,
    })

    return NextResponse.json({ ok: true, product: data })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao atualizar produto.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import crypto from 'crypto'
import { generatePixPayload, sanitizeTxid } from '@/lib/pix'
import { notifyProposalAction } from '@/lib/whatsapp-notifications'

type RouteContext = {
  params: Promise<{ token: string }>
}

function getSupabaseAdmin() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!url || !key) throw new Error('Variáveis do Supabase não configuradas no servidor.')

  return createClient(url, key, {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
    },
  })
}

function getIp(request: NextRequest) {
  return request.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    || request.headers.get('x-real-ip')
    || ''
}

function makeHash(parts: Array<string | null | undefined>) {
  return crypto.createHash('sha256').update(parts.join('|')).digest('hex')
}

async function insertEvent(supabaseAdmin: any, proposal: any, event: {
  event_type: string
  actor_type?: string
  actor_name?: string
  actor_email?: string
  note?: string
  metadata?: any
  ip?: string
  user_agent?: string
}) {
  await supabaseAdmin.from('proposal_events').insert({
    proposal_id: proposal.id,
    company_id: proposal.company_id,
    event_type: event.event_type,
    actor_type: event.actor_type || 'client',
    actor_name: event.actor_name || null,
    actor_email: event.actor_email || null,
    note: event.note || null,
    metadata: event.metadata || {},
    ip: event.ip || null,
    user_agent: event.user_agent || null,
  })
}

async function getProposalBundle(supabaseAdmin: any, token: string) {
  const { data: proposta, error: propostaError } = await supabaseAdmin
    .from('proposals')
    .select('*')
    .eq('token', token)
    .maybeSingle()

  if (propostaError) throw propostaError
  if (!proposta) return null

  const { data: empresa, error: empresaError } = await supabaseAdmin
    .from('companies')
    .select(`
      id,
      nome,
      slug,
      logo_url,
      whatsapp,
      instagram,
      pix_key,
      pix_nome,
      pix_cidade,
      aceita_pix,
      cobrar_sinal,
      percentual_sinal,
      site_primary_color,
      site_accent_color,
      marketplace_endereco,
      atendimento_horario
    `)
    .eq('id', proposta.company_id)
    .maybeSingle()

  if (empresaError) throw empresaError

  const { data: config } = await supabaseAdmin
    .from('company_proposal_settings')
    .select('*')
    .eq('company_id', proposta.company_id)
    .maybeSingle()

  const { data: events } = await supabaseAdmin
    .from('proposal_events')
    .select('id,event_type,actor_type,actor_name,note,metadata,created_at')
    .eq('proposal_id', proposta.id)
    .order('created_at', { ascending: true })

  return { proposta, empresa, config, events: events || [] }
}

async function createProductionOrder(supabaseAdmin: any, proposta: any, config: any) {
  if (!config?.auto_create_production) return null

  const existing = await supabaseAdmin
    .from('production_orders')
    .select('id')
    .eq('proposal_id', proposta.id)
    .maybeSingle()

  if (existing.data?.id) return existing.data.id

  const due = new Date()
  due.setDate(due.getDate() + 7)

  const { data: order, error } = await supabaseAdmin
    .from('production_orders')
    .insert({
      company_id: proposta.company_id,
      proposal_id: proposta.id,
      order_id: proposta.order_id,
      title: proposta.titulo || proposta.proposta_numero || 'Ordem de produção',
      customer_name: proposta.cliente_nome,
      customer_whatsapp: proposta.cliente_whatsapp,
      total_value: Number(proposta.valor_total || 0),
      signal_value: Number(proposta.valor_sinal || 0),
      status: Number(proposta.valor_sinal || 0) > 0 ? 'aguardando_sinal' : 'aprovado',
      due_date: due.toISOString(),
      metadata: {
        proposal_token: proposta.token,
        proposal_number: proposta.proposta_numero,
      },
    })
    .select('id')
    .single()

  if (error) throw error

  const rawSteps = Array.isArray(config?.default_production_steps) && config.default_production_steps.length > 0
    ? config.default_production_steps
    : [
        { titulo: 'Conferir informações do cliente', descricao: 'Validar itens, medidas e observações.' },
        { titulo: 'Separar materiais', descricao: 'Separar insumos ou arquivos necessários.' },
        { titulo: 'Produzir/executar', descricao: 'Realizar a produção ou serviço.' },
        { titulo: 'Revisar qualidade', descricao: 'Conferir acabamento e qualidade final.' },
        { titulo: 'Entregar ao cliente', descricao: 'Registrar entrega, retirada ou envio.' },
      ]

  const steps = rawSteps.map((step: any, index: number) => ({
    production_order_id: order.id,
    company_id: proposta.company_id,
    title: step.titulo || step.title || `Etapa ${index + 1}`,
    description: step.descricao || step.description || null,
    status: 'pendente',
    sort_order: index + 1,
  }))

  if (steps.length > 0) {
    await supabaseAdmin.from('production_steps').insert(steps)
  }

  await supabaseAdmin
    .from('proposals')
    .update({
      converted_to_production: true,
      production_order_id: order.id,
      updated_at: new Date().toISOString(),
    })
    .eq('id', proposta.id)

  await supabaseAdmin.from('notifications').insert({
    company_id: proposta.company_id,
    type: 'proposal_approved',
    title: 'Proposta aprovada',
    message: `${proposta.cliente_nome || 'Cliente'} aprovou uma proposta.`,
    link: `/painel/producao`,
    priority: 'alta',
    metadata: {
      proposal_id: proposta.id,
      production_order_id: order.id,
    },
  })

  return order.id
}

export async function GET(request: NextRequest, context: RouteContext) {
  try {
    const { token } = await context.params
    const supabaseAdmin = getSupabaseAdmin()
    const bundle = await getProposalBundle(supabaseAdmin, token)

    if (!bundle) return NextResponse.json({ error: 'Proposta não encontrada.' }, { status: 404 })

    const { proposta, empresa, config, events } = bundle
    const now = new Date()

    if (proposta.valid_until && ['enviado', 'visto'].includes(proposta.status) && new Date(proposta.valid_until) < now) {
      await supabaseAdmin
        .from('proposals')
        .update({ status: 'expirado', expired_at: now.toISOString(), updated_at: now.toISOString() })
        .eq('id', proposta.id)

      proposta.status = 'expirado'
      proposta.expired_at = now.toISOString()
    }

    if (proposta.status === 'enviado') {
      const viewedAt = new Date().toISOString()

      await supabaseAdmin
        .from('proposals')
        .update({
          status: 'visto',
          viewed_at: proposta.viewed_at || viewedAt,
          updated_at: viewedAt,
        })
        .eq('id', proposta.id)

      await insertEvent(supabaseAdmin, proposta, {
        event_type: 'viewed',
        actor_type: 'client',
        note: 'Cliente abriu a proposta.',
        ip: getIp(request),
        user_agent: request.headers.get('user-agent') || '',
      })

      proposta.status = 'visto'
      proposta.viewed_at = proposta.viewed_at || viewedAt
    }

    return NextResponse.json({
      proposta,
      empresa: empresa ? {
        id: empresa.id,
        nome: empresa.nome,
        slug: empresa.slug,
        logo_url: empresa.logo_url,
        whatsapp: empresa.whatsapp,
        instagram: empresa.instagram,
        site_primary_color: empresa.site_primary_color || '#05245c',
        site_accent_color: empresa.site_accent_color || '#22c55e',
        marketplace_endereco: empresa.marketplace_endereco,
        atendimento_horario: empresa.atendimento_horario,
        aceita_pix: empresa.aceita_pix !== false,
      } : null,
      config: {
        require_document: Boolean(config?.require_document),
        require_drawn_signature: config?.require_drawn_signature !== false,
        require_signature_name: config?.require_signature_name !== false,
        allow_print_pdf: config?.allow_print_pdf !== false,
      },
      events,
    })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro desconhecido.' }, { status: 500 })
  }
}

export async function POST(request: NextRequest, context: RouteContext) {
  try {
    const { token } = await context.params
    const body = await request.json()
    const action = String(body.acao || '')

    const supabaseAdmin = getSupabaseAdmin()
    const bundle = await getProposalBundle(supabaseAdmin, token)

    if (!bundle) return NextResponse.json({ error: 'Proposta não encontrada.' }, { status: 404 })

    const { proposta, empresa, config } = bundle
    const now = new Date().toISOString()
    const ip = getIp(request)
    const userAgent = request.headers.get('user-agent') || ''

    if (['expirado', 'cancelado', 'recusado'].includes(proposta.status)) {
      return NextResponse.json({ error: 'Esta proposta não está mais disponível para resposta.' }, { status: 400 })
    }

    if (action === 'aprovar') {
      const approvalName = String(body.nome || proposta.cliente_nome || '').trim()
      const approvalDocument = String(body.documento || '').trim()
      const approvalNote = String(body.observacao || '').trim()
      const acceptedTerms = Boolean(body.aceitou_termos)
      const signatureDataUrl = String(body.assinatura_data_url || '').trim()

      if (!approvalName) return NextResponse.json({ error: 'Informe o nome de quem está aprovando.' }, { status: 400 })
      if (config?.require_document && !approvalDocument) return NextResponse.json({ error: 'Informe CPF/CNPJ para aprovar.' }, { status: 400 })
      if (config?.require_drawn_signature !== false && !signatureDataUrl) return NextResponse.json({ error: 'Assine no campo de assinatura para aprovar.' }, { status: 400 })
      if (!acceptedTerms) return NextResponse.json({ error: 'Confirme que leu e aceita as condições da proposta.' }, { status: 400 })

      let pixPayload = proposta.pix_payload || ''
      let pixTxid = proposta.pix_txid || ''
      let pixValor = Number(proposta.pix_valor || proposta.valor_sinal || 0)

      if (!pixPayload && config?.auto_generate_pix !== false && empresa?.aceita_pix !== false && empresa?.pix_key && Number(proposta.valor_sinal || 0) > 0) {
        pixTxid = sanitizeTxid(`PROP${String(Date.now()).slice(-10)}`)
        pixValor = Number(proposta.valor_sinal || 0)

        pixPayload = generatePixPayload({
          key: empresa.pix_key,
          merchantName: empresa.pix_nome || empresa.nome || 'ORCALY',
          merchantCity: empresa.pix_cidade || 'MACEIO',
          amount: pixValor,
          txid: pixTxid,
          description: `Sinal proposta ${proposta.proposta_numero || proposta.token}`.slice(0, 60),
        })
      }

      const hash = makeHash([
        proposta.id,
        proposta.token,
        approvalName,
        approvalDocument,
        ip,
        signatureDataUrl ? crypto.createHash('sha256').update(signatureDataUrl).digest('hex') : '',
        now,
      ])

      const contractSnapshot = {
        empresa: empresa?.nome,
        cliente_nome: approvalName,
        cliente_documento: approvalDocument || null,
        proposta_numero: proposta.proposta_numero,
        valor_total: proposta.valor_total,
        valor_sinal: proposta.valor_sinal,
        prazo: proposta.prazo,
        condicoes: proposta.condicoes,
        itens: proposta.itens,
        accepted_at: now,
        approval_hash: hash,
      }

      const { data, error } = await supabaseAdmin
        .from('proposals')
        .update({
          status: 'aprovado',
          approved_at: now,
          approval_name: approvalName,
          approval_document: approvalDocument || null,
          approval_note: approvalNote || null,
          accepted_terms: true,
          approval_hash: hash,
          signature_name: approvalName,
          signature_data_url: signatureDataUrl || null,
          signature_signed_at: now,
          contract_snapshot: contractSnapshot,
          client_ip: ip,
          user_agent: userAgent,
          pix_payload: pixPayload || null,
          pix_txid: pixTxid || null,
          pix_valor: pixValor || null,
          updated_at: now,
        })
        .eq('id', proposta.id)
        .select('*')
        .maybeSingle()

      if (error) return NextResponse.json({ error: error.message }, { status: 500 })
      if (!data) return NextResponse.json({ error: 'Proposta não encontrada.' }, { status: 404 })

      await insertEvent(supabaseAdmin, proposta, {
        event_type: 'approved',
        actor_type: 'client',
        actor_name: approvalName,
        note: approvalNote || 'Cliente aprovou e assinou a proposta.',
        metadata: {
          approval_document: approvalDocument || null,
          accepted_terms: true,
          approval_hash: hash,
          has_signature: Boolean(signatureDataUrl),
          pix_generated: Boolean(pixPayload),
          pix_valor: pixValor || null,
        },
        ip,
        user_agent: userAgent,
      })

      if (proposta.order_id) {
        await supabaseAdmin
          .from('orders')
          .update({ status: pixPayload ? 'Proposta aprovada - aguardando sinal' : 'Proposta aprovada' })
          .eq('id', proposta.order_id)
      }

      const productionOrderId = await createProductionOrder(supabaseAdmin, data, config || {})

      try {
        await notifyProposalAction(supabaseAdmin, {
          company: empresa,
          proposal: data,
          event: 'approved',
          note: approvalNote || null,
          pixValor: pixValor || null,
        })
      } catch (proposal_approved_whatsapp) {
        console.error('[Orçaly WhatsApp] Falha ao avisar proposta aprovada:', proposal_approved_whatsapp)
      }

      return NextResponse.json({
        ok: true,
        status: data.status,
        proposta: {
          ...data,
          production_order_id: productionOrderId || data.production_order_id,
        },
        pix_payload: pixPayload || null,
        pix_valor: pixValor || null,
        approval_hash: hash,
        production_order_id: productionOrderId,
      })
    }

    if (action === 'alteracao') {
      const note = String(body.mensagem || '').trim()
      if (!note) return NextResponse.json({ error: 'Escreva o que precisa ser alterado.' }, { status: 400 })

      const { data, error } = await supabaseAdmin
        .from('proposals')
        .update({
          status: 'alteracao_solicitada',
          change_requested_at: now,
          approval_note: note,
          client_ip: ip,
          user_agent: userAgent,
          updated_at: now,
        })
        .eq('id', proposta.id)
        .select('*')
        .maybeSingle()

      if (error) return NextResponse.json({ error: error.message }, { status: 500 })

      await insertEvent(supabaseAdmin, proposta, {
        event_type: 'change_requested',
        actor_type: 'client',
        actor_name: body.nome || proposta.cliente_nome || null,
        note,
        ip,
        user_agent: userAgent,
      })

      await supabaseAdmin.from('notifications').insert({
        company_id: proposta.company_id,
        type: 'proposal_change_requested',
        title: 'Cliente pediu alteração',
        message: `${proposta.cliente_nome || 'Cliente'} pediu alteração em uma proposta.`,
        link: `/painel/proposta/${proposta.order_id || ''}`,
        priority: 'alta',
        metadata: { proposal_id: proposta.id, order_id: proposta.order_id },
      })

      if (proposta.order_id) await supabaseAdmin.from('orders').update({ status: 'Cliente pediu alteração na proposta' }).eq('id', proposta.order_id)

      return NextResponse.json({ ok: true, status: data?.status, proposta: data })
    }

    if (action === 'recusar') {
      const reason = String(body.motivo || '').trim()
      if (!reason) return NextResponse.json({ error: 'Informe o motivo da recusa.' }, { status: 400 })

      const { data, error } = await supabaseAdmin
        .from('proposals')
        .update({
          status: 'recusado',
          rejected_at: now,
          rejection_reason: reason,
          client_ip: ip,
          user_agent: userAgent,
          updated_at: now,
        })
        .eq('id', proposta.id)
        .select('*')
        .maybeSingle()

      if (error) return NextResponse.json({ error: error.message }, { status: 500 })

      await insertEvent(supabaseAdmin, proposta, {
        event_type: 'rejected',
        actor_type: 'client',
        actor_name: body.nome || proposta.cliente_nome || null,
        note: reason,
        ip,
        user_agent: userAgent,
      })

      await supabaseAdmin.from('notifications').insert({
        company_id: proposta.company_id,
        type: 'proposal_rejected',
        title: 'Proposta recusada',
        message: `${proposta.cliente_nome || 'Cliente'} recusou uma proposta.`,
        link: `/painel/propostas`,
        priority: 'normal',
        metadata: { proposal_id: proposta.id, order_id: proposta.order_id },
      })

      if (proposta.order_id) await supabaseAdmin.from('orders').update({ status: 'Proposta recusada' }).eq('id', proposta.order_id)

      try {
        await notifyProposalAction(supabaseAdmin, {
          company: empresa,
          proposal: data || proposta,
          event: 'rejected',
          note: reason,
        })
      } catch (proposal_rejected_whatsapp) {
        console.error('[Orçaly WhatsApp] Falha ao avisar recusa de proposta:', proposal_rejected_whatsapp)
      }

      return NextResponse.json({ ok: true, status: data?.status, proposta: data })
    }

    return NextResponse.json({ error: 'Ação inválida.' }, { status: 400 })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro desconhecido.' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'

async function tableCount(supabaseAdmin: any, table: string, companyId: string) {
  try {
    const { count, error } = await supabaseAdmin
      .from(table)
      .select('id', { count: 'exact', head: true })
      .eq('company_id', companyId)

    if (error) return { ok: false, count: 0, error: error.message }

    return { ok: true, count: count || 0 }
  } catch (error) {
    return { ok: false, count: 0, error: error instanceof Error ? error.message : 'Erro desconhecido' }
  }
}

export async function GET(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const requester = await getRequester(request, supabaseAdmin)

    if (!requester) {
      return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })
    }

    const access = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

    if (!access.company?.id) {
      return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    }

    if (!access.canManage) {
      return NextResponse.json({ error: 'Seu perfil não pode ver auditoria.' }, { status: 403 })
    }

    const companyId = access.company.id

    const { data: storageBuckets, error: storageError } =
      await supabaseAdmin.storage.listBuckets()
    const storageNames = new Set(
      (storageBuckets || []).map((bucket) => bucket.name),
    )
    const requiredStorageBuckets = [
      'site-assets',
      'produtos',
      'financeiro',
      'artes',
    ]
    const missingStorageBuckets = requiredStorageBuckets.filter(
      (bucket) => !storageNames.has(bucket),
    )

    const [
      products,
      orders,
      proposals,
      leads,
      tasks,
      coupons,
      notifications,
    ] = await Promise.all([
      tableCount(supabaseAdmin, 'products', companyId),
      tableCount(supabaseAdmin, 'orders', companyId),
      tableCount(supabaseAdmin, 'proposals', companyId),
      tableCount(supabaseAdmin, 'crm_leads', companyId),
      tableCount(supabaseAdmin, 'internal_tasks', companyId),
      tableCount(supabaseAdmin, 'marketplace_coupons', companyId),
      tableCount(supabaseAdmin, 'app_notifications', companyId),
    ])

    const checks = [
      {
        key: 'supabase',
        title: 'Supabase',
        ok: Boolean(process.env.NEXT_PUBLIC_SUPABASE_URL && process.env.SUPABASE_SERVICE_ROLE_KEY),
        description: 'Variáveis do Supabase configuradas.',
      },
      {
        key: 'site',
        title: 'Site público',
        ok: Boolean(access.company.site_publico_ativo && access.company.slug),
        description: access.company.slug ? `/site/${access.company.slug}` : 'Slug não definido.',
      },
      {
        key: 'storage',
        title: 'Supabase Storage',
        ok: !storageError && missingStorageBuckets.length === 0,
        description: storageError
          ? 'Não foi possível consultar os buckets.'
          : missingStorageBuckets.length
            ? `Buckets ausentes: ${missingStorageBuckets.join(', ')}.`
            : 'Buckets essenciais disponíveis.',
      },
      {
        key: 'mercado_pago',
        title: 'Mercado Pago',
        ok: Boolean(
          process.env.MP_MARKETPLACE_CLIENT_ID &&
          process.env.MP_MARKETPLACE_CLIENT_SECRET &&
          process.env.MP_MARKETPLACE_WEBHOOK_SECRET
        ),
        description: 'Credenciais e segredo do marketplace configurados.',
      },
      {
        key: 'openai_direct',
        title: 'IA interna / OpenAI',
        ok: Boolean(process.env.OPENAI_API_KEY),
        description: 'Credencial do assistente interno configurada.',
      },
      {
        key: 'ai_gateway',
        title: 'IA pública / Vercel AI Gateway',
        ok: Boolean(
          process.env.AI_GATEWAY_API_KEY ||
          process.env.VERCEL_OIDC_TOKEN
        ),
        description: 'Credencial ou identidade do AI Gateway disponível.',
      },
      {
        key: 'cron',
        title: 'Cron administrativo',
        ok: Boolean(process.env.CRON_SECRET),
        description: 'CRON_SECRET protege a execução automática do scanner.',
      },
      {
        key: 'whatsapp',
        title: 'WhatsApp',
        ok: Boolean(access.company.whatsapp_enabled || access.company.whatsapp),
        description: access.company.whatsapp_enabled ? 'WhatsApp IA ativado.' : 'Número de WhatsApp informado ou integração pendente.',
      },
    ]

    return NextResponse.json({
      company: {
        id: access.company.id,
        nome: access.company.nome,
        slug: access.company.slug,
        plano: access.company.assinatura_plano || access.company.plano,
        assinatura_status: access.company.assinatura_status,
      },
      checks,
      modules: {
        products,
        orders,
        proposals,
        leads,
        tasks,
        coupons,
        notifications,
      },
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao verificar saúde do sistema.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { createAuditLog } from '@/lib/orcaly-audit'

type Context = {
  params: Promise<{ id: string }>
}

async function access(request: NextRequest) {
  const supabaseAdmin = getSupabaseAdmin()
  const requester = await getRequester(request, supabaseAdmin)

  if (!requester) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Não autorizado.' }, { status: 401 }) }
  }

  const companyAccess = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

  if (!companyAccess.company?.id) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 }) }
  }

  return { supabaseAdmin, requester, companyAccess }
}

function cleanUpdate(body: any) {
  const allowed = [
    'titulo',
    'descricao',
    'status',
    'prioridade',
    'due_at',
    'responsavel_id',
    'crm_lead_id',
    'order_id',
    'proposal_id',
  ]

  const update: Record<string, any> = {}

  for (const field of allowed) {
    if (body[field] !== undefined) update[field] = body[field]
  }

  if (update.status === 'concluida') update.completed_at = new Date().toISOString()
  if (update.status && update.status !== 'concluida') update.completed_at = null
  update.updated_at = new Date().toISOString()

  return update
}

export async function PATCH(request: NextRequest, context: Context) {
  try {
    const { id } = await context.params
    const result = await access(request)
    if ('error' in result && result.error) return result.error

    const body = await request.json()
    const update = cleanUpdate(body)

    const { data, error } = await result.supabaseAdmin
      .from('internal_tasks')
      .update(update)
      .eq('id', id)
      .eq('company_id', result.companyAccess!.company.id)
      .select('*')
      .single()

    if (error) throw error

    await createAuditLog(result.supabaseAdmin, {
      company_id: result.companyAccess!.company.id,
      user_id: result.requester!.id,
      action: 'task.updated',
      entity: 'internal_tasks',
      entity_id: id,
      details: update,
      request,
    })

    return NextResponse.json({ ok: true, task: data })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao atualizar tarefa.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin } from '@/lib/company-access'
import { createAuditLog, createNotification } from '@/lib/orcaly-audit'

function cleanTask(body: any) {
  const titulo = String(body.titulo || '').trim()
  if (!titulo) throw new Error('Informe o título da tarefa.')

  return {
    titulo,
    descricao: String(body.descricao || '').trim() || null,
    status: String(body.status || 'pendente'),
    prioridade: String(body.prioridade || 'media'),
    due_at: body.due_at || null,
    responsavel_id: body.responsavel_id || null,
    crm_lead_id: body.crm_lead_id || null,
    order_id: body.order_id || null,
    proposal_id: body.proposal_id || null,
  }
}

async function access(request: NextRequest) {
  const supabaseAdmin = getSupabaseAdmin()
  const requester = await getRequester(request, supabaseAdmin)

  if (!requester) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Não autorizado.' }, { status: 401 }) }
  }

  const companyAccess = await getCompanyAccess(supabaseAdmin, requester.id, requester.email)

  if (!companyAccess.company?.id) {
    return { supabaseAdmin, error: NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 }) }
  }

  return { supabaseAdmin, requester, companyAccess }
}

export async function GET(request: NextRequest) {
  try {
    const result = await access(request)
    if ('error' in result && result.error) return result.error

    const { searchParams } = new URL(request.url)
    const status = searchParams.get('status')

    let query = result.supabaseAdmin
      .from('internal_tasks')
      .select('*')
      .eq('company_id', result.companyAccess!.company.id)
      .order('due_at', { ascending: true, nullsFirst: false })
      .order('created_at', { ascending: false })
      .limit(200)

    if (status && status !== 'todos') query = query.eq('status', status)

    const { data, error } = await query
    if (error) throw error

    return NextResponse.json({ tasks: data || [] })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao carregar tarefas.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  try {
    const result = await access(request)
    if ('error' in result && result.error) return result.error

    const body = await request.json()
    const payload = cleanTask(body)

    const { data, error } = await result.supabaseAdmin
      .from('internal_tasks')
      .insert({
        ...payload,
        company_id: result.companyAccess!.company.id,
        created_by: result.requester!.id,
      })
      .select('*')
      .single()

    if (error) throw error

    await createAuditLog(result.supabaseAdmin, {
      company_id: result.companyAccess!.company.id,
      user_id: result.requester!.id,
      action: 'task.created',
      entity: 'internal_tasks',
      entity_id: data.id,
      details: { titulo: data.titulo, prioridade: data.prioridade },
      request,
    })

    await createNotification(result.supabaseAdmin, {
      company_id: result.companyAccess!.company.id,
      user_id: data.responsavel_id || result.requester!.id,
      tipo: 'task',
      titulo: 'Nova tarefa criada',
      mensagem: data.titulo,
      link_url: '/painel/tarefas',
      payload: { task_id: data.id },
    })

    return NextResponse.json({ ok: true, task: data })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Erro ao criar tarefa.'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getCompanyAccess, getRequester, getSupabaseAdmin, isUuid } from '@/lib/company-access'
import { notifyOrderStatus } from '@/lib/whatsapp-notifications'

export async function POST(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const user = await getRequester(request, supabaseAdmin)
    if (!user) return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })

    const access = await getCompanyAccess(supabaseAdmin, user.id, user.email)
    if (!access.company?.id) return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })

    const body = await request.json()
    const status = String(body.status || '').trim()
    const orderId = String(body.order_id || '').trim()
    const productionOrderId = String(body.production_order_id || '').trim()
    if (!status) return NextResponse.json({ error: 'Status não informado.' }, { status: 400 })

    let order: any = null

    if (isUuid(orderId)) {
      const { data } = await supabaseAdmin.from('orders').select('*').eq('id', orderId).eq('company_id', access.company.id).maybeSingle()
      order = data
    }

    if (!order && isUuid(productionOrderId)) {
      const { data: prod } = await supabaseAdmin.from('production_orders').select('*').eq('id', productionOrderId).eq('company_id', access.company.id).maybeSingle()
      if (prod?.order_id) {
        const { data } = await supabaseAdmin.from('orders').select('*').eq('id', prod.order_id).eq('company_id', access.company.id).maybeSingle()
        order = data || { id: prod.order_id, nome: prod.customer_name, telefone: prod.customer_whatsapp, valor_total: prod.total_value }
      } else if (prod) {
        order = { id: prod.id, nome: prod.customer_name, telefone: prod.customer_whatsapp, valor_total: prod.total_value }
      }
    }

    if (!order) return NextResponse.json({ error: 'Pedido não encontrado.' }, { status: 404 })

    await notifyOrderStatus(supabaseAdmin, { company: access.company, order, status, source: body.source || 'manual' })
    return NextResponse.json({ ok: true })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro ao notificar status.' }, { status: 500 })
  }
}

