      updated_at: new Date().toISOString(),
    }

    const { data, error } = await supabaseAdmin.from('company_whatsapp_settings').upsert(payload, { onConflict: 'company_id' }).select('*').single()
    if (error) throw error
    return NextResponse.json({ ok: true, settings: normalize(data, access.company.id) })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro ao salvar WhatsApp.' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  try {
    const supabaseAdmin = getSupabaseAdmin()
    const user = await getRequester(request, supabaseAdmin)
    if (!user) return NextResponse.json({ error: 'Não autorizado.' }, { status: 401 })

    const access = await getCompanyAccess(supabaseAdmin, user.id, user.email)
    if (!access.company?.id) return NextResponse.json({ error: 'Empresa não encontrada.' }, { status: 404 })
    if (!access.canManage) return NextResponse.json({ error: 'Apenas dono ou gerente pode testar WhatsApp.' }, { status: 403 })

    const body = await request.json()
    const { data: settings } = await supabaseAdmin.from('company_whatsapp_settings').select('*').eq('company_id', access.company.id).maybeSingle()
    const result = await sendWhatsAppMessage(supabaseAdmin, {
      companyId: access.company.id,
      eventType: 'manual_test',
      to: body.to,
      text: body.text || `Teste do Orçaly para ${access.company.nome}.`,
      phoneNumberId: settings?.phone_number_id || null,
    })

    return NextResponse.json({ ok: result.ok, result })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro ao testar WhatsApp.' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getSupabaseAdmin } from '@/lib/company-access'
import { generateAiReply, getCompanyByWhatsAppPhoneNumberId, getWhatsAppSettings, saveInbound, sanitizePhone, sendWhatsAppMessage, verifyWhatsAppSignature } from '@/lib/whatsapp'

function parseText(message: any) {
  if (message?.type === 'text') return String(message.text?.body || '').trim()
  if (message?.type === 'button') return String(message.button?.text || message.button?.payload || '').trim()
  if (message?.type === 'interactive') return String(message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || '').trim()
  return ''
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const mode = searchParams.get('hub.mode')
  const token = searchParams.get('hub.verify_token')
  const challenge = searchParams.get('hub.challenge')
  if (mode === 'subscribe' && token === process.env.WHATSAPP_VERIFY_TOKEN) return new NextResponse(challenge || '', { status: 200 })
  return NextResponse.json({ error: 'Token inválido.' }, { status: 403 })
}

export async function POST(request: NextRequest) {
  try {
    const rawBody = await request.text()
    if (!verifyWhatsAppSignature(rawBody, request.headers.get('x-hub-signature-256'))) {
      return NextResponse.json({ error: 'Assinatura inválida.' }, { status: 403 })
    }

    const body = JSON.parse(rawBody || '{}')
    const supabaseAdmin = getSupabaseAdmin()

    for (const entry of Array.isArray(body.entry) ? body.entry : []) {
      for (const change of Array.isArray(entry.changes) ? entry.changes : []) {
        const value = change.value || {}
        const phoneNumberId = value.metadata?.phone_number_id || ''
        const businessPhone = value.metadata?.display_phone_number || ''
        const company = await getCompanyByWhatsAppPhoneNumberId(supabaseAdmin, phoneNumberId)
        if (!company?.id) continue

        const settings = await getWhatsAppSettings(supabaseAdmin, company.id)

        for (const status of Array.isArray(value.statuses) ? value.statuses : []) {
          await supabaseAdmin.from('whatsapp_message_logs').insert({
            company_id: company.id,
            direction: 'outbound',
            event_type: 'status_callback',
            to_phone: sanitizePhone(status.recipient_id || ''),
            message_type: 'status',
            content: status.status || null,
            status: status.status || 'status',
            meta_message_id: status.id || null,
            raw_payload: status,
          })
        }

        const contacts = Array.isArray(value.contacts) ? value.contacts : []

        for (const message of Array.isArray(value.messages) ? value.messages : []) {
          const from = sanitizePhone(message.from || '')
          if (!from) continue

          const contact = contacts.find((item: any) => sanitizePhone(item.wa_id) === from)
          const name = contact?.profile?.name || null
          const inboundText = parseText(message)

          await saveInbound(supabaseAdmin, {
            companyId: company.id,
            from,
            to: businessPhone,
            name,
            text: inboundText || `[${message.type || 'mensagem'}]`,
            raw: message,
          })

          if (!settings.enabled || !settings.ai_enabled) continue

          if (!inboundText) {
            await sendWhatsAppMessage(supabaseAdmin, {
              companyId: company.id,
              eventType: 'ai_fallback_non_text',
              to: from,
              text: settings.fallback_message,
              phoneNumberId: settings.phone_number_id || phoneNumberId,
            })
            continue
          }

          const { data: products } = await supabaseAdmin
            .from('products').select('nome,descricao,preco,ativo,arquivado,categoria,tipo')
            .eq('company_id', company.id).eq('ativo', true).limit(40)

          const reply = await generateAiReply({
            company,
            settings,
            inboundText,
            products: (products || []).filter((p: any) => p.arquivado !== true),
          })

          await sendWhatsAppMessage(supabaseAdmin, {
            companyId: company.id,
            eventType: 'ai_auto_reply',
            to: from,
            text: reply,
            phoneNumberId: settings.phone_number_id || phoneNumberId,
          })
        }
      }
    }

    return NextResponse.json({ received: true })
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : 'Erro no webhook WhatsApp.' }, { status: 500 })
  }
}

'use client'

import { useEffect, useState } from 'react'
import { useParams } from 'next/navigation'

export default function ArteAprovacaoPage() {
  const params = useParams<{ token: string }>()
  const token = params?.token
  const [request, setRequest] = useState<any>(null)
  const [comment, setComment] = useState('')
  const [loading, setLoading] = useState(true)
  const [message, setMessage] = useState('')
  const [error, setError] = useState('')

  async function load() {
    setLoading(true)
    setError('')

    const response = await fetch(`/api/arte/${token}`)
    const data = await response.json()

    if (!response.ok) {
      setError(data.error || 'Erro ao carregar arte.')
      setLoading(false)
      return
    }

    setRequest(data.request)
    setLoading(false)
  }

  async function submit(action: 'approve' | 'request_changes') {
    setError('')
    setMessage('')

    const response = await fetch(`/api/arte/${token}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, comment }),
    })

    const data = await response.json()

    if (!response.ok) {
      setError(data.error || 'Erro ao responder.')
      return
    }

    setRequest(data.request)
    setMessage(action === 'approve' ? 'Arte aprovada com sucesso.' : 'Alteração solicitada com sucesso.')
  }

  useEffect(() => {
    if (token) load()
  }, [token])

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#f5f8ff] px-4">
        <div className="rounded-[2rem] bg-white p-8 font-black shadow-xl">Carregando arte...</div>
      </main>
    )
  }

  if (error && !request) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#f5f8ff] px-4">
        <div className="max-w-lg rounded-[2rem] bg-white p-8 text-center shadow-xl">
          <h1 className="text-3xl font-black text-[#071b3a]">Arte não encontrada</h1>
          <p className="mt-3 font-bold text-red-600">{error}</p>
        </div>
      </main>
    )
  }

  const company = request?.companies

  return (
    <main className="min-h-screen overflow-x-hidden bg-[#f5f8ff] px-4 py-8 text-[#071b3a]">
      <section className="mx-auto max-w-5xl rounded-[2rem] border border-blue-100 bg-white p-5 shadow-2xl shadow-blue-950/10 sm:p-8">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <p className="text-sm font-black uppercase tracking-[0.2em] text-[#05245c]">Aprovação de arte</p>
            <h1 className="mt-2 text-3xl font-black tracking-[-0.04em] text-[#071b3a] sm:text-5xl">
              {request?.title || request?.produto_nome || 'Prévia da arte'}
            </h1>
            <p className="mt-3 font-bold text-slate-500">{company?.nome || 'Empresa'} • Status: {request?.status}</p>
          </div>

          {company?.logo_url && <img src={company.logo_url} alt={company.nome} className="h-16 w-auto object-contain" />}
        </div>

        {message && <div className="mt-5 rounded-2xl border border-emerald-100 bg-emerald-50 p-4 font-bold text-emerald-700">{message}</div>}
        {error && <div className="mt-5 rounded-2xl border border-red-100 bg-red-50 p-4 font-bold text-red-700">{error}</div>}

        <div className="mt-7 overflow-hidden rounded-[1.5rem] border border-slate-200 bg-[#f8fbff]">
          {request?.artwork_url || request?.preview_url ? (
            <img src={request.artwork_url || request.preview_url} alt="Prévia da arte" className="max-h-[720px] w-full object-contain" />
          ) : (
            <div className="grid min-h-[260px] place-items-center p-8 text-center">
              <p className="font-black text-slate-500">Nenhuma imagem de arte foi anexada.</p>
            </div>
          )}
        </div>

        {request?.instructions && (
          <div className="mt-5 rounded-[1.5rem] bg-blue-50 p-5">
            <p className="font-black text-[#05245c]">Observações da empresa</p>
            <p className="mt-2 font-bold leading-7 text-slate-600">{request.instructions}</p>
          </div>
        )}

        <div className="mt-6 grid gap-3">
          <textarea
            value={comment}
            onChange={(event) => setComment(event.target.value)}
            placeholder="Comentário opcional. Ex.: aprovado, trocar cor, ajustar texto, aumentar logo..."
            rows={4}
            className="resize-none rounded-[1.5rem] border border-slate-200 bg-[#f8fbff] px-4 py-4 font-bold outline-none focus:border-[#05245c]"
          />

          <div className="grid gap-3 sm:grid-cols-2">
            <button
              type="button"
              onClick={() => submit('approve')}
              className="rounded-2xl bg-emerald-600 px-6 py-4 font-black text-white"
            >
              Aprovar arte
            </button>
            <button
              type="button"
              onClick={() => submit('request_changes')}
              className="rounded-2xl bg-amber-500 px-6 py-4 font-black text-white"
            >
              Pedir alteração
            </button>
          </div>
        </div>
      </section>
    </main>
  )
}

