function formatPhone(value: string) {
  const numbers = value.replace(/\D/g, "").slice(0, 13);

  if (numbers.length <= 2) return numbers;
  if (numbers.length <= 7)
    return `(${numbers.slice(0, 2)}) ${numbers.slice(2)}`;
  if (numbers.length <= 11)
    return `(${numbers.slice(0, 2)}) ${numbers.slice(2, 7)}-${numbers.slice(7)}`;

  return `+${numbers.slice(0, 2)} (${numbers.slice(2, 4)}) ${numbers.slice(4, 9)}-${numbers.slice(9, 13)}`;
}

function formatCpfCnpj(value: string) {
  const numbers = value.replace(/\D/g, "").slice(0, 14);

  if (numbers.length <= 11) {
    return numbers
      .replace(/^(\d{3})(\d)/, "$1.$2")
      .replace(/^(\d{3})\.(\d{3})(\d)/, "$1.$2.$3")
      .replace(/\.(\d{3})(\d)/, ".$1-$2");
  }

  return numbers
    .replace(/^(\d{2})(\d)/, "$1.$2")
    .replace(/^(\d{2})\.(\d{3})(\d)/, "$1.$2.$3")
    .replace(/\.(\d{3})(\d)/, ".$1/$2")
    .replace(/(\d{4})(\d)/, "$1-$2");
}

function validCpfCnpj(value: string) {
  const numbers = value.replace(/\D/g, "");
  return numbers.length === 11 || numbers.length === 14;
}

function isEmail(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

function CadastroContent() {
  const searchParams = useSearchParams();
  const [referralCode, setReferralCode] = useState("");
  const [step, setStep] = useState(1);
  const [form, setForm] = useState<CadastroForm>({
    nome_responsavel: "",
    email: "",
    cpf_cnpj: "",
    whatsapp: "",
    empresa_nome: "",
    modelo_negocio: "services",
    business_type: "services",
    onboarding_goal: "Receber mais pedidos",
    subdomain_slug: "",
    cidade: "",
    estado: "AL",
    plano: "profissional",
  });

  const [cidades, setCidades] = useState<string[]>([]);
  const [buscaCidade, setBuscaCidade] = useState("");
  const [carregandoCidades, setCarregandoCidades] = useState(false);
  const [loading, setLoading] = useState(false);
  const [erro, setErro] = useState("");
  const [slugCheck, setSlugCheck] = useState<SlugCheck>({
    status: "idle",
    message: "Escolha o endereço público da empresa.",
    suggestions: [],
  });

  const config = useMemo(
    () => getBusinessTypeConfig(form.business_type),
    [form.business_type],
  );

  const planoSelecionado = useMemo(() => {
    return planos.find((plano) => plano.id === form.plano) || planos[1];
  }, [form.plano]);

  const cidadesFiltradas = useMemo(() => {
    const busca = buscaCidade.trim().toLowerCase();
    if (!busca) return cidades;
    return cidades.filter((cidade) => cidade.toLowerCase().includes(busca));
  }, [buscaCidade, cidades]);

  const progresso = (step / steps.length) * 100;

  function update<K extends keyof CadastroForm>(
    campo: K,
    valor: CadastroForm[K],
  ) {
    setForm((atual) => ({ ...atual, [campo]: valor }));
  }

  useEffect(() => {
    const queryCode = String(searchParams.get("ref") || "")
      .toUpperCase()
      .replace(/[^A-Z0-9_-]/g, "")
      .slice(0, 32);
    const storageKey = "orcaly_affiliate_referral_v1";
    let storedCode = "";

    try {
      const raw = window.localStorage.getItem(storageKey);
      const saved = raw
        ? (JSON.parse(raw) as { code?: string; expiresAt?: number })
        : null;

      if (saved?.code && Number(saved.expiresAt || 0) > Date.now()) {
        storedCode = String(saved.code);
      }
    } catch {
      storedCode = "";
    }

    const code = queryCode || storedCode;
    if (!code) return;

    setReferralCode(code);

    try {
      window.localStorage.setItem(
        storageKey,
        JSON.stringify({
          code,
          expiresAt: Date.now() + 60 * 24 * 60 * 60 * 1000,
        }),
      );

      const sessionKey = "orcaly_affiliate_click_session_v1";
      let sessionId = window.localStorage.getItem(sessionKey);

      if (!sessionId) {
        sessionId =
          typeof crypto !== "undefined" && "randomUUID" in crypto
            ? crypto.randomUUID()
            : Math.random().toString(36).slice(2);
        window.localStorage.setItem(sessionKey, sessionId);
      }

      void fetch("/api/parceiros/track", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        keepalive: true,
        body: JSON.stringify({
          code,
          sessionId,
          landingPath: window.location.pathname + window.location.search,
          referrer: document.referrer,
        }),
      });
    } catch {
      // A referência ainda segue no formulário.
    }
  }, [searchParams]);

  useEffect(() => {
    async function carregarCidades() {
      setCarregandoCidades(true);
      setCidades([]);
      setBuscaCidade("");
      update("cidade", "");

      try {
        const resposta = await fetch(
          `https://servicodados.ibge.gov.br/api/v1/localidades/estados/${form.estado}/municipios?orderBy=nome`,
        );
        const dados = (await resposta.json()) as CidadeIbge[];
        const nomes = dados
          .map((cidade: CidadeIbge) => cidade.nome)
          .filter(Boolean);
        setCidades(nomes);
      } catch {
        setCidades([]);
      }

      setCarregandoCidades(false);
    }

    if (form.estado) carregarCidades();
  }, [form.estado]);

  useEffect(() => {
    if (!form.empresa_nome || form.subdomain_slug) return;
    update("subdomain_slug", normalizeSubdomainSlug(form.empresa_nome));
  }, [form.empresa_nome, form.subdomain_slug]);

  useEffect(() => {
    const validation = validateSubdomainSlug(form.subdomain_slug);

    if (!form.subdomain_slug) {
      setSlugCheck({
        status: "idle",
        message: "Escolha o endereço público da empresa.",
        suggestions: getSubdomainSuggestions(form.empresa_nome, form.cidade),
      });
      return;
    }

    if (!validation.ok) {
      setSlugCheck({
        status: "invalid",
        message: validation.reason || "Link inválido.",
        suggestions: getSubdomainSuggestions(
          form.empresa_nome || form.subdomain_slug,
          form.cidade,
        ),
      });
      return;
    }

    setSlugCheck((current) => ({
      ...current,
      status: "checking",
      message: "Verificando disponibilidade...",
    }));

    const controller = new AbortController();
    const timer = window.setTimeout(async () => {
      try {
        const params = new URLSearchParams({
          slug: validation.slug,
          company: form.empresa_nome || validation.slug,
          city: form.cidade || "",
        });

        const response = await fetch(
          `/api/company/check-subdomain?${params.toString()}`,
          {
            signal: controller.signal,
          },
        );

        const data = await response.json();

        if (!response.ok) {
          throw new Error(data.error || "Erro ao verificar link.");
        }

        if (data.available) {
          setSlugCheck({
            status: "available",
            message: "Link disponível.",
            suggestions: [],
          });
        } else {
          setSlugCheck({
            status: "unavailable",
            message:
              data.reason || "Esse link já está em uso. Tente outro nome.",
            suggestions: Array.isArray(data.suggestions)
              ? data.suggestions
              : [],
          });
        }
      } catch (error) {
        if (error instanceof DOMException && error.name === "AbortError")
          return;

        setSlugCheck({
          status: "invalid",
          message:
            error instanceof Error ? error.message : "Erro ao verificar link.",
          suggestions: getSubdomainSuggestions(
            form.empresa_nome || form.subdomain_slug,
            form.cidade,
          ),
        });
      }
    }, 450);

    return () => {
      controller.abort();
      window.clearTimeout(timer);
    };
