      if (!form.cidade) return "Escolha a cidade da empresa.";
      if (!form.onboarding_goal)
        return "Escolha o principal objetivo da empresa.";
    }

    if (currentStep === 3 && !form.business_type) {
      return "Escolha o tipo de negócio.";
    }

    if (currentStep === 4) {
      const validation = validateSubdomainSlug(form.subdomain_slug);
      if (!validation.ok)
        return validation.reason || "Escolha um link público válido.";
      if (slugCheck.status === "checking")
        return "Aguarde a verificação do link.";
      if (slugCheck.status !== "available")
        return slugCheck.message || "Escolha um link disponível.";
    }

    return "";
