export default function LoginPage() {
  const router = useRouter()

  const [email, setEmail] = useState('')
  const [senha, setSenha] = useState('')
  const [mostrarSenha, setMostrarSenha] = useState(false)
  const [lembrarEmail, setLembrarEmail] = useState(true)
  const [carregando, setCarregando] = useState(false)
  const [mensagem, setMensagem] = useState(
    'Entre para acessar o painel da sua empresa.',
  )
  const [tipoMensagem, setTipoMensagem] =
    useState<MessageType>('info')
  const [segmentIndex, setSegmentIndex] = useState(0)

  const emailValido = useMemo(
    () => isValidEmail(email),
    [email],
  )
  const currentSegment = segmentCards[segmentIndex]

  useEffect(() => {
    if (typeof window === 'undefined') return

    const savedEmail = window.localStorage.getItem(
      'orcaly_login_email',
    )

    if (savedEmail) {
      setEmail(savedEmail)
    }

    const params = new URLSearchParams(window.location.search)

    if (params.get('expired') === '1') {
      setTipoMensagem('info')
      setMensagem(
        'Sua sessão expirou. Entre novamente para continuar.',
      )
      return
    }

    if (params.get('renovar') === '1') {
      setTipoMensagem('info')
      setMensagem(
        'Entre para renovar sua assinatura e reativar seu painel.',
      )
      return
    }

    setTipoMensagem('info')
    setMensagem(
      'Entre para acessar o painel da sua empresa.',
    )
  }, [])

  useEffect(() => {
    const timer = window.setInterval(() => {
      setSegmentIndex(
        (current) => (current + 1) % segmentCards.length,
      )
    }, 5200)

    return () => window.clearInterval(timer)
  }, [])

  function handleEmailChange(value: string) {
    setEmail(value)

    if (
      typeof window !== 'undefined' &&
      lembrarEmail
    ) {
      const normalized = value.trim().toLowerCase()

      if (normalized) {
        window.localStorage.setItem(
          'orcaly_login_email',
          normalized,
        )
      }
    }
  }

  function handleRememberChange(checked: boolean) {
    setLembrarEmail(checked)

    if (typeof window === 'undefined') return

    if (!checked) {
      window.localStorage.removeItem(
        'orcaly_login_email',
      )
      return
    }

    const normalized = email.trim().toLowerCase()

    if (normalized) {
      window.localStorage.setItem(
        'orcaly_login_email',
        normalized,
      )
    }
  }

  function avisarRecuperacaoSenha() {
    setTipoMensagem('info')
    setMensagem(
      'A recuperação automática será liberada em breve. Por enquanto, confira os dados ou fale com o suporte em orcalybr@gmail.com.',
    )
  }

  async function entrar(
    evento: FormEvent<HTMLFormElement>,
  ) {
    evento.preventDefault()

    if (carregando) return

    const emailLimpo = email.trim().toLowerCase()

    if (!emailLimpo) {
      setTipoMensagem('erro')
      setMensagem('Informe o e-mail da conta.')
      return
    }

    if (!emailValido) {
      setTipoMensagem('erro')
      setMensagem('Digite um e-mail válido.')
      return
    }

    if (!senha) {
      setTipoMensagem('erro')
      setMensagem('Informe sua senha de acesso.')
      return
    }

    setCarregando(true)
    setTipoMensagem('info')
    setMensagem('Validando seu acesso...')

    try {
      const { data, error } =
        await supabase.auth.signInWithPassword({
          email: emailLimpo,
          password: senha,
        })

      if (error) {
        setTipoMensagem('erro')
        setMensagem(
          getFriendlyAuthError(error.message),
        )
        setCarregando(false)
        return
      }

      if (!data.user?.id) {
        setTipoMensagem('erro')
        setMensagem(
          'Não foi possível entrar agora. Tente novamente em alguns instantes.',
        )
        setCarregando(false)
        return
      }

      if (
        lembrarEmail &&
        typeof window !== 'undefined'
      ) {
        window.localStorage.setItem(
          'orcaly_login_email',
          emailLimpo,
        )
      }

      if (
        data.session?.access_token &&
        data.session?.refresh_token
      ) {
        await supabase.auth.setSession({
          access_token: data.session.access_token,
          refresh_token: data.session.refresh_token,
        })
      }

      setTipoMensagem('sucesso')
      setMensagem(
        'Acesso validado. Abrindo seu painel...',
      )

      await new Promise((resolve) =>
        window.setTimeout(resolve, 180),
      )

      router.replace(getSafeNextPath())
    } catch {
      setTipoMensagem('erro')
      setMensagem(
        'Não foi possível entrar agora. Tente novamente em alguns instantes.',
      )
      setCarregando(false)
    }
  }

  const messageClass =
    tipoMensagem === 'erro'
      ? 'border-red-200/90 bg-red-50 text-red-700'
      : tipoMensagem === 'sucesso'
        ? 'border-emerald-200/90 bg-emerald-50 text-emerald-700'
        : 'border-blue-100 bg-blue-50/80 text-[#05245c]'

