            </div>

            <span className={`w-fit rounded-full px-3 py-1 text-xs font-black ring-1 ${visual.className}`}>
              {visual.label}
            </span>

            <p className="font-black text-[#10213d]">{value > 0 ? money(value) : 'A definir'}</p>
