type Settings = Record<string, any>

const booleanFields = [
  ['new_order_enabled', 'Novo pedido recebido'],
  ['order_stuck_enabled', 'Pedido parado há X dias'],
  ['task_due_today_enabled', 'Tarefa vence hoje'],
