]

const numberFields = [
  ['order_stuck_days', 'Pedido parado depois de quantos dias?'],
  ['lead_idle_days', 'Lead sem contato depois de quantos dias?'],
  ['proposal_idle_days', 'Proposta sem resposta depois de quantos dias?'],
