'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { getAccessTokenClient } from '@/lib/current-company-client'

function formatDate(value: string) {
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value
  return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(date)
}

export default function NotificacoesPage() {
  const [token, setToken] = useState('')
  const [notifications, setNotifications] = useState<any[]>([])
  const [unread, setUnread] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  async function load() {
    setLoading(true)
    setError('')

    try {
      const accessToken = await getAccessTokenClient()
      setToken(accessToken)

      const response = await fetch('/api/notifications', {
        headers: { Authorization: `Bearer ${accessToken}` },
      })

      const payload = await response.json().catch(() => ({}))

      if (!response.ok) throw new Error(payload.error || 'Erro ao carregar notificações.')

      setNotifications(payload.notifications || [])
      setUnread(payload.unread || 0)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erro ao carregar notificações.')
    }

    setLoading(false)
  }

  useEffect(() => {
    load()
  }, [])

  async function markAllRead() {
    const response = await fetch('/api/notifications', {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ all: true }),
    })

    if (response.ok) await load()
  }

  if (loading) {
    return <main className="flex min-h-screen items-center justify-center bg-[#f5f8ff]"><div className="rounded-[2rem] bg-white p-8 font-black shadow-xl">Carregando notificações...</div></main>
  }

  return (
    <main className="min-h-screen bg-[#f5f8ff] px-4 py-6 text-[#071b3a]">
      <section className="mx-auto max-w-5xl space-y-6">
        <header className="rounded-[2rem] border border-blue-100 bg-white p-6 shadow-xl shadow-blue-950/5">
          <Link href="/painel" className="text-sm font-black text-[#05245c]">← Voltar ao painel</Link>
          <div className="mt-5 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <p className="text-xs font-black uppercase tracking-[0.22em] text-[#05245c]">Central</p>
              <h1 className="mt-2 text-4xl font-black tracking-[-0.05em] sm:text-5xl">Notificações</h1>
              <p className="mt-3 max-w-3xl font-bold leading-7 text-slate-500">Alertas do sistema, tarefas, CRM, pedidos, cupons e eventos importantes.</p>
            </div>
            <button onClick={markAllRead} className="rounded-2xl bg-[#05245c] px-5 py-4 font-black text-white">Marcar tudo como lido</button>
          </div>
        </header>

        {error && <div className="rounded-2xl bg-red-50 p-4 font-bold text-red-700">{error}</div>}

        <div className="rounded-[2rem] border border-blue-100 bg-white p-5 shadow-xl shadow-blue-950/5">
          <p className="mb-4 text-sm font-black text-slate-500">{unread} não lida(s)</p>

          <div className="grid gap-3">
            {notifications.map((item) => (
              <article key={item.id} className={`rounded-[1.4rem] border p-4 ${item.status === 'unread' ? 'border-[#05245c] bg-blue-50' : 'border-slate-100 bg-white'}`}>
                <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                  <div>
                    <p className="text-xs font-black uppercase tracking-[0.18em] text-[#05245c]">{item.tipo}</p>
                    <h2 className="mt-1 text-lg font-black">{item.titulo}</h2>
                    {item.mensagem && <p className="mt-2 font-bold leading-6 text-slate-500">{item.mensagem}</p>}
                    <p className="mt-2 text-xs font-bold text-slate-400">{formatDate(item.created_at)}</p>
                  </div>
                  {item.link_url && <Link href={item.link_url} className="rounded-2xl bg-white px-4 py-3 text-sm font-black text-[#05245c]">Abrir</Link>}
                </div>
              </article>
            ))}

            {notifications.length === 0 && (
              <div className="rounded-[1.4rem] border border-dashed border-slate-200 bg-white p-8 text-center font-bold text-slate-400">
                Nenhuma notificação ainda.
              </div>
            )}
          </div>
        </div>
      </section>
    </main>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import { supabase } from '@/lib/supabase'

type Empresa = {
  id: string
  nome: string
  slug: string | null
  whatsapp: string | null
  cor_principal: string | null
  logo_url: string | null
}

type Pedido = {
  id: string
  company_id: string | null
  nome: string
  telefone: string
  produto: string
  quantidade: number | null
  observacoes: string | null
  status: string | null
  preco_estimado: number | null
  valor_total: number | null
  valor_sinal: number | null
  percentual_sinal: number | null
  forma_pagamento: string | null
  parcelas: number | null
  itens_resumo: string | null
  arquivo_url: string | null
  created_at: string
}

type ItemPedido = {
  id: string
  nome: string
  tipo: string | null
  unidade: string | null
  quantidade: number | null
  preco_unitario: number | null
  subtotal: number | null
  largura: number | null
  altura: number | null
  comprimento: number | null
  area_m2: number | null
  precificacao: string | null
  detalhes_calculo: string | null
}

const statusOpcoes = [
  'Recebido',
  'Em análise',
  'Orçamento enviado',
  'Aguardando pagamento',
  'Em produção',
  'Finalizado',
  'Cancelado',
]

function formatarDinheiro(valor: number) {
  return Number(valor || 0).toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  })
}

function formatarData(data: string) {
  if (!data) return 'Data não informada'

  return new Date(data).toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

function montarWhatsapp(telefone: string) {
  const numeros = String(telefone || '').replace(/\D/g, '')

  if (!numeros) return ''
  if (numeros.startsWith('55')) return numeros
  if (numeros.length >= 10) return `55${numeros}`

  return numeros
}

function getValorPedido(pedido: Pedido | null) {
  if (!pedido) return 0

  return Number(pedido.valor_total || pedido.preco_estimado || 0)
}

export default function OrcamentoPedidoPage() {
  const params = useParams()
  const pedidoId = String(params?.id || '')

  const [empresa, setEmpresa] = useState<Empresa | null>(null)
  const [pedido, setPedido] = useState<Pedido | null>(null)
  const [itens, setItens] = useState<ItemPedido[]>([])
  const [carregando, setCarregando] = useState(true)
  const [mensagem, setMensagem] = useState('')

  async function carregarOrcamento() {
    setCarregando(true)
    setMensagem('')

    try {
      if (!pedidoId || pedidoId === 'undefined' || pedidoId === 'null') {
        setMensagem('Pedido não informado na URL.')
        return
      }

      const { data: pedidoData, error: pedidoError } = await supabase
        .from('orders')
        .select('*')
        .eq('id', pedidoId)
        .maybeSingle()

      if (pedidoError) {
        setMensagem(`Erro ao buscar pedido: ${pedidoError.message}`)
        return
      }

      if (!pedidoData) {
        setMensagem('Pedido não encontrado. Volte ao painel e tente abrir novamente.')
        return
      }

      const pedidoEncontrado = pedidoData as Pedido
      setPedido(pedidoEncontrado)

      if (pedidoEncontrado.company_id) {
        const { data: empresaData, error: empresaError } = await supabase
          .from('companies')
          .select('id, nome, slug, whatsapp, cor_principal, logo_url')
          .eq('id', pedidoEncontrado.company_id)
          .maybeSingle()

        if (empresaError) {
          setMensagem(`Pedido carregado, mas não consegui buscar a empresa: ${empresaError.message}`)
        } else if (empresaData) {
          setEmpresa(empresaData as Empresa)
        }
      }

      const { data: itensData, error: itensError } = await supabase
        .from('order_items')
        .select('*')
        .eq('order_id', pedidoId)

      if (itensError) {
        setMensagem(
          `Pedido carregado, mas os itens detalhados não foram encontrados: ${itensError.message}`
        )
        setItens([])
        return
      }

      setItens((itensData || []) as ItemPedido[])
    } catch (erro) {
      const textoErro =
        erro instanceof Error
          ? erro.message
          : 'Erro desconhecido ao carregar orçamento.'

      setMensagem(`Erro: ${textoErro}`)
    } finally {
      setCarregando(false)
    }
  }

  async function notificarStatusPedido(novoStatus: string) {
    try {
      const { data: sessionData } = await supabase.auth.getSession()
      const token = sessionData.session?.access_token
      if (!token || !pedido?.id) return

      await fetch('/api/whatsapp/order-status', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          order_id: pedido.id,
          status: novoStatus,
          source: 'pedido',
        }),
      })
    } catch (error) {
      console.error('[Orçaly WhatsApp] Falha ao avisar status:', error)
    }
  }

  async function atualizarStatus(novoStatus: string) {
    if (!pedido) return

    const { error } = await supabase
      .from('orders')
      .update({ status: novoStatus })
      .eq('id', pedido.id)

    if (error) {
      setMensagem(`Erro ao atualizar status: ${error.message}`)
      return
    }

    setPedido({ ...pedido, status: novoStatus })
    await notificarStatusPedido(novoStatus)
    setMensagem('Status atualizado.')
  }

  async function copiarResumo() {
    if (!pedido) return

    const nomeEmpresa = empresa?.nome || 'Empresa'
    const valorTotal = getValorPedido(pedido)

    const resumoItens =
      itens.length > 0
        ? itens
            .map((item) => {
              return `- ${item.nome}: ${item.quantidade || 1} ${item.unidade || ''} | ${formatarDinheiro(Number(item.subtotal || 0))}`
            })
            .join('\n')
        : `- ${pedido.produto}: ${pedido.quantidade || 1} | ${formatarDinheiro(valorTotal)}`

    const texto = `ORÇAMENTO - ${nomeEmpresa}

Cliente: ${pedido.nome}
WhatsApp: ${pedido.telefone}
Data: ${formatarData(pedido.created_at)}

Itens:
${resumoItens}

Total: ${formatarDinheiro(valorTotal)}
${pedido.valor_sinal ? `Sinal: ${formatarDinheiro(Number(pedido.valor_sinal))}` : ''}
Status: ${pedido.status || 'Recebido'}

${pedido.observacoes ? `Observações: ${pedido.observacoes}` : ''}`

    await navigator.clipboard.writeText(texto)
    setMensagem('Resumo copiado.')
  }

  useEffect(() => {
    carregarOrcamento()
  }, [pedidoId])

  const nomeEmpresa = empresa?.nome || 'Orçaly'
  const corPrincipal = empresa?.cor_principal || '#05245c'
  const valorTotal = getValorPedido(pedido)
  const numeroCliente = pedido ? montarWhatsapp(pedido.telefone || '') : ''
  const textoWhatsapp =
    pedido
      ? `Olá, ${pedido.nome}! Segue o resumo do seu orçamento na ${nomeEmpresa}. Total: ${formatarDinheiro(valorTotal)}.`
      : ''
  const linkWhatsapp = numeroCliente
    ? `https://wa.me/${numeroCliente}?text=${encodeURIComponent(textoWhatsapp)}`
    : ''

  if (carregando) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-white px-4">
        <div className="rounded-[2rem] border border-blue-50 bg-white p-8 text-center shadow-xl shadow-blue-950/5">
          <img
            src="/logo-orcaly.png"
            alt="Orçaly"
            className="mx-auto mb-6 h-14 w-auto object-contain"
          />

