function AdminTable({ title, rows, columns, render }: { title: string; rows: any[]; columns: string[]; render: (row: any) => any[] }) {
  return (
    <div className="min-w-0 overflow-hidden rounded-[2rem] border border-blue-100 bg-white shadow-xl shadow-blue-950/5">
      <div className="border-b border-blue-50 p-5">
        <h2 className="text-2xl font-black tracking-[-0.04em] text-[#071b3a]">{title}</h2>
        <p className="mt-1 text-sm font-bold text-slate-500">{rows.length} registro(s)</p>
      </div>
      <div className="overflow-x-auto">
        <table className="min-w-[760px] w-full text-left text-sm">
          <thead className="bg-[#f8fbff] text-xs font-black uppercase tracking-[0.14em] text-slate-400">
            <tr>{columns.map((col) => <th key={col} className="px-5 py-4">{col}</th>)}</tr>
          </thead>
          <tbody className="divide-y divide-blue-50">
            {rows.length ? rows.map((row, index) => (
              <tr key={row.id || index} className="align-top">
                {render(row).map((cell, cellIndex) => <td key={cellIndex} className="max-w-[260px] break-words px-5 py-4 font-bold text-slate-600">{cell}</td>)}
              </tr>
            )) : (
              <tr><td colSpan={columns.length} className="px-5 py-10 text-center font-bold text-slate-500">Nenhum registro encontrado.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

"use client";

// ORCALY_OWNER_SUPPORT_CONTROL_V1

import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import { supabase } from "@/lib/supabase";

type Json = Record<string, any>;

function money(value: unknown) {
  if (value === null || value === undefined) {
    return "Protegido";
  }

  return Number(value || 0).toLocaleString(
    "pt-BR",
    {
      style: "currency",
      currency: "BRL",
    },
  );
}

function dateTime(value: unknown) {
  if (!value) return "Sem registro";
  const parsed = new Date(String(value));
  if (Number.isNaN(parsed.getTime())) {
    return "Sem registro";
  }

  return new Intl.DateTimeFormat("pt-BR", {
    dateStyle: "short",
    timeStyle: "short",
  }).format(parsed);
}

async function currentToken() {
  const { data } = await supabase.auth.getSession();
  return data.session?.access_token || "";
}

async function jsonFetch(
  url: string,
  token: string,
) {
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
    },
    cache: "no-store",
  });

  const payload = await response
    .json()
    .catch(() => ({}));

  return {
    ok: response.ok,
    status: response.status,
    payload,
  };
}

function Metric({
  label,
  value,
  detail,
  tone = "blue",
}: {
  label: string;
  value: string;
  detail: string;
  tone?: "blue" | "green" | "amber" | "violet";
}) {
  const tones = {
    blue: "from-blue-50 to-white border-blue-100 text-[#05245c]",
    green:
      "from-emerald-50 to-white border-emerald-100 text-emerald-700",
    amber:
      "from-amber-50 to-white border-amber-100 text-amber-700",
    violet:
      "from-violet-50 to-white border-violet-100 text-violet-700",
  };

  return (
    <article
      className={`rounded-[1.6rem] border bg-gradient-to-br p-5 shadow-sm ${tones[tone]}`}
    >
      <p className="text-[10px] font-black uppercase tracking-[0.16em] opacity-55">
        {label}
      </p>
      <p className="mt-3 text-3xl font-black tracking-[-0.045em]">
        {value}
      </p>
      <p className="mt-2 text-xs font-bold opacity-55">
        {detail}
      </p>
    </article>
  );
}

export default function OwnerControlCenter() {
  const router = useRouter();
  const [session, setSession] =
    useState<Json | null>(null);
  const [affiliates, setAffiliates] =
    useState<Json | null>(null);
  const [platform, setPlatform] =
    useState<Json | null>(null);
  const [team, setTeam] =
    useState<any[]>([]);
  const [audit, setAudit] =
    useState<any[]>([]);
  const [loading, setLoading] =
    useState(true);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError("");

    const token = await currentToken();

    if (!token) {
      router.replace("/admin/login");
      return;
    }

    const sessionResult = await jsonFetch(
      "/api/admin/session",
      token,
    );

    if (!sessionResult.ok) {
      await supabase.auth.signOut();
      router.replace("/admin/login");
      return;
    }

    if (
      sessionResult.payload?.admin
        ?.mustChangePassword
    ) {
      router.replace("/admin/alterar-senha");
      return;
    }

    setSession(sessionResult.payload);

    const [
      affiliatesResult,
      platformResult,
      teamResult,
      auditResult,
    ] = await Promise.all([
      jsonFetch(
        "/api/admin/affiliates",
        token,
      ),
      jsonFetch(
        "/api/platform-admin/summary",
        token,
      ),
      jsonFetch("/api/admin/team", token),
      jsonFetch("/api/admin/audit", token),
    ]);

    if (affiliatesResult.ok) {
      setAffiliates(
        affiliatesResult.payload,
      );
    }

    if (platformResult.ok) {
      setPlatform(platformResult.payload);
    }

    if (teamResult.ok) {
      setTeam(
        teamResult.payload.team || [],
      );
    }

    if (auditResult.ok) {
      setAudit(
        auditResult.payload.logs || [],
      );
    }

    if (
      !affiliatesResult.ok &&
      !platformResult.ok
    ) {
      setError(
        affiliatesResult.payload.error ||
          platformResult.payload.error ||
          "Não foi possível carregar o centro de controle.",
      );
    }

    setLoading(false);
  }, [router]);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void load();
    }, 0);

    return () => window.clearTimeout(timer);
  }, [load]);

  const pendingReferrals = useMemo(
    () =>
      (affiliates?.referrals || []).filter(
        (row: any) =>
          row.review_status === "pending" ||
          row.review_status === "flagged",
      ),
    [affiliates],
  );

  const pendingPayouts = useMemo(
    () =>
      (affiliates?.payouts || []).filter(
        (row: any) =>
          [
            "requested",
            "approved",
            "processing",
          ].includes(row.status),
      ),
    [affiliates],
  );

  const pendingPix = useMemo(
    () =>
      (affiliates?.profiles || []).filter(
        (row: any) =>
          row.payout_status !== "verified",
      ),
    [affiliates],
  );

  const topPartners =
    affiliates?.ranking?.top || [];

  async function logout() {
    await supabase.auth.signOut();
    router.replace("/admin/login");
  }

  if (loading) {
    return (
      <main className="grid min-h-screen place-items-center bg-[#eef3f9] text-[#071b3a]">
        <div className="text-center">
          <div className="mx-auto h-11 w-11 animate-spin rounded-full border-4 border-blue-100 border-t-[#05245c]" />
          <p className="mt-4 font-black">
            Carregando centro de controle...
          </p>
        </div>
      </main>
    );
  }

  if (!session) {
    return null;
  }

  const admin = session.admin || {};
  const capabilities =
    session.capabilities || {};
  const affiliateSummary =
    affiliates?.summary || {};
  const platformMetrics =
    platform?.metrics || {};

  const nav = [
    {
      href: "/admin",
      label: "Visão geral",
      visible: true,
    },
    {
      href: "/admin/indicacoes",
      label: "Parceiros",
      visible:
        capabilities["affiliates.view"],
    },
    {
      href: "/admin/empresas",
      label: "Empresas",
      visible:
        capabilities["companies.view"],
    },
    {
      href: "/admin/equipe",
      label: "Equipe interna",
      visible:
        capabilities["team.manage"],
    },
    {
      href: "/admin/auditoria",
      label: "Auditoria",
      visible:
        capabilities["audit.view"],
    },
  ].filter((item) => item.visible);

