        <ProductRequestModal
          product={selected}
          businessType={normalizedType}
          primaryColor={primaryColor}
          accentColor={accentColor}
          onClose={() => setSelected(null)}
          onAdd={addToCart}
        />
      ) : null}
    </section>
  )
}

function ProductRequestModal({
  product,
  businessType,
  primaryColor,
  accentColor,
  onClose,
  onAdd,
}: {
  product: PublicSiteProduct
  businessType: CatalogBusinessType
  primaryColor: string
  accentColor: string
  onClose: () => void
  onAdd: (
    product: PublicSiteProduct,
    quantity: number,
    notes: string,
    answers: Record<string, string>,
    optionSelections: ProductOptionSelections,
  ) => void
}) {
  const [quantity, setQuantity] = useState(1)
  const [notes, setNotes] = useState('')
  const [answers, setAnswers] = useState<Record<string, string>>({})
  const [optionSelections, setOptionSelections] =
    useState<ProductOptionSelections>({})
  const [optionError, setOptionError] = useState('')
  const fields = segmentFields[businessType] || segmentFields.services
  const optionGroups = useMemo(
    () => getProductOptionGroups(product),
    [product],
  )
  const price = getProductPriceNumber(product)
  const optionsPrice = getOptionSelectionsPrice(
    optionGroups,
    optionSelections,
  )
  const subtotal = Number(
    (
      (price + optionsPrice) *
      Math.max(1, quantity)
    ).toFixed(2),
  )
  const image = getPrimaryProductImage(product)

  function selectOption(
    group: ProductOptionGroup,
    optionId: string,
  ) {
    setOptionError('')

    setOptionSelections((current) => {
      const selected = current[group.id] || []

      if (group.selection === 'single') {
        return {
          ...current,
          [group.id]:
            selected[0] === optionId ? [] : [optionId],
        }
      }

      if (selected.includes(optionId)) {
        return {
          ...current,
          [group.id]: selected.filter((id) => id !== optionId),
        }
      }

      if (selected.length >= Math.max(1, group.max)) {
        setOptionError(
          `Escolha no máximo ${group.max} opções em "${group.name}".`,
        )
        return current
      }

      return {
        ...current,
        [group.id]: [...selected, optionId],
      }
    })
  }

  function addConfiguredItem() {
    const validation = validateProductOptionSelections(
      optionGroups,
      optionSelections,
    )

    if (validation) {
      setOptionError(validation)
      return
    }

    onAdd(
      product,
      quantity,
      notes,
      answers,
      optionSelections,
    )
  }

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-[#071b3a]/60 px-4 py-6 backdrop-blur-sm" role="dialog" aria-modal="true">
      <div className="max-h-[92vh] w-full max-w-5xl overflow-y-auto rounded-[2.4rem] bg-white p-4 shadow-2xl shadow-blue-950/30">
        <div className="grid gap-5 lg:grid-cols-[1fr_1fr]">
          <div className="min-w-0">
            {image ? <img src={image} alt={getProductName(product)} className="h-80 w-full rounded-[1.9rem] object-cover" /> : <div className="grid h-80 place-items-center rounded-[1.9rem] bg-slate-100 text-sm font-black text-slate-400">Sem foto</div>}
            <div className="mt-4 rounded-[1.5rem] p-4 text-white" style={{ background: `linear-gradient(135deg, ${primaryColor}, ${accentColor})` }}>
              <p className="text-xs font-black uppercase tracking-[0.16em] text-white/60">{getCategory(product)}</p>
              <h3 className="mt-1 text-3xl font-black tracking-[-0.05em]">{getProductName(product)}</h3>
              <p className="mt-3 text-sm font-bold leading-6 text-white/70">{product.descricao || product.descricao_curta || 'Informe detalhes para a empresa responder melhor.'}</p>
            </div>
          </div>

          <div className="min-w-0 p-2 sm:p-4">
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-black uppercase tracking-[0.18em] text-[#05245c]">Configurar solicitação</p>
                <h3 className="mt-2 text-4xl font-black leading-[1.02] tracking-[-0.055em] text-[#071b3a]">{getProductPriceLabel(product)}</h3>
              </div>
              <button type="button" onClick={onClose} className="rounded-full bg-slate-100 px-4 py-2 text-sm font-black text-slate-500">Fechar</button>
            </div>

            <div className="mt-6 grid gap-4">
              <label className="grid gap-2 text-sm font-black text-slate-600">
                Quantidade
                <input type="number" min={1} value={quantity} onChange={(event) => setQuantity(Math.max(1, Number(event.target.value || 1)))} className="rounded-2xl border border-blue-100 bg-[#f8fbff] px-4 py-3 font-bold outline-none" />
              </label>

              {optionGroups.map((group) => {
                const selected = optionSelections[group.id] || []
                const rule =
                  group.selection === 'single'
                    ? group.required
                      ? 'Escolha 1 opção'
                      : 'Escolha até 1 opção'
                    : `${group.required ? `Escolha de ${Math.max(1, group.min)} a` : 'Escolha até'} ${group.max}`

                return (
                  <section key={group.id} className="rounded-[1.4rem] border border-blue-100 bg-[#f8fbff] p-4">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <div>
                        <p className="font-black text-[#071b3a]">{group.name}</p>
                        <p className="mt-1 text-xs font-bold text-slate-500">{rule}</p>
                      </div>
                      <span className={`rounded-full px-3 py-1 text-xs font-black ${group.required ? 'bg-emerald-100 text-emerald-700' : 'bg-white text-slate-500'}`}>
                        {group.required ? 'Obrigatório' : 'Opcional'}
                      </span>
                    </div>

                    <div className="mt-3 grid gap-2">
                      {group.options.filter((option) => option.active).map((option) => {
                        const checked = selected.includes(option.id)

                        return (
                          <label key={option.id} className={`flex cursor-pointer items-center justify-between gap-3 rounded-2xl border px-4 py-3 ${checked ? 'border-blue-300 bg-white' : 'border-blue-100 bg-white/70'}`}>
                            <span className="flex min-w-0 items-center gap-3">
                              <input
                                type={group.selection === 'single' ? 'radio' : 'checkbox'}
                                name={`option-group-${group.id}`}
                                checked={checked}
                                onChange={() => selectOption(group, option.id)}
                              />
                              <span className="truncate font-black text-slate-700">{option.name}</span>
                            </span>
                            <span className="shrink-0 text-sm font-black text-[#05245c]">
                              {option.price > 0 ? `+ ${money(option.price)}` : 'Incluso'}
                            </span>
                          </label>
                        )
                      })}
                    </div>
                  </section>
                )
              })}

              {fields.map((field) => (
                <label key={field.key} className="grid gap-2 text-sm font-black text-slate-600">
                  {field.label}
                  {field.rows ? (
                    <textarea value={answers[field.key] || ''} onChange={(event) => setAnswers((current) => ({ ...current, [field.key]: event.target.value }))} placeholder={field.placeholder} rows={field.rows} className="resize-none rounded-2xl border border-blue-100 bg-[#f8fbff] px-4 py-3 font-bold outline-none" />
                  ) : (
                    <input value={answers[field.key] || ''} onChange={(event) => setAnswers((current) => ({ ...current, [field.key]: event.target.value }))} placeholder={field.placeholder} className="rounded-2xl border border-blue-100 bg-[#f8fbff] px-4 py-3 font-bold outline-none" />
                  )}
                </label>
              ))}

              <label className="grid gap-2 text-sm font-black text-slate-600">
                Observações
                <textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Detalhes adicionais, prazo, preferências ou dúvidas." rows={4} className="resize-none rounded-2xl border border-blue-100 bg-[#f8fbff] px-4 py-3 font-bold outline-none" />
              </label>

              {optionError ? (
                <div className="rounded-2xl bg-red-50 p-4 text-sm font-bold text-red-700">
                  {optionError}
                </div>
              ) : null}

              <div className="flex flex-col gap-3 rounded-[1.5rem] border border-blue-100 bg-[#f8fbff] p-4 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <p className="text-xs font-black uppercase tracking-[0.16em] text-slate-400">Subtotal estimado</p>
                  <p className="text-3xl font-black text-[#071b3a]">{money(subtotal)}</p>
                  {optionsPrice > 0 ? <p className="mt-1 text-xs font-bold text-slate-500">Inclui {money(optionsPrice)} por unidade em opções.</p> : null}
                </div>
                <button type="button" onClick={addConfiguredItem} className="rounded-2xl px-5 py-4 font-black text-white" style={{ background: primaryColor }}>
                  Adicionar
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useRef, useState, type ChangeEvent, type DragEvent } from 'react'
import { uploadPanelFile } from '@/lib/panel-storage'

type LogoUploaderProps = {
  companyId?: string | null
  value?: string | null
  onChange: (url: string | null) => void
  disabled?: boolean
}

const allowedTypes = ['image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/svg+xml']
const maxSize = 5 * 1024 * 1024

export default function LogoUploader({ companyId, value, onChange, disabled }: LogoUploaderProps) {
  const inputRef = useRef<HTMLInputElement | null>(null)
  const [uploading, setUploading] = useState(false)
  const [dragging, setDragging] = useState(false)
  const [error, setError] = useState('')

  async function uploadFile(file: File) {
    setError('')

    if (!companyId) {
      setError('Empresa não carregada ainda.')
      return
    }

    if (!allowedTypes.includes(file.type)) {
      setError('Envie uma logo em PNG, JPG, WEBP ou SVG.')
      return
    }

    if (file.size > maxSize) {
      setError('A logo precisa ter até 5 MB.')
      return
    }

    setUploading(true)

    try {
      // ORCALY_LOGO_STORAGE_V1
      const upload = await uploadPanelFile({
        companyId,
        file,
        purpose: 'logo',
      })

      if (!upload.url) throw new Error('A URL pública da logo não foi criada.')
      onChange(upload.url)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erro ao enviar logo.')
    }

    setUploading(false)
  }

  function handleInput(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]
    if (file) void uploadFile(file)
    event.target.value = ''
  }

  function handleDrop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault()
    setDragging(false)

    const file = event.dataTransfer.files?.[0]
    if (file) void uploadFile(file)
  }

  return (
    <div className="rounded-[1.6rem] border border-blue-100 bg-[#f8fbff] p-5">
      <input
        ref={inputRef}
        type="file"
        accept=".png,.jpg,.jpeg,.webp,.svg,image/png,image/jpeg,image/webp,image/svg+xml"
        onChange={handleInput}
        className="hidden"
        disabled={disabled || uploading}
      />

      <div
        onDragOver={(event) => {
          event.preventDefault()
          setDragging(true)
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={handleDrop}
        className={`rounded-[1.4rem] border-2 border-dashed p-5 text-center transition ${
          dragging ? 'border-[#05245c] bg-white' : 'border-blue-100 bg-white/70'
        }`}
      >
        {value ? (
          <div className="mx-auto mb-4 grid h-28 w-28 place-items-center rounded-[1.5rem] bg-white shadow-lg ring-1 ring-blue-100">
            <img src={value} alt="Logo da empresa" className="max-h-[78%] max-w-[78%] object-contain" />
          </div>
        ) : (
          <div className="mx-auto mb-4 grid h-20 w-20 place-items-center rounded-[1.5rem] bg-blue-50 text-3xl">🏷️</div>
        )}

        <h3 className="text-lg font-black tracking-[-0.03em] text-[#071b3a]">Envie a logo da sua empresa</h3>
        <p className="mx-auto mt-2 max-w-md text-sm font-bold leading-6 text-slate-500">
          PNG, JPG, WEBP ou SVG. Recomendado: fundo transparente.
        </p>

        <div className="mt-5 flex flex-wrap justify-center gap-2">
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            disabled={disabled || uploading}
            className="rounded-2xl bg-[#05245c] px-5 py-3 text-sm font-black text-white disabled:opacity-60"
          >
            {uploading ? 'Enviando...' : value ? 'Trocar logo' : 'Selecionar logo'}
          </button>

          {value ? (
            <button
              type="button"
              onClick={() => onChange(null)}
              disabled={disabled || uploading}
              className="rounded-2xl border border-blue-100 bg-white px-5 py-3 text-sm font-black text-[#05245c] disabled:opacity-60"
            >
              Remover logo
            </button>
          ) : null}
        </div>
      </div>

      {error ? <p className="mt-3 text-sm font-bold text-red-600">{error}</p> : null}
    </div>
  )
}

type ProductMediaGalleryProps = {
  product: {
    nome?: string | null
    imagem_url?: string | null
    image_urls?: string[] | null
    video_url?: string | null
  }
  className?: string
}

export default function ProductMediaGallery({ product, className = '' }: ProductMediaGalleryProps) {
  const images = Array.isArray(product.image_urls)
    ? product.image_urls.filter(Boolean).slice(0, 4)
    : product.imagem_url
      ? [product.imagem_url]
      : []

  return (
    <div className={className}>
      {product.video_url ? (
        <video src={product.video_url} controls muted className="aspect-video w-full rounded-[1.5rem] object-cover" />
      ) : images[0] ? (
        <img src={images[0]} alt={product.nome || 'Produto'} className="aspect-video w-full rounded-[1.5rem] object-cover" />
      ) : (
        <div className="grid aspect-video w-full place-items-center rounded-[1.5rem] bg-slate-100 text-sm font-black text-slate-400">
          Sem mídia
        </div>
      )}

      {images.length > 1 ? (
        <div className="mt-3 grid grid-cols-4 gap-2">
          {images.map((image) => (
            <img key={image} src={image} alt={product.nome || 'Produto'} className="h-20 rounded-xl object-cover" />
          ))}
        </div>
      ) : null}
    </div>
  )
}

// ORCALY_ASAAS_MIGRATION_V2
"use client";

import { FormEvent, useState } from "react";
import { supabase } from "@/lib/supabase";

type PlanKey = "essencial" | "profissional" | "premium";
type PaymentMethod = "PIX" | "CREDIT_CARD";

const plans: Array<{ key: PlanKey; name: string; price: string }> = [
  { key: "essencial", name: "Essencial", price: "R$ 49,90/mes" },
  { key: "profissional", name: "Profissional", price: "R$ 99,90/mes" },
  { key: "premium", name: "Premium", price: "R$ 149,90/mes" },
];

export default function AsaasSubscriptionPayment() {
  const [planKey, setPlanKey] = useState<PlanKey>("essencial");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>("PIX");
  const [customer, setCustomer] = useState({
    name: "",
    email: "",
    cpfCnpj: "",
    phone: "",
    postalCode: "",
    addressNumber: "",
    addressComplement: "",
  });
  const [card, setCard] = useState({
    holderName: "",
    number: "",
    expiryMonth: "",
    expiryYear: "",
    ccv: "",
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [pix, setPix] = useState<{ encodedImage?: string; payload?: string } | null>(null);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (loading) return;

    setLoading(true);
    setError("");
    setMessage("Preparando sua assinatura...");
    setPix(null);

    try {
      const { data } = await supabase.auth.getSession();
      const token = data.session?.access_token;
      if (!token) throw new Error("Sessao nao encontrada.");

      const response = await fetch("/api/assinatura/asaas", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          planKey,
          paymentMethod,
          customer,
          card: paymentMethod === "CREDIT_CARD" ? card : undefined,
        }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload.error || "Nao foi possivel criar a assinatura.");
      }

      setMessage(payload.message || "Assinatura preparada com sucesso.");
      if (payload.pix) setPix(payload.pix);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Nao foi possivel criar a assinatura.");
      setMessage("");
    } finally {
      setLoading(false);
    }
  }

  async function copyPix() {
    if (!pix?.payload) return;
    await navigator.clipboard.writeText(pix.payload);
    setMessage("Codigo Pix copiado.");
  }

  return (
    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm md:p-8">
      <div className="max-w-3xl">
        <p className="text-sm font-bold text-violet-600">Pagamento seguro</p>
        <h2 className="mt-2 text-2xl font-black text-slate-950">Ativar ou reativar assinatura</h2>
        <p className="mt-3 text-sm leading-6 text-slate-600">
          O periodo gratuito continua sendo concedido somente na primeira adesao. Nenhum dado de cartao e armazenado pelo Orcaly.
        </p>
      </div>

      <form onSubmit={submit} className="mt-7 space-y-6">
        <fieldset>
          <legend className="text-sm font-bold text-slate-800">Plano</legend>
          <div className="mt-3 grid gap-3 md:grid-cols-3">
            {plans.map((plan) => (
              <label
                key={plan.key}
                className={`cursor-pointer rounded-2xl border p-4 transition ${
                  planKey === plan.key
                    ? "border-violet-500 bg-violet-50"
                    : "border-slate-200 hover:border-slate-300"
                }`}
              >
                <input
                  type="radio"
                  name="plan"
                  value={plan.key}
                  checked={planKey === plan.key}
                  onChange={() => setPlanKey(plan.key)}
                  className="sr-only"
                />
                <span className="block font-black text-slate-950">{plan.name}</span>
                <span className="mt-1 block text-sm text-slate-600">{plan.price}</span>
              </label>
            ))}
          </div>
        </fieldset>

        <fieldset>
          <legend className="text-sm font-bold text-slate-800">Forma de pagamento</legend>
          <div className="mt-3 flex flex-wrap gap-3">
            {(["PIX", "CREDIT_CARD"] as PaymentMethod[]).map((method) => (
              <label key={method} className={`cursor-pointer rounded-xl border px-4 py-3 text-sm font-bold ${
                paymentMethod === method
                  ? "border-violet-500 bg-violet-50 text-violet-700"
                  : "border-slate-200 text-slate-700"
              }`}>
                <input
                  type="radio"
                  name="method"
                  value={method}
                  checked={paymentMethod === method}
                  onChange={() => setPaymentMethod(method)}
                  className="sr-only"
                />
                {method === "PIX" ? "Pix" : "Cartao"}
              </label>
            ))}
          </div>
        </fieldset>

        <div className="grid gap-4 md:grid-cols-2">
          {[
            ["name", "Nome", "text"],
            ["email", "E-mail", "email"],
            ["cpfCnpj", "CPF ou CNPJ", "text"],
            ["phone", "Telefone", "tel"],
            ["postalCode", "CEP", "text"],
            ["addressNumber", "Numero", "text"],
            ["addressComplement", "Complemento", "text"],
          ].map(([name, label, type]) => (
            <label key={name} className="text-sm font-semibold text-slate-700">
              <span>{label}</span>
              <input
                type={type}
                value={customer[name as keyof typeof customer]}
                onChange={(event) =>
                  setCustomer((current) => ({ ...current, [name]: event.target.value }))
                }
                required={["name", "email", "cpfCnpj", "postalCode", "addressNumber"].includes(name)}
                className="mt-2 w-full rounded-xl border border-slate-300 px-3 py-3 outline-none focus:border-violet-500 focus:ring-2 focus:ring-violet-100"
              />
            </label>
          ))}
        </div>

        {paymentMethod === "CREDIT_CARD" ? (
          <div className="grid gap-4 rounded-2xl border border-slate-200 bg-slate-50 p-5 md:grid-cols-2">
            {[
              ["holderName", "Nome impresso no cartao", "text", "cc-name"],
              ["number", "Numero do cartao", "text", "cc-number"],
              ["expiryMonth", "Mes", "text", "cc-exp-month"],
              ["expiryYear", "Ano", "text", "cc-exp-year"],
              ["ccv", "CVV", "password", "cc-csc"],
            ].map(([name, label, type, autocomplete]) => (
              <label key={name} className="text-sm font-semibold text-slate-700">
                <span>{label}</span>
                <input
                  type={type}
                  autoComplete={autocomplete}
                  inputMode={name === "holderName" ? "text" : "numeric"}
                  value={card[name as keyof typeof card]}
                  onChange={(event) =>
                    setCard((current) => ({ ...current, [name]: event.target.value }))
                  }
                  required
                  className="mt-2 w-full rounded-xl border border-slate-300 bg-white px-3 py-3 outline-none focus:border-violet-500 focus:ring-2 focus:ring-violet-100"
                />
              </label>
            ))}
            <p className="md:col-span-2 text-xs leading-5 text-slate-500">
              Os dados sao enviados diretamente ao backend seguro e descartados apos a tokenizacao. O CVV nunca e armazenado.
            </p>
          </div>
        ) : null}

        {error ? <div role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-700">{error}</div> : null}
        {message ? <div aria-live="polite" className="rounded-xl bg-emerald-50 p-4 text-sm text-emerald-700">{message}</div> : null}

        {pix ? (
          <div className="rounded-2xl border border-violet-200 bg-violet-50 p-5">
            <h3 className="font-black text-slate-950">Pagamento Pix</h3>
            {pix.encodedImage ? (
              <img
                src={`data:image/png;base64,${pix.encodedImage}`}
                alt="QR Code Pix da assinatura"
                className="mt-4 h-48 w-48 rounded-xl bg-white p-2"
              />
            ) : null}
            {pix.payload ? (
              <button
                type="button"
                onClick={copyPix}
                className="mt-4 rounded-xl bg-white px-4 py-3 text-sm font-bold text-violet-700 shadow-sm"
              >
                Copiar codigo Pix
              </button>
            ) : null}
          </div>
        ) : null}

        <button
          type="submit"
          disabled={loading}
          className="inline-flex min-h-11 items-center justify-center rounded-xl bg-violet-600 px-6 py-3 text-sm font-bold text-white transition hover:bg-violet-700 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {loading ? "Processando..." : paymentMethod === "PIX" ? "Continuar com Pix" : "Continuar com cartao"}
        </button>
      </form>
    </section>
  );
}

