import { createNotification } from '@/lib/orcaly-audit'

type SupabaseAdmin = any

export type SmartNotificationSettings = {
  new_order_enabled: boolean
  order_stuck_enabled: boolean
  order_stuck_days: number
  task_due_today_enabled: boolean
  lead_idle_enabled: boolean
  lead_idle_days: number
  proposal_idle_enabled: boolean
  proposal_idle_days: number
  coupon_expiring_enabled: boolean
  coupon_expiring_days: number
  product_without_image_enabled: boolean
  site_without_logo_enabled: boolean
  subscription_expiring_enabled: boolean
  subscription_expiring_days: number
}

export type SmartNotificationResult = {
  company_id: string
  created: number
  skipped: number
  errors: string[]
  events: Array<{
    type: string
    title: string
    link_url?: string
    created: boolean
  }>
}

const DEFAULT_SETTINGS: SmartNotificationSettings = {
  new_order_enabled: true,
  order_stuck_enabled: true,
  order_stuck_days: 3,
  task_due_today_enabled: true,
  lead_idle_enabled: true,
  lead_idle_days: 3,
  proposal_idle_enabled: true,
  proposal_idle_days: 3,
  coupon_expiring_enabled: true,
  coupon_expiring_days: 3,
  product_without_image_enabled: true,
  site_without_logo_enabled: true,
  subscription_expiring_enabled: true,
  subscription_expiring_days: 7,
}

function nowMs() {
  return Date.now()
}

function daysAgoMs(days: number) {
  return nowMs() - Math.max(1, Number(days || 1)) * 24 * 60 * 60 * 1000
}

function daysAheadMs(days: number) {
  return nowMs() + Math.max(1, Number(days || 1)) * 24 * 60 * 60 * 1000
}

function dayKey(date = new Date()) {
  return date.toISOString().slice(0, 10)
}

function toMs(value: unknown) {
  if (!value) return 0
  const date = new Date(String(value))
  const time = date.getTime()
  return Number.isNaN(time) ? 0 : time
}

function isFinalOrder(status: unknown) {
  const value = String(status || '').toLowerCase()
  return value.includes('entregue') || value.includes('cancel') || value.includes('finaliz')
}

function isClosedLead(lead: any) {
  const etapa = String(lead?.etapa || '').toLowerCase()
  const status = String(lead?.status || '').toLowerCase()

  return etapa.includes('fechado')
    || etapa.includes('perdido')
    || status.includes('inativo')
    || status.includes('perdido')
    || status.includes('fechado')
}

function isClosedProposal(proposal: any) {
  const status = String(proposal?.status || '').toLowerCase()

  return status.includes('aprov')
    || status.includes('aceit')
    || status.includes('fech')
    || status.includes('cancel')
    || status.includes('perd')
}

function hasProductImage(product: any) {
  if (Array.isArray(product?.image_urls) && product.image_urls.filter(Boolean).length > 0) return true
  if (product?.imagem_url) return true
  if (product?.foto_url) return true
  if (product?.image_url) return true
  if (product?.arquivo_url) return true
  return false
}

async function safeRows(
  supabaseAdmin: SupabaseAdmin,
  result: SmartNotificationResult,
  label: string,
  query: any
) {
  try {
    const { data, error } = await query

    if (error) {
      result.errors.push(`${label}: ${error.message}`)
      return []
    }

    return data || []
  } catch (error) {
    result.errors.push(`${label}: ${error instanceof Error ? error.message : 'erro desconhecido'}`)
    return []
  }
}

async function getSettings(
  supabaseAdmin: SupabaseAdmin,
  companyId: string
): Promise<SmartNotificationSettings> {
  try {
    const { data, error } = await supabaseAdmin
      .from('smart_notification_settings')
      .select('*')
      .eq('company_id', companyId)
      .maybeSingle()

    if (error) throw error

    if (!data) {
      await supabaseAdmin
        .from('smart_notification_settings')
        .insert({ company_id: companyId })

      return DEFAULT_SETTINGS
    }

    return {
      ...DEFAULT_SETTINGS,
      ...data,
      order_stuck_days: Number(data.order_stuck_days || DEFAULT_SETTINGS.order_stuck_days),
      lead_idle_days: Number(data.lead_idle_days || DEFAULT_SETTINGS.lead_idle_days),
      proposal_idle_days: Number(data.proposal_idle_days || DEFAULT_SETTINGS.proposal_idle_days),
      coupon_expiring_days: Number(data.coupon_expiring_days || DEFAULT_SETTINGS.coupon_expiring_days),
      subscription_expiring_days: Number(data.subscription_expiring_days || DEFAULT_SETTINGS.subscription_expiring_days),
    }
  } catch {
    return DEFAULT_SETTINGS
  }
}

async function createOnce(
  supabaseAdmin: SupabaseAdmin,
  result: SmartNotificationResult,
  input: {
    company_id: string
    event_key: string
    event_type: string
    entity?: string
    entity_id?: string
    titulo: string
    mensagem: string
    link_url?: string
    tipo?: string
    payload?: Record<string, any>
  }
) {
  try {
    const { error } = await supabaseAdmin
      .from('smart_notification_events')
      .insert({
        company_id: input.company_id,
        event_key: input.event_key,
        event_type: input.event_type,
        entity: input.entity || null,
        entity_id: input.entity_id || null,
      })

    if (error) {
      if (error.code === '23505') {
        result.skipped += 1
        result.events.push({
          type: input.event_type,
          title: input.titulo,
          link_url: input.link_url,
          created: false,
        })
        return false
      }

      result.errors.push(`${input.event_type}: ${error.message}`)
      return false
    }

    await createNotification(supabaseAdmin, {
      company_id: input.company_id,
      tipo: input.tipo || 'smart',
      titulo: input.titulo,
      mensagem: input.mensagem,
      link_url: input.link_url,
      payload: {
        smart: true,
        event_key: input.event_key,
        event_type: input.event_type,
        ...(input.payload || {}),
      },
    })

    result.created += 1
    result.events.push({
      type: input.event_type,
      title: input.titulo,
      link_url: input.link_url,
      created: true,
    })

    return true
  } catch (error) {
    result.errors.push(`${input.event_type}: ${error instanceof Error ? error.message : 'erro desconhecido'}`)
    return false
  }
}

export async function scanCompanySmartNotifications(
  supabaseAdmin: SupabaseAdmin,
  company: any
): Promise<SmartNotificationResult> {
  const companyId = String(company?.id || '')
  const settings = await getSettings(supabaseAdmin, companyId)

  const result: SmartNotificationResult = {
    company_id: companyId,
    created: 0,
    skipped: 0,
    errors: [],
    events: [],
  }

  if (!companyId) {
    result.errors.push('Empresa sem ID.')
    return result
  }

  if (settings.new_order_enabled) {
    const orders = await safeRows(
      supabaseAdmin,
      result,
      'novos pedidos',
      supabaseAdmin
        .from('orders')
        .select('*')
        .eq('company_id', companyId)
        .gte('created_at', new Date(daysAgoMs(1)).toISOString())
        .limit(80)
    )

    for (const order of orders) {
      if (isFinalOrder(order.status)) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `new_order:${order.id}`,
        event_type: 'new_order',
        entity: 'orders',
        entity_id: String(order.id),
        tipo: 'order',
        titulo: 'Novo pedido recebido',
        mensagem: `${order.nome || 'Cliente'} enviou um pedido${order.produto ? `: ${order.produto}` : '.'}`,
        link_url: `/painel/pedidos/${order.id}`,
        payload: { order_id: order.id },
      })
    }
  }

  if (settings.order_stuck_enabled) {
    const openOrders = await safeRows(
      supabaseAdmin,
      result,
      'pedidos parados',
      supabaseAdmin
        .from('orders')
        .select('*')
        .eq('company_id', companyId)
        .limit(250)
    )

    const cutoff = daysAgoMs(settings.order_stuck_days)

    for (const order of openOrders) {
      if (isFinalOrder(order.status)) continue

      const ref = toMs(order.updated_at || order.created_at)
      if (!ref || ref > cutoff) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `order_stuck:${order.id}:${order.status || 'sem_status'}`,
        event_type: 'order_stuck',
        entity: 'orders',
        entity_id: String(order.id),
        tipo: 'order',
        titulo: 'Pedido parado há alguns dias',
        mensagem: `${order.nome || 'Cliente'} está com pedido em "${order.status || 'sem status'}" há ${settings.order_stuck_days}+ dias.`,
        link_url: `/painel/pedidos/${order.id}`,
        payload: { order_id: order.id, status: order.status },
      })
    }
  }

  if (settings.task_due_today_enabled) {
    const tasks = await safeRows(
      supabaseAdmin,
      result,
      'tarefas vencendo hoje',
      supabaseAdmin
        .from('internal_tasks')
        .select('*')
        .eq('company_id', companyId)
        .neq('status', 'concluida')
        .limit(200)
    )

    const start = new Date()
    start.setHours(0, 0, 0, 0)
    const end = new Date()
    end.setHours(23, 59, 59, 999)
    const key = dayKey(start)

    for (const task of tasks) {
      const due = toMs(task.due_at)
      if (!due || due < start.getTime() || due > end.getTime()) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `task_due_today:${task.id}:${key}`,
        event_type: 'task_due_today',
        entity: 'internal_tasks',
        entity_id: String(task.id),
        tipo: 'task',
        titulo: 'Tarefa vence hoje',
        mensagem: task.titulo || 'Uma tarefa precisa de atenção hoje.',
        link_url: '/painel/tarefas',
        payload: { task_id: task.id },
      })
    }
  }

  if (settings.lead_idle_enabled) {
    const leads = await safeRows(
      supabaseAdmin,
      result,
      'leads sem contato',
      supabaseAdmin
        .from('crm_leads')
        .select('*')
        .eq('company_id', companyId)
        .limit(250)
    )

    const cutoff = daysAgoMs(settings.lead_idle_days)

    for (const lead of leads) {
      if (isClosedLead(lead)) continue

      const nextContact = toMs(lead.proximo_contato_em)
      const ref = nextContact || toMs(lead.updated_at || lead.created_at)

      if (!ref || ref > cutoff) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `lead_idle:${lead.id}:${lead.etapa || 'etapa'}`,
        event_type: 'lead_idle',
        entity: 'crm_leads',
        entity_id: String(lead.id),
        tipo: 'crm',
        titulo: 'Lead sem contato há alguns dias',
        mensagem: `${lead.nome || 'Lead'} precisa de retorno. Etapa atual: ${lead.etapa || 'não definida'}.`,
        link_url: '/painel/crm',
        payload: { lead_id: lead.id },
      })
    }
  }

  if (settings.proposal_idle_enabled) {
    const proposals = await safeRows(
      supabaseAdmin,
      result,
      'propostas sem resposta',
      supabaseAdmin
        .from('proposals')
        .select('*')
        .eq('company_id', companyId)
        .limit(250)
    )

    const cutoff = daysAgoMs(settings.proposal_idle_days)

    for (const proposal of proposals) {
      if (isClosedProposal(proposal)) continue

      const ref = toMs(proposal.updated_at || proposal.created_at)
      if (!ref || ref > cutoff) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `proposal_idle:${proposal.id}:${proposal.status || 'status'}`,
        event_type: 'proposal_idle',
        entity: 'proposals',
        entity_id: String(proposal.id),
        tipo: 'proposal',
        titulo: 'Proposta sem resposta',
        mensagem: `${proposal.titulo || proposal.cliente_nome || 'Uma proposta'} está sem resposta há ${settings.proposal_idle_days}+ dias.`,
        link_url: '/painel/propostas',
        payload: { proposal_id: proposal.id },
      })
    }
  }

  if (settings.coupon_expiring_enabled) {
    const coupons = await safeRows(
      supabaseAdmin,
      result,
      'cupons perto de expirar',
      supabaseAdmin
        .from('marketplace_coupons')
        .select('*')
        .eq('company_id', companyId)
        .eq('ativo', true)
        .limit(200)
    )

    const limit = daysAheadMs(settings.coupon_expiring_days)

    for (const coupon of coupons) {
      const ends = toMs(coupon.ends_at)
      if (!ends || ends < nowMs() || ends > limit) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `coupon_expiring:${coupon.id}:${String(coupon.ends_at).slice(0, 10)}`,
        event_type: 'coupon_expiring',
        entity: 'marketplace_coupons',
        entity_id: String(coupon.id),
        tipo: 'coupon',
        titulo: 'Cupom perto de expirar',
        mensagem: `O cupom ${coupon.codigo || coupon.codigo_normalizado || 'sem código'} expira em breve.`,
        link_url: '/painel/cupons',
        payload: { coupon_id: coupon.id },
      })
    }
  }

  if (settings.product_without_image_enabled) {
    const products = await safeRows(
      supabaseAdmin,
      result,
      'produtos sem imagem',
      supabaseAdmin
        .from('products')
        .select('*')
        .eq('company_id', companyId)
        .limit(250)
    )

    for (const product of products) {
      if (product.arquivado || product.oculto || product.ativo === false) continue
      if (hasProductImage(product)) continue

      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `product_no_image:${product.id}`,
        event_type: 'product_no_image',
        entity: 'products',
        entity_id: String(product.id),
        tipo: 'product',
        titulo: 'Produto sem imagem',
        mensagem: `${product.nome || 'Um produto'} está sem imagem no catálogo.`,
        link_url: `/painel/produtos/${product.id}`,
        payload: { product_id: product.id },
      })
    }
  }

  if (settings.site_without_logo_enabled && !company.logo_url) {
    await createOnce(supabaseAdmin, result, {
      company_id: companyId,
      event_key: `site_no_logo:${companyId}`,
      event_type: 'site_no_logo',
      entity: 'companies',
      entity_id: companyId,
      tipo: 'site',
      titulo: 'Site sem logo',
      mensagem: 'O site público ainda não tem logo. Isso deixa a página com cara de obra inacabada.',
      link_url: '/painel/site',
      payload: { company_id: companyId },
    })
  }

  if (settings.subscription_expiring_enabled && company.assinatura_expira_em) {
    const expiration = toMs(company.assinatura_expira_em)

    if (expiration && expiration >= nowMs() && expiration <= daysAheadMs(settings.subscription_expiring_days)) {
      await createOnce(supabaseAdmin, result, {
        company_id: companyId,
        event_key: `subscription_expiring:${companyId}:${String(company.assinatura_expira_em).slice(0, 10)}`,
        event_type: 'subscription_expiring',
        entity: 'companies',
        entity_id: companyId,
        tipo: 'subscription',
        titulo: 'Assinatura perto de vencer',
        mensagem: `A assinatura vence em até ${settings.subscription_expiring_days} dias.`,
        link_url: '/assinatura',
        payload: { company_id: companyId },
      })
    }
  }

  return result
}

import 'server-only'

import { createHash } from 'node:crypto'
import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getClientIp } from '@/lib/orcaly-security'

type RateLimitOptions = {
  scope: string
  limit: number
  windowSeconds: number
  identity?: string
  failOpen?: boolean
}

function adminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!url || !key) {
    throw new Error('Rate limit sem configuracao segura do Supabase.')
  }

  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  })
}

function keyFor(scope: string, identity: string) {
  return createHash('sha256')
    .update(`orcaly-rate-limit:v1:${scope}:${identity}`)
    .digest('hex')
}

export async function enforceRateLimit(
  request: NextRequest,
  options: RateLimitOptions,
) {
  const identity = String(options.identity || getClientIp(request) || 'unknown')
  const key = keyFor(options.scope, identity)

  try {
    const { data, error } = await adminClient().rpc('orcaly_consume_rate_limit', {
      p_key: key,
      p_limit: Math.max(1, Math.floor(options.limit)),
      p_window_seconds: Math.max(1, Math.floor(options.windowSeconds)),
    })

    if (error) throw error

    const row = Array.isArray(data) ? data[0] : data
    const allowed = row?.allowed === true
    const remaining = Math.max(0, Number(row?.remaining || 0))
    const resetAt = row?.reset_at ? new Date(row.reset_at) : null
    const retryAfter = resetAt
      ? Math.max(1, Math.ceil((resetAt.getTime() - Date.now()) / 1000))
      : options.windowSeconds

    if (!allowed) {
      const response = NextResponse.json(
        { error: 'Muitas tentativas. Aguarde e tente novamente.' },
        { status: 429 },
      )
      response.headers.set('Retry-After', String(retryAfter))
      response.headers.set('X-RateLimit-Remaining', '0')
      return response
    }

    return null
  } catch (error) {
    console.error(
      'orcaly_rate_limit_error',
      error instanceof Error ? error.message : error,
    )

    if (options.failOpen) return null

    return NextResponse.json(
      { error: 'Protecao temporariamente indisponivel.' },
      { status: 503 },
    )
  }
}

import "server-only";

import {
  createHmac,
  randomUUID,
  timingSafeEqual,
} from "node:crypto";
import { createClient } from "@supabase/supabase-js";
import { signupMercadoPagoRequest } from "@/lib/payments/signup/mercado-pago";

type JsonRecord = Record<string, unknown>;
type SignupPlanKey = "essencial" | "profissional" | "premium";

const DAY_MS = 86_400_000;

export const SIGNUP_PLANS: Record<
  SignupPlanKey,
  {
    key: SignupPlanKey;
    name: string;
    price: number;
    description: string;
  }
> = {
  essencial: {
    key: "essencial",
    name: "Básico",
    price: 49.9,
    description: "Site, catálogo e pedidos.",
  },
  profissional: {
    key: "profissional",
    name: "Intermediário",
    price: 99.9,
    description: "Mais recursos para organizar e vender.",
  },
  premium: {
    key: "premium",
    name: "Premium",
    price: 149.9,
    description: "Recursos avançados para operações em crescimento.",
  },
};

function text(value: unknown) {
  return String(value || "").trim();
}

function record(value: unknown): JsonRecord {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return value as JsonRecord;
}

function digits(value: unknown) {
  return text(value).replace(/\D/g, "");
}

function planKey(value: unknown): SignupPlanKey {
  const normalized = text(value).toLowerCase();

  if (normalized === "premium") return "premium";

  if (
    normalized === "profissional" ||
    normalized === "intermediario" ||
    normalized === "intermediário"
  ) {
    return "profissional";
  }

  return "essencial";
}

function adminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const serviceRole = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !serviceRole) {
    throw new Error("Configuração segura do Supabase ausente.");
  }

  return createClient(url, serviceRole, {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
    },
  });
}

function appUrl() {
  const candidates = [
    process.env.ORCALY_APP_URL,
    process.env.NEXT_PUBLIC_SITE_URL,
    process.env.NEXT_PUBLIC_APP_URL,
    "https://orcaly.com.br",
  ];

  for (const candidate of candidates) {
    const value = text(candidate).replace(/\/$/, "");

    if (!value) continue;

    try {
      const url = new URL(value);
      const localHost = [
        "localhost",
        "127.0.0.1",
        "::1",
      ].includes(url.hostname);

      if (url.protocol === "https:" && !localHost) {
        return url.origin;
      }
    } catch {
      // Ignora valores malformados e tenta a proxima URL publica.
    }
  }

  return "https://orcaly.com.br";
}

function signingKey() {
  const value = text(process.env.PAYMENT_CREDENTIALS_ENCRYPTION_KEY);

  if (!value) {
    throw new Error("Chave de segurança do checkout ausente.");
  }

  return value;
}

function signaturePayload(leadId: string, expires: number) {
  return `${leadId}:${expires}`;
}

export function createSignupCheckoutToken(
  leadId: string,
  expires = Date.now() + 4 * 60 * 60 * 1000,
) {
  const token = createHmac("sha256", signingKey())
    .update(signaturePayload(leadId, expires))
    .digest("base64url");

  return { token, expires };
}

export function verifySignupCheckoutToken(
  leadId: string,
  expires: unknown,
  token: unknown,
) {
  const expiration = Number(expires || 0);
  const supplied = text(token);

  if (
    !leadId ||
    !supplied ||
    !Number.isFinite(expiration) ||
    expiration <= Date.now()
  ) {
    return false;
  }

  const expected = createHmac("sha256", signingKey())
    .update(signaturePayload(leadId, expiration))
    .digest();

  let received: Buffer;

  try {
    received = Buffer.from(supplied, "base64url");
  } catch {
    return false;
  }

  return (
    received.length === expected.length &&
    timingSafeEqual(received, expected)
  );
}

async function getLead(leadId: string) {
  const admin = adminClient();
  const { data, error } = await admin
    .from("signup_leads")
    .select("*")
    .eq("id", leadId)
    .maybeSingle();

  if (error) throw error;

  if (!data) {
    throw Object.assign(new Error("Cadastro não encontrado."), {
      status: 404,
    });
  }

  return { admin, lead: data as JsonRecord };
}

function checkoutSummary(lead: JsonRecord) {
  const raw = record(lead.raw_data);
  const selected = SIGNUP_PLANS[planKey(lead.plano)];
  const paymentMethod = text(raw.signup_payment_method);
  const paymentStatus = text(lead.payment_status || raw.signup_payment_status);
  const pix = record(raw.signup_pix);
  const subscription = record(raw.signup_subscription);

  return {
    leadId: text(lead.id),
    responsibleName: text(lead.nome_responsavel),
    companyName: text(lead.empresa_nome),
    email: text(lead.email),
    phone: text(lead.whatsapp),
    document: digits(
      raw.signup_document ||
        raw.cpf_cnpj ||
        raw.documento,
    ),
    plan: selected,
    status: text(lead.status),
    paymentMethod: paymentMethod || null,
    paymentStatus: paymentStatus || null,
    readyToCreateAccount:
      text(lead.status) === "trial_ready" ||
      text(lead.status) === "pago" ||
      text(lead.status) === "convertido",
    converted: text(lead.status) === "convertido",
    pix: {
      paymentId: text(pix.payment_id) || null,
      qrCode: text(pix.qr_code) || null,
      qrCodeBase64: text(pix.qr_code_base64) || null,
      ticketUrl: text(pix.ticket_url) || null,
      expirationDate: text(pix.expiration_date) || null,
    },
    subscription: {
      id: text(subscription.id) || null,
      status: text(subscription.status) || null,
      nextPaymentDate: text(subscription.next_payment_date) || null,
    },
  };
}

export async function loadSignupCheckout(
  leadId: string,
  expires: unknown,
  token: unknown,
) {
  if (!verifySignupCheckoutToken(leadId, expires, token)) {
    throw Object.assign(
      new Error("Este link de pagamento expirou. Volte ao cadastro e continue novamente."),
      { status: 401 },
    );
  }

  const { lead } = await getLead(leadId);
  return checkoutSummary(lead);
}

function mergeRawData(lead: JsonRecord, patch: JsonRecord) {
  return {
    ...record(lead.raw_data),
    ...patch,
  };
}

function pixFields(payment: JsonRecord) {
  const point = record(payment.point_of_interaction);
  const transaction = record(point.transaction_data);

  return {
    payment_id: text(payment.id),
    status: text(payment.status),
    qr_code: text(transaction.qr_code),
    qr_code_base64: text(transaction.qr_code_base64),
    ticket_url: text(transaction.ticket_url),
    expiration_date: text(payment.date_of_expiration),
  };
}

export async function createSignupPix(input: {
  leadId: string;
  expires: unknown;
  checkoutToken: unknown;
  document: unknown;
}) {
  if (
    !verifySignupCheckoutToken(
      input.leadId,
      input.expires,
      input.checkoutToken,
    )
  ) {
    throw Object.assign(new Error("Checkout expirado."), {
      status: 401,
    });
  }

  const { admin, lead } = await getLead(input.leadId);

  if (["pago", "trial_ready", "convertido"].includes(text(lead.status))) {
    return checkoutSummary(lead);
  }

  const raw = record(lead.raw_data);
  const existingPix = record(raw.signup_pix);
  const existingPaymentId = text(existingPix.payment_id);

  if (existingPaymentId) {
    const remote = await signupMercadoPagoRequest(
      `/v1/payments/${encodeURIComponent(existingPaymentId)}`,
    );

    const nextPix = pixFields(remote);
    const approved = text(remote.status) === "approved";

    await admin
      .from("signup_leads")
      .update({
        status: approved ? "pago" : "checkout_criado",
        payment_status: text(remote.status) || "pending",
        mercado_pago_payment_id: existingPaymentId,
        paid_at: approved ? new Date().toISOString() : null,
        raw_data: mergeRawData(lead, {
          signup_payment_method: "pix",
          signup_payment_status: text(remote.status) || "pending",
          signup_bonus_days: 7,
          signup_pix: nextPix,
        }),
      })
      .eq("id", input.leadId);

    const refreshed = await getLead(input.leadId);
    return checkoutSummary(refreshed.lead);
  }

  const selected = SIGNUP_PLANS[planKey(lead.plano)];
  const cpfCnpj = digits(
    input.document ||
      raw.signup_document ||
      raw.cpf_cnpj ||
      raw.documento,
  );

  if (![11, 14].includes(cpfCnpj.length)) {
    throw Object.assign(new Error("Informe um CPF ou CNPJ válido."), {
      status: 400,
    });
  }

  const idempotency = randomUUID();
  const expiration = new Date(Date.now() + 30 * 60 * 1000).toISOString();

  const payment = await signupMercadoPagoRequest(
    "/v1/payments",
    {
      method: "POST",
      body: JSON.stringify({
        transaction_amount: selected.price,
        description: `Plano ${selected.name} - Orçaly`,
        payment_method_id: "pix",
        external_reference: `signup_pix:${input.leadId}`,
        notification_url: `${appUrl()}/api/mercado-pago/webhook-leads`,
        date_of_expiration: expiration,
        payer: {
          email: text(lead.email),
          first_name: text(lead.nome_responsavel),
          identification: {
            type: cpfCnpj.length === 14 ? "CNPJ" : "CPF",
            number: cpfCnpj,
          },
        },
        metadata: {
          lead_id: input.leadId,
          origin: "signup",
          plan: selected.key,
          bonus_days: 7,
        },
      }),
    },
    idempotency,
  );

  const nextPix = pixFields(payment);

  await admin
    .from("signup_leads")
    .update({
      status: "checkout_criado",
      payment_status: text(payment.status) || "pending",
      mercado_pago_payment_id: text(payment.id) || null,
      checkout_url: null,
      raw_data: mergeRawData(lead, {
        signup_payment_method: "pix",
        signup_payment_status: text(payment.status) || "pending",
        signup_bonus_days: 7,
        signup_pix: nextPix,
      }),
    })
    .eq("id", input.leadId);

  const refreshed = await getLead(input.leadId);
  return checkoutSummary(refreshed.lead);
}

export async function createSignupCardSubscription(input: {
  leadId: string;
  expires: unknown;
  checkoutToken: unknown;
  cardTokenId: unknown;
  payerEmail: unknown;
}) {
  if (
    !verifySignupCheckoutToken(
      input.leadId,
      input.expires,
      input.checkoutToken,
    )
  ) {
    throw Object.assign(new Error("Checkout expirado."), {
      status: 401,
    });
  }

  const { admin, lead } = await getLead(input.leadId);

  if (["trial_ready", "convertido"].includes(text(lead.status))) {
    return checkoutSummary(lead);
  }

  const leadRaw = record(lead.raw_data);
  const existingPix = record(leadRaw.signup_pix);
  const existingPixId = text(existingPix.payment_id);
  const existingPixStatus = text(
    existingPix.status || lead.payment_status,
  ).toLowerCase();

  if (
    existingPixId &&
    !["rejected", "canceled", "cancelled", "expired"].includes(
      existingPixStatus,
    )
  ) {
    throw Object.assign(
      new Error(
        "Já existe um Pix aguardando pagamento. Conclua ou aguarde a expiração.",
      ),
      { status: 409 },
    );
  }

  const selected = SIGNUP_PLANS[planKey(lead.plano)];
  const cardTokenId = text(input.cardTokenId);
  const payerEmail = text(input.payerEmail || lead.email).toLowerCase();

  if (!cardTokenId) {
    throw Object.assign(
      new Error("Não foi possível validar o cartão."),
      { status: 400 },
    );
  }

  if (!payerEmail.includes("@")) {
    throw Object.assign(new Error("Informe um e-mail válido."), {
      status: 400,
    });
  }

  const subscription = await signupMercadoPagoRequest("/preapproval", {
    method: "POST",
    body: JSON.stringify({
      reason: `Plano ${selected.name} - Orçaly`,
      external_reference: `signup_subscription:${input.leadId}:${selected.key}`,
      payer_email: payerEmail,
      card_token_id: cardTokenId,
      auto_recurring: {
        frequency: 1,
        frequency_type: "months",
        transaction_amount: selected.price,
        currency_id: "BRL",
        free_trial: {
          frequency: 7,
          frequency_type: "days",
        },
      },
      back_url: `${appUrl()}/checkout/cadastro`,
      status: "authorized",
    }),
  });

  const remoteStatus = text(subscription.status) || "authorized";

  if (!text(subscription.id)) {
    throw Object.assign(
      new Error("O Mercado Pago não confirmou a assinatura."),
      { status: 502 },
    );
  }

  const raw = mergeRawData(lead, {
    signup_payment_method: "card",
    signup_payment_status: remoteStatus,
    signup_trial_days: 7,
    signup_subscription: {
      id: text(subscription.id),
      status: remoteStatus,
      next_payment_date: text(subscription.next_payment_date),
      payer_email: payerEmail,
    },
  });

  await admin
    .from("signup_leads")
    .update({
      status: "trial_ready",
      payment_status: remoteStatus,
      checkout_url: null,
      raw_data: raw,
    })
    .eq("id", input.leadId);

  const refreshed = await getLead(input.leadId);
  return checkoutSummary(refreshed.lead);
}

export async function refreshSignupCheckoutStatus(input: {
  leadId: string;
  expires: unknown;
  checkoutToken: unknown;
}) {
  if (
    !verifySignupCheckoutToken(
      input.leadId,
      input.expires,
      input.checkoutToken,
    )
  ) {
    throw Object.assign(new Error("Checkout expirado."), {
      status: 401,
    });
  }

  const { admin, lead } = await getLead(input.leadId);

  if (["trial_ready", "pago", "convertido"].includes(text(lead.status))) {
    return checkoutSummary(lead);
  }

  const raw = record(lead.raw_data);
  const pix = record(raw.signup_pix);
  const paymentId = text(pix.payment_id || lead.mercado_pago_payment_id);

  if (!paymentId) {
    return checkoutSummary(lead);
  }

  const payment = await signupMercadoPagoRequest(
    `/v1/payments/${encodeURIComponent(paymentId)}`,
  );
  const status = text(payment.status) || "pending";
  const approved = status === "approved";

  await admin
    .from("signup_leads")
    .update({
      status: approved ? "pago" : "checkout_criado",
      payment_status: status,
      mercado_pago_payment_id: paymentId,
      paid_at: approved ? new Date().toISOString() : null,
      raw_data: mergeRawData(lead, {
        signup_payment_method: "pix",
        signup_payment_status: status,
        signup_bonus_days: 7,
        signup_pix: pixFields(payment),
      }),
    })
    .eq("id", input.leadId);

  const refreshed = await getLead(input.leadId);
  return checkoutSummary(refreshed.lead);
}

import { createNotification } from '@/lib/orcaly-audit'
import { getWhatsAppSettings, money, sanitizePhone, sendWhatsAppMessage, shortId } from '@/lib/whatsapp'

type SupabaseAdmin = any

function siteUrl() {
  return (process.env.NEXT_PUBLIC_SITE_URL || 'https://orcaly.com.br').replace(/\/$/, '')
}

function orderUrl(order: any) {
  return order?.id ? `${siteUrl()}/painel/pedidos/${order.id}` : `${siteUrl()}/painel/pedidos`
}

function statusMessage(status: string, companyName: string, orderNumber: string) {
  const normalized = String(status || '').toLowerCase()

  if (normalized.includes('análise') || normalized.includes('analise')) {
    return `Seu pedido ${orderNumber} está em análise. A equipe da ${companyName} está conferindo os detalhes antes de seguir.`
  }

  if (normalized.includes('aprov')) {
    return `Seu pedido ${orderNumber} foi aprovado. A equipe da ${companyName} vai seguir para a próxima etapa.`
  }

  if (normalized.includes('produção') || normalized.includes('producao')) {
    return `Seu pedido ${orderNumber} entrou em produção. A equipe da ${companyName} já está trabalhando nele.`
  }

  if (normalized.includes('pronto')) {
    return `Seu pedido ${orderNumber} está pronto. A equipe da ${companyName} vai combinar retirada, entrega ou finalização.`
  }

  if (normalized.includes('entreg')) {
    return `Seu pedido ${orderNumber} foi marcado como entregue. Obrigado por comprar com ${companyName}.`
  }

  if (normalized.includes('cancel')) {
    return `Seu pedido ${orderNumber} foi cancelado. Se tiver dúvidas, fale com a equipe da ${companyName}.`
  }

  if (normalized.includes('pendente')) {
    return `Seu pedido ${orderNumber} está pendente. A equipe da ${companyName} pode precisar de alguma informação para continuar.`
  }

  return `Atualização do seu pedido ${orderNumber}: ${status}. Empresa: ${companyName}.`
}

async function safeSend(supabaseAdmin: SupabaseAdmin, options: any) {
  try {
    return await sendWhatsAppMessage(supabaseAdmin, options)
