export async function notifyNewOrder(
  supabaseAdmin: SupabaseAdmin,
  payload: {
    company: any
    order: any
    cliente?: any
    total?: number
    resumo?: string
  }
) {
  const { company, order } = payload
  if (!company?.id || !order?.id) return { ok: false, skipped: true }

  const settings = await getWhatsAppSettings(supabaseAdmin, company.id)
  const numero = `#${shortId(order.id)}`
  const total = Number(payload.total || order.valor_total || order.preco_estimado || 0)
  const resumo = payload.resumo || order.itens_resumo || order.produto || 'Pedido'
  const companyName = company.nome || 'Empresa'
  const customerName = order.nome || payload.cliente?.nome || 'Cliente'
  const customerPhone = order.telefone || payload.cliente?.telefone || 'não informado'
  const link = orderUrl(order)

  await safeInternalNotification(supabaseAdmin, {
    companyId: company.id,
    title: 'Novo pedido recebido',
    message: `${customerName} enviou um pedido: ${resumo}. Valor: ${money(total)}.`,
    linkUrl: link,
    orderId: order.id,
  })

  await safeUpdateOrder(supabaseAdmin, order.id, {
    notificado_em: new Date().toISOString(),
  })

  if (!settings.enabled) {
    return { ok: true, whatsapp_skipped: true, reason: 'WhatsApp desativado nas configurações.' }
  }

  const results: any[] = []

  if (settings.notify_owner_new_order) {
    const to = sanitizePhone(settings.owner_phone || company.whatsapp)

    if (to) {
      const result = await safeSend(supabaseAdmin, {
        companyId: company.id,
        orderId: order.id,
        eventType: 'owner_new_order',
        to,
        text:
          `Novo pedido recebido no Orçaly.\n\n` +
          `Pedido: ${numero}\n` +
          `Cliente: ${customerName}\n` +
          `WhatsApp: ${customerPhone}\n` +
          `Itens: ${resumo}\n` +
          `Valor: ${money(total)}\n\n` +
          `Abrir pedido: ${link}`,
        templateName: settings.template_order_created,
        templateParams: [companyName, numero, customerName, money(total), link],
        templateLanguage: settings.template_language,
        phoneNumberId: settings.phone_number_id,
      })

      results.push({ target: 'owner', ...result })

      if (result?.ok) {
        await safeUpdateOrder(supabaseAdmin, order.id, {
          whatsapp_owner_notified_at: new Date().toISOString(),
        })
      }
    }
  }

  if (settings.notify_client_new_order) {
    const to = sanitizePhone(order.telefone || payload.cliente?.telefone)

    if (to) {
      const result = await safeSend(supabaseAdmin, {
        companyId: company.id,
        orderId: order.id,
        eventType: 'client_new_order',
        to,
        text:
          `Olá, ${customerName}!\n\n` +
          `Recebemos seu pedido ${numero} em ${companyName}.\n` +
          `Itens: ${resumo}\n` +
          `Valor estimado: ${money(total)}\n\n` +
          `Nossa equipe vai analisar e seguir com o atendimento.`,
        templateName: settings.template_order_created,
        templateParams: [customerName, numero, companyName, money(total)],
        templateLanguage: settings.template_language,
        phoneNumberId: settings.phone_number_id,
      })

      results.push({ target: 'client_created', ...result })

      if (result?.ok) {
        await safeUpdateOrder(supabaseAdmin, order.id, {
          whatsapp_client_created_notified_at: new Date().toISOString(),
        })
      }
    }
  }

  return { ok: true, results }
}

export async function notifyOrderStatus(
  supabaseAdmin: SupabaseAdmin,
  payload: {
    company: any
    order: any
    status: string
    source?: string
  }
) {
  const { company, order } = payload

  if (!company?.id || !order?.id || !payload.status) {
    return { ok: false, skipped: true }
  }

  const settings = await getWhatsAppSettings(supabaseAdmin, company.id)

  if (!settings.enabled || !settings.notify_client_order_status) {
    return { ok: true, whatsapp_skipped: true, reason: 'WhatsApp de status desativado.' }
  }

  const to = sanitizePhone(order.telefone || order.customer_whatsapp)

  if (!to) {
    return { ok: false, skipped: true, reason: 'Cliente sem WhatsApp/telefone.' }
  }

  const numero = `#${shortId(order.id)}`
  const companyName = company.nome || 'Empresa'
  const customerName = order.nome || order.customer_name || 'Cliente'
  const message = statusMessage(payload.status, companyName, numero)

  const result = await safeSend(supabaseAdmin, {
    companyId: company.id,
    orderId: order.id,
    eventType: `client_order_status_${payload.source || 'manual'}`,
    to,
    text:
      `Olá, ${customerName}!\n\n` +
      `${message}\n\n` +
      `Qualquer dúvida, responda esta mensagem.`,
    templateName: settings.template_order_status,
    templateParams: [customerName, numero, payload.status, companyName],
    templateLanguage: settings.template_language,
    phoneNumberId: settings.phone_number_id,
  })

  if (result?.ok) {
    await safeUpdateOrder(supabaseAdmin, order.id, {
      whatsapp_last_status_notified: payload.status,
      whatsapp_last_status_notified_at: new Date().toISOString(),
    })
  }

  return result
}

export async function notifyProposalAction(
  supabaseAdmin: SupabaseAdmin,
  payload: {
    company: any
    proposal: any
    event: 'sent' | 'approved' | 'change_requested' | 'rejected'
    note?: string | null
    pixValor?: number | null
  }
) {
  const { company, proposal } = payload
  if (!company?.id || !proposal?.id) return

  const settings = await getWhatsAppSettings(supabaseAdmin, company.id)
  if (!settings.enabled) return

  const numero = proposal.proposta_numero || `#${shortId(proposal.id)}`
  const valor = money(proposal.valor_total || 0)
  const label: Record<string, string> = {
    sent: 'Proposta enviada',
    approved: 'Proposta aprovada',
    change_requested: 'Alteração solicitada',
    rejected: 'Proposta recusada',
  }

  if (settings.notify_owner_proposal) {
    const to = sanitizePhone(settings.owner_phone || company.whatsapp)
    if (to) {
      await safeSend(supabaseAdmin, {
        companyId: company.id,
        orderId: proposal.order_id,
        proposalId: proposal.id,
        eventType: `owner_proposal_${payload.event}`,
        to,
        text: `${label[payload.event]} no Orçaly.\n\nProposta: ${numero}\nCliente: ${proposal.cliente_nome || 'Cliente'}\nValor: ${valor}${payload.note ? `\nObservação: ${payload.note}` : ''}`,
        templateName: settings.template_proposal_update,
        templateParams: [company.nome || 'Empresa', numero, label[payload.event], proposal.cliente_nome || 'Cliente', valor],
        templateLanguage: settings.template_language,
        phoneNumberId: settings.phone_number_id,
      })
    }
  }

  if (settings.notify_client_proposal) {
    const to = sanitizePhone(proposal.cliente_whatsapp)
    if (to) {
      await safeSend(supabaseAdmin, {
        companyId: company.id,
        orderId: proposal.order_id,
        proposalId: proposal.id,
        eventType: `client_proposal_${payload.event}`,
        to,
        text: `${label[payload.event]}: ${numero}\n\nValor: ${valor}\nEmpresa: ${company.nome || 'Empresa'}\n${proposal.token ? `${siteUrl()}/proposta/${proposal.token}` : ''}`,
        templateName: settings.template_proposal_update,
        templateParams: [proposal.cliente_nome || 'Cliente', numero, label[payload.event], valor, company.nome || 'Empresa'],
        templateLanguage: settings.template_language,
        phoneNumberId: settings.phone_number_id,
      })
    }
  }
}

import crypto from 'crypto'

type SupabaseAdmin = any

export function sanitizePhone(value: unknown) {
  let phone = String(value || '').replace(/\D/g, '')
  if (!phone) return ''
  if (!phone.startsWith('55') && phone.length >= 10 && phone.length <= 11) phone = `55${phone}`
  return phone
}

export function money(value: unknown) {
  return Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
}

export function shortId(value: unknown) {
  return String(value || '').slice(0, 8).toUpperCase()
}

function graphVersion() {
  return process.env.WHATSAPP_GRAPH_VERSION || 'v23.0'
}

function token() {
  return process.env.WHATSAPP_CLOUD_API_TOKEN || process.env.WHATSAPP_ACCESS_TOKEN || ''
}

function defaultPhoneNumberId() {
  return process.env.WHATSAPP_PHONE_NUMBER_ID || ''
}

export function verifyWhatsAppSignature(rawBody: string, signatureHeader?: string | null) {
  const appSecret = process.env.WHATSAPP_APP_SECRET
  if (!appSecret) return true
  if (!signatureHeader || !signatureHeader.startsWith('sha256=')) return false
  const expected = `sha256=${crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex')}`
  try { return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signatureHeader)) } catch { return false }
}

export async function getWhatsAppSettings(supabaseAdmin: SupabaseAdmin, companyId: string) {
  const { data, error } = await supabaseAdmin
    .from('company_whatsapp_settings').select('*').eq('company_id', companyId).maybeSingle()
  if (error) throw error
  return {
    company_id: companyId,
    enabled: Boolean(data?.enabled),
    ai_enabled: Boolean(data?.ai_enabled),
    notify_owner_new_order: data?.notify_owner_new_order !== false,
    notify_client_new_order: data?.notify_client_new_order !== false,
    notify_client_order_status: data?.notify_client_order_status !== false,
    notify_client_proposal: data?.notify_client_proposal !== false,
    notify_owner_proposal: data?.notify_owner_proposal !== false,
    owner_phone: data?.owner_phone || null,
    phone_number_id: data?.phone_number_id || null,
    template_order_created: data?.template_order_created || null,
    template_order_status: data?.template_order_status || null,
    template_proposal_update: data?.template_proposal_update || null,
    template_payment_update: data?.template_payment_update || null,
    template_language: data?.template_language || 'pt_BR',
    fallback_message: data?.fallback_message || 'No momento não consegui responder automaticamente. Nossa equipe vai continuar seu atendimento.',
    ai_prompt: data?.ai_prompt || null,
  }
}

async function logMessage(supabaseAdmin: SupabaseAdmin, payload: any) {
  await supabaseAdmin.from('whatsapp_message_logs').insert({
    company_id: payload.companyId || null,
    order_id: payload.orderId || null,
    proposal_id: payload.proposalId || null,
    direction: payload.direction,
    event_type: payload.eventType || null,
    to_phone: payload.toPhone || null,
    from_phone: payload.fromPhone || null,
    message_type: payload.messageType || 'text',
    content: payload.content || null,
    status: payload.status || 'pending',
    meta_message_id: payload.metaMessageId || null,
    raw_payload: payload.rawPayload || null,
    raw_response: payload.rawResponse || null,
    error: payload.error || null,
  })
}

function textPayload(to: string, text: string) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: true, body: text.slice(0, 4096) } }
}

function templatePayload(to: string, templateName: string, language: string, params: string[]) {
  return {
    messaging_product: 'whatsapp',
    to,
    type: 'template',
    template: {
      name: templateName,
      language: { code: language || 'pt_BR' },
      components: params.length ? [{ type: 'body', parameters: params.map((text) => ({ type: 'text', text: String(text || '').slice(0, 1024) })) }] : [],
    },
  }
}

export async function sendWhatsAppMessage(supabaseAdmin: SupabaseAdmin, options: {
  companyId?: string | null
  orderId?: string | null
  proposalId?: string | null
  eventType: string
  to: string
  text: string
  templateName?: string | null
  templateParams?: string[]
  templateLanguage?: string | null
  phoneNumberId?: string | null
}) {
  const to = sanitizePhone(options.to)
  const accessToken = token()
  const phoneNumberId = options.phoneNumberId || defaultPhoneNumberId()

  if (!to || !accessToken || !phoneNumberId) {
    await logMessage(supabaseAdmin, { ...options, direction: 'outbound', toPhone: to || options.to, content: options.text, status: 'skipped', error: 'WhatsApp não configurado ou telefone inválido.' })
    return { ok: false, skipped: true }
  }

  const useTemplate = Boolean(options.templateName)
  const payload = useTemplate
    ? templatePayload(to, String(options.templateName), options.templateLanguage || 'pt_BR', options.templateParams || [])
    : textPayload(to, options.text)

  try {
    const response = await fetch(`https://graph.facebook.com/${graphVersion()}/${phoneNumberId}/messages`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })

    const data = await response.json().catch(() => ({}))
    const metaMessageId = data?.messages?.[0]?.id || null

    if (!response.ok) {
      const errorMessage = data?.error?.message || `Erro WhatsApp ${response.status}`
      await logMessage(supabaseAdmin, { ...options, direction: 'outbound', toPhone: to, messageType: useTemplate ? 'template' : 'text', content: options.text, status: 'failed', rawPayload: payload, rawResponse: data, error: errorMessage })
      return { ok: false, error: errorMessage, response: data }
    }

    await logMessage(supabaseAdmin, { ...options, direction: 'outbound', toPhone: to, messageType: useTemplate ? 'template' : 'text', content: options.text, status: 'sent', metaMessageId, rawPayload: payload, rawResponse: data })
    return { ok: true, messageId: metaMessageId }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Erro ao enviar WhatsApp.'
    await logMessage(supabaseAdmin, { ...options, direction: 'outbound', toPhone: to, content: options.text, status: 'failed', rawPayload: payload, error: errorMessage })
    return { ok: false, error: errorMessage }
  }
}

export async function getCompanyByWhatsAppPhoneNumberId(supabaseAdmin: SupabaseAdmin, phoneNumberId: string) {
  const { data: setting } = await supabaseAdmin
    .from('company_whatsapp_settings').select('company_id')
    .eq('phone_number_id', phoneNumberId).eq('enabled', true).limit(1).maybeSingle()

  const companyId = setting?.company_id
  if (!companyId) return null

  const { data } = await supabaseAdmin.from('companies').select('*').eq('id', companyId).maybeSingle()
  return data || null
}

export async function saveInbound(supabaseAdmin: SupabaseAdmin, payload: { companyId: string, from: string, to?: string, name?: string | null, text: string, raw?: any }) {
  const phone = sanitizePhone(payload.from)
  if (phone) {
    await supabaseAdmin.from('whatsapp_conversations').upsert({
      company_id: payload.companyId,
      phone,
      customer_name: payload.name || null,
      last_inbound_at: new Date().toISOString(),
      last_message: payload.text,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'company_id,phone' })
  }

  await logMessage(supabaseAdmin, { companyId: payload.companyId, direction: 'inbound', eventType: 'inbound_message', fromPhone: phone, toPhone: payload.to, content: payload.text, status: 'received', rawPayload: payload.raw })
}

export async function generateAiReply(context: { company: any, settings: any, inboundText: string, products?: any[] }) {
  const apiKey = process.env.OPENAI_API_KEY
  if (!apiKey) return context.settings.fallback_message

  const products = (context.products || []).slice(0, 30).map((p) => `- ${p.nome}: ${Number(p.preco || 0) > 0 ? money(p.preco) : 'sob consulta'}${p.descricao ? ` — ${p.descricao}` : ''}`).join('\\n')

  const prompt = `
Você é atendente automático da empresa "${context.company?.nome || 'Empresa'}" no Orçaly.
Responda em português brasileiro, curto, educado e comercial.
Não invente valores fora do catálogo.
Se faltar informação para orçamento, peça medidas, quantidade, prazo e arquivo/referência.
Se o cliente pedir humano, diga que a equipe seguirá o atendimento.
Produtos/serviços:
${products || 'Catálogo não informado.'}

Instruções da empresa:
${context.settings.ai_prompt || 'Conduza o cliente para um orçamento.'}
`.trim()

  const response = await fetch('https://api.openai.com/v1/responses', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: process.env.ORCALY_AI_MODEL || 'gpt-4.1-mini',
      input: [{ role: 'system', content: prompt }, { role: 'user', content: context.inboundText }],
      max_output_tokens: 450,
    }),
  })

  const data = await response.json().catch(() => ({}))
  if (!response.ok) return context.settings.fallback_message

  return String(data.output_text || '').trim() || context.settings.fallback_message
}

// ORCALY_OWNER_SUPPORT_CONTROL_V1
// ORCALY_PLATFORM_ADMIN_HARDENING_V1
import { createServerClient } from '@supabase/ssr'
import { NextRequest, NextResponse } from 'next/server'
import {
  applySecurityHeaders,
  isReservedSubdomain,
} from './lib/orcaly-security'
import { getRootDomain } from './lib/company-url'

type CookieToSet = {
  name: string
  value: string
  options?: any
}

function cleanHost(host: string) {
  return host.split(':')[0].toLowerCase()
}

function getSubdomain(
  hostname: string,
  rootDomain: string,
) {
  const host = cleanHost(hostname)

  if (host === rootDomain) return null
  if (host === `www.${rootDomain}`) return null

  if (host.endsWith(`.${rootDomain}`)) {
    return (
      host
        .replace(`.${rootDomain}`, '')
        .split('.')
        .pop() || null
    )
  }

  return null
}

function applyCookies(
  response: NextResponse,
  cookies: CookieToSet[],
) {
  for (const cookie of cookies) {
    response.cookies.set(
      cookie.name,
      cookie.value,
      cookie.options,
    )
  }

  return response
}

function secureResponse(
  response: NextResponse,
  request: NextRequest,
  cookies: CookieToSet[],
) {
  const secured = applySecurityHeaders(
    applyCookies(response, cookies),
    request,
  )
  const pathname = request.nextUrl.pathname
  const internalAdminResource =
    pathname === '/admin' ||
    pathname.startsWith('/admin/') ||
    pathname === '/api/admin' ||
    pathname.startsWith('/api/admin/') ||
    pathname === '/api/platform-admin' ||
    pathname.startsWith('/api/platform-admin/')

  if (internalAdminResource) {
    secured.headers.set(
      'Cache-Control',
      'private, no-store, no-cache, max-age=0, must-revalidate',
    )
    secured.headers.set('Pragma', 'no-cache')
    secured.headers.set('Expires', '0')
    secured.headers.set(
      'X-Robots-Tag',
      'noindex, nofollow, noarchive, nosnippet',
    )
  }

  return secured
}

function normalizedRole(value: unknown) {
  const role = String(value || '')
    .trim()
    .toLowerCase()

  if (role === 'super_admin') return 'owner'
  if (role === 'suporte') return 'support'
  return role
}

export async function proxy(request: NextRequest) {
  const url = request.nextUrl.clone()
  const pathname = url.pathname
  const host = request.headers.get('host') || ''
  const rootDomain = getRootDomain()
  const subdomain = getSubdomain(
    host,
    rootDomain,
  )

  const adminLoginPage =
    pathname === '/admin/login'
  const affiliateSensitivePage =
    pathname === '/parceiros/painel' ||
    pathname.startsWith('/parceiros/painel/')
  const adminSensitivePage =
    !adminLoginPage &&
    (pathname === '/admin' ||
      pathname.startsWith('/admin/'))
  const companySensitivePage =
    pathname === '/painel' ||
    pathname.startsWith('/painel/')
  const sensitivePage =
    adminSensitivePage ||
    affiliateSensitivePage ||
    companySensitivePage

  const cookiesToSet: CookieToSet[] = []

  if (sensitivePage) {
    const supabaseUrl =
      process.env.NEXT_PUBLIC_SUPABASE_URL
    const supabaseKey =
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

    if (!supabaseUrl || !supabaseKey) {
      return secureResponse(
        NextResponse.json(
          {
            error:
              'Autenticação indisponível.',
          },
          { status: 503 },
        ),
        request,
        cookiesToSet,
      )
    }

    const supabase = createServerClient(
      supabaseUrl,
      supabaseKey,
      {
        cookies: {
          getAll() {
            return request.cookies.getAll()
          },
          setAll(cookies) {
            for (const cookie of cookies) {
              request.cookies.set(
                cookie.name,
                cookie.value,
              )
              cookiesToSet.push(cookie)
            }
          },
        },
      },
    )

    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      const login = request.nextUrl.clone()

      login.pathname = adminSensitivePage
        ? '/admin/login'
        : affiliateSensitivePage
          ? '/parceiros/login'
          : '/login'
      login.searchParams.set(
        'next',
        `${pathname}${request.nextUrl.search}`,
      )

      return secureResponse(
        NextResponse.redirect(login),
        request,
        cookiesToSet,
      )
    }

    const tokenRole = normalizedRole(
      user.app_metadata?.orcaly_role,
    )

    if (adminSensitivePage) {
      const { data, error } = await supabase.rpc(
        'get_my_platform_admin_access',
      )
      const adminAccess = Array.isArray(data)
        ? data[0]
        : data
      const databaseRole = normalizedRole(
        adminAccess?.admin_role,
      )
      const allowedAdminRoles = new Set([
        'owner',
        'admin',
        'finance',
        'support',
      ])
      if (
        error ||
        adminAccess?.admin_is_active !== true ||
        !allowedAdminRoles.has(databaseRole)
      ) {
        const panel = request.nextUrl.clone()
        panel.pathname = '/painel/inicio'
        panel.search = ''

        return secureResponse(
          NextResponse.redirect(panel),
          request,
          cookiesToSet,
        )
      }

      if (
        adminAccess?.must_change_password === true &&
        pathname !== '/admin/alterar-senha'
      ) {
        const passwordPage =
          request.nextUrl.clone()
        passwordPage.pathname =
          '/admin/alterar-senha'
        passwordPage.search = ''

        return secureResponse(
          NextResponse.redirect(passwordPage),
          request,
          cookiesToSet,
        )
      }
    }

    if (
      affiliateSensitivePage &&
      tokenRole !== 'affiliate'
    ) {
      const login = request.nextUrl.clone()
      login.pathname = '/parceiros/login'
      login.search = ''

      return secureResponse(
        NextResponse.redirect(login),
        request,
        cookiesToSet,
      )
    }
  }

  // ORCALY_SUBDOMAIN_ROUTE_PASSTHROUGH_V1
  // Apenas a raiz do subdomínio representa a vitrine da empresa.
  // Rotas reais, como /checkout/[slug], devem seguir para o Next.js.
  const shouldRewriteSubdomain =
    subdomain &&
    !isReservedSubdomain(subdomain) &&
    pathname === '/'

  if (shouldRewriteSubdomain) {
    url.pathname = `/site/${subdomain}`

    return secureResponse(
      NextResponse.rewrite(url),
      request,
      cookiesToSet,
    )
  }

  return secureResponse(
    NextResponse.next({
      request,
    }),
    request,
    cookiesToSet,
  )
}

export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|robots.txt|sitemap.xml|.*\\.(?:png|jpg|jpeg|gif|webp|svg|ico|css|js|map|txt|xml|woff|woff2)$).*)',
  ],
}
